def pdf_to_images(pdf_path, tmpdir, dpi=200):
    """Turn each page of a PDF into a PNG (for import). Uses PyMuPDF if installed
    (renders any PDF), else falls back to extracting embedded images with pypdf
    (works for scanned PDFs). Returns a list of PNG paths."""
    out = []
    if HAS_FITZ:
        try:
            doc = fitz.open(pdf_path)
            zoom = dpi / 72.0
            mat = fitz.Matrix(zoom, zoom)
            for page in doc:
                pix = page.get_pixmap(matrix=mat)
                fd, png = tempfile.mkstemp(suffix=".png", dir=tmpdir); os.close(fd)
                pix.save(png)
                out.append(png)
            doc.close()
            if out:
                return out
        except Exception:
            out = []
    # fallback: pull the biggest embedded image from each page (scanned PDFs)
    try:
        from pypdf import PdfReader as _PR
        reader = _PR(pdf_path)
        for page in reader.pages:
            try:
                imgs = list(getattr(page, "images", []))
            except Exception:
                imgs = []
            if not imgs:
                continue
            big = max(imgs, key=lambda im: len(getattr(im, "data", b"")))
            fd, png = tempfile.mkstemp(suffix=".png", dir=tmpdir); os.close(fd)
            with open(png, "wb") as fh:
                fh.write(big.data)
            try:
                with Image.open(png) as im2:
                    im2.convert("RGB").save(png, "PNG")
            except Exception:
                pass
            out.append(png)
    except Exception:
        pass
    return out


def _configure_tesseract():
    """Point pytesseract at a Tesseract install even if it's not on PATH."""
    if not HAS_OCR_LIBS:
        return
    try:
        # (v205) BUNDLED Tesseract SABSE PEHLE — ab installer ke saath hi
        # aata hai ({app}\tesseract), user ko alag install nahi karna padta
        _exed = (os.path.dirname(os.path.abspath(sys.executable))
                 if getattr(sys, "frozen", False)
                 else os.path.dirname(os.path.abspath(__file__)))
        _bt = os.path.join(_exed, "tesseract", "tesseract.exe")
        if os.path.isfile(_bt):
            pytesseract.pytesseract.tesseract_cmd = _bt
            os.environ["TESSDATA_PREFIX"] = os.path.join(os.path.dirname(_bt), "tessdata")
            return
        home = os.path.expanduser("~")
        for c in (os.path.join(os.environ.get("LOCALAPPDATA", ""), "ApneScan",
                               "Tesseract", "tesseract.exe"),   # (v205) self-install
                  r"C:\Program Files\Tesseract-OCR\tesseract.exe",
                  r"C:\Program Files (x86)\Tesseract-OCR\tesseract.exe",
                  os.path.join(home, "AppData", "Local", "Tesseract-OCR", "tesseract.exe"),
                  os.path.join(home, "AppData", "Local", "Programs", "Tesseract-OCR", "tesseract.exe")):
            if os.path.exists(c):
                pytesseract.pytesseract.tesseract_cmd = c
                break
    except Exception:
        pass


_TESS_OK = None      # cache: get_tesseract_version() har baar tesseract.exe ko
                     # subprocess me chalata hai (~0.5-2s) — isse UI atak jati
                     # thi (khaaskar rename ke baad). Ek baar check, phir yaad.
def tesseract_available():
    global _TESS_OK
    if _TESS_OK is not None:
        return _TESS_OK
    if not HAS_OCR_LIBS:
        _TESS_OK = False
        return False
    try:
        pytesseract.get_tesseract_version()
        _TESS_OK = True
    except Exception:
        _TESS_OK = False
    return _TESS_OK


# Give the Smart Orientation engine the app's cached OCR-availability check, so
# it uses the exact same result as the rest of the app (no behaviour drift) while
# staying free of any import back into this file.
_orientation.tesseract_available = tesseract_available


_configure_tesseract()

