def app_icon():
    for n in ("apnescan.ico", "apnescan_icon.png"):
        p = resource_path(n)
        if os.path.exists(p):
            return QtGui.QIcon(p)
    # fallback: decode the embedded icon
    try:
        import base64 as _b64
        pm = QtGui.QPixmap()
        pm.loadFromData(_b64.b64decode(_EMBEDDED_ICON_B64))
        if not pm.isNull():
            return QtGui.QIcon(pm)
    except Exception:
        pass
    return QtGui.QIcon()


