def read_barcode(path):
    """Return first barcode/QR text found in the image, else None."""
    if not HAS_ZBAR:
        return None
    try:
        with Image.open(path) as im:
            results = _zbar_decode(im.convert("RGB"))
        for r in results:
            try:
                val = r.data.decode("utf-8").strip()
            except Exception:
                val = str(r.data).strip()
            if val:
                return val
        return None
    except Exception:
        return None


