class FlowLayout(QtWidgets.QLayout):
    """A left-to-right wrapping layout (the classic Qt example). Used by the
    redesigned Rename dialog so suggestion chips wrap to the next line instead
    of clipping — keeps the dialog responsive at any width."""

    def __init__(self, parent=None, margin=0, spacing=6):
        super().__init__(parent)
        if parent is not None:
            self.setContentsMargins(margin, margin, margin, margin)
        self.setSpacing(spacing)
        self._items = []

    def __del__(self):
        while self.count():
            self.takeAt(0)

    def addItem(self, item):
        self._items.append(item)

    def count(self):
        return len(self._items)

    def itemAt(self, i):
        return self._items[i] if 0 <= i < len(self._items) else None

    def takeAt(self, i):
        return self._items.pop(i) if 0 <= i < len(self._items) else None

    def expandingDirections(self):
        return QtCore.Qt.Orientations(QtCore.Qt.Orientation(0))

    def hasHeightForWidth(self):
        return True

    def heightForWidth(self, width):
        return self._do_layout(QtCore.QRect(0, 0, width, 0), True)

    def setGeometry(self, rect):
        super().setGeometry(rect)
        self._do_layout(rect, False)

    def sizeHint(self):
        return self.minimumSize()

    def minimumSize(self):
        size = QtCore.QSize()
        for item in self._items:
            size = size.expandedTo(item.minimumSize())
        m = self.contentsMargins()
        size += QtCore.QSize(m.left() + m.right(), m.top() + m.bottom())
        return size

    def _do_layout(self, rect, test_only):
        x, y = rect.x(), rect.y()
        line_h = 0
        space = self.spacing()
        for item in self._items:
            w = item.sizeHint().width()
            h = item.sizeHint().height()
            nx = x + w
            if nx - rect.x() > rect.width() and line_h > 0:
                x = rect.x()
                y = y + line_h + space
                nx = x + w
                line_h = 0
            if not test_only:
                item.setGeometry(QtCore.QRect(QtCore.QPoint(x, y), item.sizeHint()))
            x = nx + space
            line_h = max(line_h, h)
        return y + line_h - rect.y()


class TallItemDelegate(QtWidgets.QStyledItemDelegate):
    """Force a comfortable row height in a list/popup so text never clips at
    the bottom (used by the Rename dialog's suggestion dropdown)."""

    def __init__(self, parent=None, height=32):
        super().__init__(parent)
        self._h = height

    def sizeHint(self, opt, idx):
        s = super().sizeHint(opt, idx)
        s.setHeight(max(self._h, s.height()))
        return s


# Role that carries the usage-count on a suggestion item.
SUGG_COUNT_ROLE = int(QtCore.Qt.UserRole) + 20


class SuggestCountDelegate(QtWidgets.QStyledItemDelegate):
    """Rename dropdown row: document name on the LEFT, its usage count as a
    small pill on the RIGHT — full name never clipped, comfortable height."""

    def __init__(self, parent=None, height=34):
        super().__init__(parent)
        self._h = height

    def sizeHint(self, opt, idx):
        s = super().sizeHint(opt, idx)
        s.setHeight(max(self._h, s.height()))
        return s

    def paint(self, painter, option, index):
        opt = QtWidgets.QStyleOptionViewItem(option)
        self.initStyleOption(opt, index)
        name = opt.text or ""
        opt.text = ""
        style = opt.widget.style() if opt.widget else QtWidgets.QApplication.style()
        style.drawControl(QtWidgets.QStyle.CE_ItemViewItem, opt, painter, opt.widget)
        sel = bool(opt.state & QtWidgets.QStyle.State_Selected)
        cnt = index.data(SUGG_COUNT_ROLE)
        cnt_str = ""
        try:
            if cnt is not None and int(cnt) > 0:
                cnt_str = str(int(cnt))
        except Exception:
            cnt_str = ""
        painter.save()
        fm = painter.fontMetrics()
        r = opt.rect.adjusted(13, 0, -12, 0)
        pill_w = 0
        if cnt_str:
            try:
                tw = fm.horizontalAdvance(cnt_str)
            except Exception:
                tw = fm.width(cnt_str)
            pill_w = max(22, tw + 14)
            pr = QtCore.QRect(r.right() - pill_w, r.top() + (r.height() - 20) // 2,
                              pill_w, 20)
            painter.setRenderHint(QtGui.QPainter.Antialiasing, True)
            painter.setPen(QtCore.Qt.NoPen)
            painter.setBrush(QtGui.QColor("#E7E1FF" if sel else "#F0EEFB"))
            painter.drawRoundedRect(pr, 10, 10)
            painter.setPen(QtGui.QColor("#6A5AE0"))
            f = painter.font(); f.setPointSizeF(max(8.0, f.pointSizeF() - 1)); f.setBold(True)
            painter.setFont(f)
            painter.drawText(pr, QtCore.Qt.AlignCenter, cnt_str)
            painter.setFont(opt.font)
        name_rect = QtCore.QRect(r.left(), r.top(),
                                 r.width() - (pill_w + 10 if pill_w else 0), r.height())
        painter.setPen(QtGui.QColor("#4A3FB0" if sel else "#1F2340"))
        elided = fm.elidedText(name, QtCore.Qt.ElideRight, name_rect.width())
        painter.drawText(name_rect, QtCore.Qt.AlignVCenter | QtCore.Qt.AlignLeft, elided)
        painter.restore()


class NameWorker(QtCore.QThread):
    named = QtCore.pyqtSignal(int, str)   # (row, title)
    finished_all = QtCore.pyqtSignal()

    def __init__(self, items, learned=None):
        super().__init__()
        self.items = items                # list of (row, path)
        self.learned = learned or []      # list of (wordset, name)

    def run(self):
        for row, path in self.items:
            if self.isInterruptionRequested():
                break
            text = page_ocr_text(path, 0.6)
            # priority: name YOU taught it > document-type > printed heading
            title = (learned_name_for(text, self.learned)
                     or classify_from_text(text)
                     or ocr_page_title(path))
            if title:
                self.named.emit(row, title)
        self.finished_all.emit()


class FuncWorker(QtCore.QThread):
    """Koi bhi bhaari kaam (OCR/network) background me chala kar result de —
    UI kabhi nahi rukti. Result ya Exception, dono `done` signal me aate hain."""
    done = QtCore.pyqtSignal(object)

    def __init__(self, fn):
        super().__init__()
        self.fn = fn

    def run(self):
        try:
            self.done.emit(self.fn())
        except Exception as e:
            self.done.emit(e)


class LearnWorker(QtCore.QThread):
    """Rename ke baad naam 'seekhne' ka OCR background me — pehle ye UI thread
    par chalta tha aur har rename par app 3-10 second jam jaati thi."""
    got = QtCore.pyqtSignal(str, list)   # (name, words)

    def __init__(self, path, name):
        super().__init__()
        self.path = path
        self.name = name

    def run(self):
        try:
            # Zyada text (0.75) padho taaki form ka signature bharpoor bane —
            # naam yaad rakhna jitna bharpoor, utna reliable.
            words = sorted(sig_words(page_ocr_text(self.path, 0.75)))
        except Exception:
            words = []
        self.got.emit(self.name, words)


class ImportWorker(QtCore.QThread):
    """Import (images/PDF/photo-cleanup) background me — UI kabhi nahi rukti.
    Thumbnail bhi yahin chhota (QImage worker thread me safe hai)."""
    page_ready = QtCore.pyqtSignal(str, QtGui.QImage)
    done = QtCore.pyqtSignal(int)

    def __init__(self, files, tmpdir, mode="normal", thumb_w=360, thumb_h=480):
        super().__init__()
        self.files = list(files)
        self.tmpdir = tmpdir
        self.mode = mode          # "normal" ya "photo" (phone-photo cleanup)
        self.thumb_w = thumb_w
        self.thumb_h = thumb_h

    def _thumb(self, path):
        r = QtGui.QImageReader(path)
        r.setAutoTransform(True)
        sz = r.size()
        if sz.isValid() and sz.width() > 0 and sz.height() > 0:
            s = min(float(self.thumb_w) / sz.width(),
                    float(self.thumb_h) / sz.height(), 1.0)
            r.setScaledSize(QtCore.QSize(max(1, int(sz.width() * s)),
                                         max(1, int(sz.height() * s))))
        return r.read()

    def run(self):
        count = 0
        for f in self.files:
            if self.isInterruptionRequested():
                break
            try:
                if self.mode == "photo":
                    # (v211) photo → scan-jaisa: perspective + shadow + rang
                    # wapsi + enhance + denoise — sab ek saath
                    with Image.open(f) as im:
                        img = ai_photo_to_scan(im)
                    fd, out = tempfile.mkstemp(suffix=".jpg", dir=self.tmpdir)
                    os.close(fd)
                    img.save(out, "JPEG", quality=90)
                    outs = [out]
                elif f.lower().endswith(".pdf"):
                    outs = pdf_to_images(f, self.tmpdir) or []
                else:
                    with Image.open(f) as im:
                        fd, out = tempfile.mkstemp(suffix=".png", dir=self.tmpdir)
                        os.close(fd)
                        im.convert("RGB").save(out, "PNG")
                    outs = [out]
                for p in outs:
                    count += 1
                    self.page_ready.emit(p, self._thumb(p))
            except Exception:
                pass
        self.done.emit(count)


class ScanWorker(QtCore.QThread):
    page_done = QtCore.pyqtSignal(str)
    done = QtCore.pyqtSignal(int, int)
    failed = QtCore.pyqtSignal(str)
    stage = QtCore.pyqtSignal(str)      # F16: live processing-stage updates
    # (v310) Part 1 — scan-dialog ke live thumbnail/counter ke liye (purane
    # signals ko chhua nahi; ye SIRF UI dikhane ke liye extra hain):
    page_ready = QtCore.pyqtSignal(str, int, int, str)   # (path, kept, skipped, title)
    page_dropped = QtCore.pyqtSignal(int, str)           # (skipped_total, reason)

    def __init__(self, hwnd, source_name, dpi, pixel_type, duplex, tmpdir, opts):
        super().__init__()
        self.hwnd = hwnd
        self.source_name = source_name
        self.dpi = dpi
        self.pixel_type = pixel_type
        self.duplex = duplex
        self.tmpdir = tmpdir
        self.opts = opts or {}
        self.kept = 0
        self.skipped = 0

    def run(self):
        import queue as _q, threading as _th
        pageq = _q.Queue()

        def _consumer():
            # Runs in parallel: saves/processes each page while the scanner
            # is already pulling the NEXT one (this removes the per-page pause).
            while True:
                img = pageq.get()
                if img is None:
                    break
                try:
                    self.stage.emit("processing")   # F16: live processing stage
                    # (v308) ORIGINAL COLOUR (jaisa hai waisa): rangeen page ka
                    # rang/tone bilkul na badle — vivid/white-balance, auto-gray,
                    # flatten, enhance, HD-clear, adaptive-BW sab CHHOD do. Sirf
                    # sidha-karna/crop (geometry) chalega, jo rang nahi chhoota.
                    _true = bool(self.opts.get("true_colour"))
                    if self.opts.get("remove_blank"):
                        _sens = {"kam": 0.0003, "normal": 0.0008, "zyada": 0.004}
                        _thr = _sens.get(self.opts.get("blank_sensitivity", "normal"), 0.0008)
                        if is_blank_page(img, _thr):
                            self.skipped += 1
                            try:
                                self.page_dropped.emit(self.skipped, "blank")
                            except Exception:
                                pass
                            continue
                    # (v240) ADF ki dark/gray backing (choti sheet ke SIDE/NECHE
                    # dikhne wali patti) ko GRAY ki jagah WHITE karo — user ki
                    # maang. whiten_outside_paper: paper ka kinara bright-FRACTION
                    # se pehchan kar sirf paper ke BAHAR ki backing white karta hai
                    # (page ka size same). Isliye niche ki laal/halki address-line
                    # (jo paper ke ANDAR hai) NAHI udti — purana pixel-whiten use
                    # bhi uda deta tha. Bhari/normal page par no-op.
                    #   backing_mode: "white" (default) / "crop" / "off"
                    _bm = self.opts.get("backing_mode", "crop")
                    if self.opts.get("auto_trim_backing", True) and _bm != "off":
                        if _bm == "crop":
                            img = trim_scanner_backing(img)      # kaat kar hatao
                        else:
                            img = whiten_outside_paper(img)      # gray -> WHITE
                    elif self.opts.get("auto_whiten_backing", False):
                        img = whiten_dark_background(img)
                    # Photocopy jaisi GRAY-maili background asli safed karo
                    # (streak/shading bhi) — text gehra, print/PDF ekdam saaf.
                    # Photo/X-ray par apne aap no-op. Settings se band ho
                    # sakta hai (auto_flatten).
                    if self.opts.get("auto_flatten", False) and not _true:
                        img = flatten_background(img)
                    # (v245) NAPS2-MATCH: gray-maile/feeke scan -> naps2_levels:
                    # background CLEAN-WHITE + text DEEP-BLACK (NAPS2 jaisa). white-
                    # point levels stretch — faint line nahi udti, rangeen header/
                    # mohar nahi dhulte (test: mean 224->240, p50 255, faint 0%
                    # washed). (v244 me ye SIRF eSCL par tha — galti: ApneScan ka
                    # WIA output BHI grayish nikla, NAPS2-WIA jaisa whiten nahi hota.
                    # Isliye ab HAR method par — function adaptive hai, pehle se
                    # safed page par apne aap NO-OP.) Colour/gray par (B&W ka apna
                    # threshold), aur tab nahi jab user ne khud koi enhance chuna ho.
                    _manual_enh = (self.opts.get("auto_flatten", False)
                                   or self.opts.get("quality_enhance")
                                   or self.opts.get("smart_scan")
                                   or (self.opts.get("enhance_mode", "original")
                                       not in ("original", "", None)))
                    if (self.opts.get("auto_vivid", True)
                            and self.pixel_type != "bw" and not _manual_enh and not _true):
                        img = naps2_levels(img)
                    # ---- Smart Orientation = FIRST processing stage (spec) ----
                    # Har page ko sabse pehle seedha karo taaki aage ke sab stage
                    # (crop/deskew/enhance) + thumbnail/OCR/PDF sahi orientation par chalein.
                    if self.opts.get("auto_orient", True):
                        img = auto_orient(
                            img, mode=self.opts.get("auto_orient_mode", "accurate"),
                            deskew_small=bool(self.opts.get("auto_orient_deskew")),
                            threshold=int(self.opts.get("auto_orient_conf", 80) or 80),
                            ocr_based=bool(self.opts.get("auto_orient_ocr", True)),
                            text_based=bool(self.opts.get("auto_orient_cv", True)),
                            layout_based=bool(self.opts.get("auto_orient_layout", True)),
                            page_label="page %d" % (self.kept + 1))
                        # (v204) ginti: is scan me kitne pages ghumaye gaye —
                        # scan ke baad user ko status me dikhta hai
                        try:
                            _lr = getattr(auto_orient, "last", None) or {}
                            self.orient_tot = getattr(self, "orient_tot", 0) + 1
                            if _lr.get("decision") == "rotate":
                                self.orient_rot = getattr(self, "orient_rot", 0) + 1
                        except Exception:
                            pass
                    # F15 Smart Scan: one toggle turns on the recommended cleanup set
                    _smart = bool(self.opts.get("smart_scan"))
                    if self.opts.get("clean_edges") or _smart:
                        img = clean_edges(img)
                    if self.opts.get("auto_crop") or _smart:
                        img = autocrop(img)
                    if self.opts.get("deskew") or _smart:
                        img = deskew(img)
                    if self.opts.get("quality_enhance") and not _true:
                        img = auto_enhance(img)
                    # F5 background-enhancement mode (Original/White/Enhanced/High-Contrast);
                    # Smart Scan defaults it to 'enhanced' when left on Original.
                    _mode = self.opts.get("enhance_mode", "original")
                    if _smart and _mode == "original":
                        _mode = "enhanced"
                    if _mode and _mode != "original" and not _true:
                        img = apply_enhance_mode(img, _mode)
                    if self.opts.get("noise_removal") or _smart:   # F8 denoise
                        img = denoise(img)
                    # (v306) HD-CLEAR: har scan ko crisp/saaf banao (text/line/mohar
                    # ubhre) — file size lagbhag same. (v309) True-colour me BHI chalta
                    # hai: sharpen sirf tez/crisp karta hai, RANG nahi badalta.
                    if self.opts.get("hd_clear", True):
                        try:
                            img = sharpen_clarity(img)
                        except Exception:
                            pass
                    # (v211) QUALITY CHOWKIDAAR: kamzor page turant pakdo —
                    # scan khatam hote hi user ko page-number ke saath chetavni
                    if self.opts.get("quality_watch", True):
                        try:
                            _qi = ai_scan_quality(img)
                            if _qi:
                                if not hasattr(self, "q_warns"):
                                    self.q_warns = []
                                self.q_warns.append((self.kept + 1, _qi))
                        except Exception:
                            pass
                    # Rang-heen page ko gray bana do (chhoti file) — sirf colour
                    # scan me, aur sirf jab option ON ho.
                    if (self.opts.get("auto_colour") and self.pixel_type == "color"
                            and not _true and not has_real_colour(img)):
                        img = img.convert("L")   # sach me rang-heen page hi gray
                    # Ek glass par do page → do alag page (option ON ho to)
                    if self.opts.get("split_two_page"):
                        parts = split_two_pages(img)
                    else:
                        parts = [img]
                    self.stage.emit("saving")
                    for _pi in parts:
                        self._save_and_emit(_pi)
                except Exception:
                    pass

        def _save_and_emit(im):
            # Ek image ko temp file me save karke UI ko bhejo. JPEG encode ~5x
            # tez (bade scan me speed) — colour/grey ke liye JPEG, 1-bit B&W ke
            # liye PNG. HD: master pages quality 95 par rakhe jaate hain (yahi
            # se print/PDF bante hain — compress sirf PDF banate waqt hota hai)
            # + dpi metadata, taaki PDF me page ka asli size sahi bane.
            try:
                _d = int(self.dpi)
            except Exception:
                _d = 200
            # NAPS2-PARITY: page apni ASLI resolution par, BINA kisi
            # sharpening ke save hota hai — NAPS2 bhi scan-data ko waise ka
            # waisa rakhta hai (koi filter nahi). Pehle yahan unsharp lagta
            # tha jo JPEG ko 25-35% phula deta tha; print ki 'dhaar' waise
            # bhi PRINT ke waqt aati hai (_draw_fit ka smooth upscale).
            # Sirf B&W me upscale+unsharp RAKHA hai — wahan Sauvola threshold
            # ke kinare smooth bante hain aur 1-bit file ~20KB hi rehti hai.
            if 0 < _d < 300 and im.mode != "1" and self.pixel_type == "bw":
                try:
                    _sc = min(2.0, 300.0 / _d)
                    im = im.resize((max(1, int(im.width * _sc)),
                                    max(1, int(im.height * _sc))),
                                   Image.LANCZOS)
                    _d = int(round(_d * _sc))
                    im = im.filter(ImageFilter.UnsharpMask(
                        radius=2, percent=110, threshold=3))
                except Exception:
                    pass
            _dpi = (_d, _d)
            # User ne Grayscale chuna ho to file PAKKI gray bane — kuch driver
            # (jaise HP WIA) gray maangne par bhi colour dete hain; unki
            # colour-tint (pink cast) bhi isi se khatam ho jaati hai.
            if self.pixel_type == "gray" and im.mode not in ("L", "1"):
                try:
                    im = im.convert("L")
                except Exception:
                    pass
            if self.pixel_type == "bw":
                fd, out = tempfile.mkstemp(suffix=".png", dir=self.tmpdir)
                os.close(fd)
                try:
                    if im.mode != "1":
                        # Sauvola adaptive threshold — patle akshar/halki
                        # syahi surakshit, pure white bg (fallback: global 160)
                        im = adaptive_bw(im)
                except Exception:
                    pass
                try:
                    im.save(out, "PNG", compress_level=1, dpi=_dpi)
                except Exception:
                    im.save(out, "PNG")
            else:
                fd, out = tempfile.mkstemp(suffix=".jpg", dir=self.tmpdir)
                os.close(fd)
                try:
                    # (v237) NAPS2 jaisa: master q90 (NAPS2 q75 se behtar, par
                    # v232 wale q95+4:4:4 se KAAFI chhota — file bahut badi ho
                    # rahi thi). Normal subsampling (NAPS2 bhi wahi).
                    if im.mode == "L":
                        im.save(out, "JPEG", quality=90, dpi=_dpi)
                    else:
                        im.convert("RGB").save(out, "JPEG", quality=90, dpi=_dpi)
                except Exception:
                    im.convert("RGB").save(out, "JPEG", quality=90)
            self.kept += 1
            self.page_done.emit(out)
            # (v310) dialog ke live thumbnail + counter ke liye (naam abhi nahi
            # bana — OCR naming baad me hota hai, isliye title khaali)
            try:
                self.page_ready.emit(out, self.kept, self.skipped, "")
            except Exception:
                pass
        self._save_and_emit = _save_and_emit

        consumer = _th.Thread(target=_consumer, daemon=True)
        consumer.start()

        def _on_page(img):
            # Producer: hand the page off instantly and let the scanner keep going.
            pageq.put(img)

        err = None
        method = self.opts.get("scanner_method", "twain")
        # (v235) SIRF scanner-acquire ka samay naapo (consumer parallel chalta
        # hai, isliye ye WIA/eSCL/TWAIN ki asli raftaar hai — hamare OCR/process
        # ka samay ismein nahi aata). Isi se 'WIA dheema?' faisla hota hai.
        _t_acq0 = time.time()
        try:
            _ps = str(self.opts.get("page_size", "auto"))
            if _ps.startswith("custom"):
                _ps = "custom:%d" % int(self.opts.get("custom_page_mm", 600) or 600)
            if method == "escl":
                scan_via_escl(self.opts.get("scanner_ip"), self.dpi, self.pixel_type,
                              self.duplex, _on_page, should_stop=self.isInterruptionRequested,
                              page_size=_ps)
            elif method == "naps2":
                scan_via_naps2(self.opts.get("naps2_path") or find_naps2(),
                               self.opts.get("naps2_profile"), self.tmpdir,
                               self.duplex, _on_page,
                               should_stop=self.isInterruptionRequested)
            elif method == "wia":
                try:
                    _pythoncom.CoInitialize()
                except Exception:
                    pass
                try:
                    wia_scan_pages(self.opts.get("wia_device_id"), self.dpi,
                                   self.pixel_type, self.duplex, _on_page,
                                   should_stop=self.isInterruptionRequested,
                                   source=self.opts.get("paper_source", "auto"),
                                   page_size=self.opts.get("page_size", "auto"),
                                   best_quality=self.opts.get("scan_best_quality", True))
                finally:
                    try:
                        _pythoncom.CoUninitialize()
                    except Exception:
                        pass
            else:
                scan_pages(self.hwnd, self.source_name, self.dpi,
                           self.pixel_type, self.duplex, _on_page,
                           should_stop=self.isInterruptionRequested,
                           file_xfer=bool(self.opts.get("twain_file_xfer")))
        except ScannerError as exc:
            err = str(exc)
        except Exception:
            err = "Scan error:\n%s" % traceback.format_exc()
        try:
            self.acquire_secs = max(0.0, time.time() - _t_acq0)
        except Exception:
            self.acquire_secs = 0.0

        pageq.put(None)            # tell the saver thread to finish
        consumer.join(timeout=60)  # wait until all pages are saved

        if err is not None and self.kept == 0:
            self.failed.emit(err)
            return
        if self.kept == 0 and self.skipped == 0:
            self.failed.emit(err or 'No page was scanned.')
            return
        self.done.emit(self.kept, self.skipped)


