class RelayPoller(QtCore.QObject):
    """Internet phone-session ka PC-side engine: har kuchh second me server
    se poochta hai; nayi file aate hi utaar leta hai (server se turant delete
    ho jaati hai) aur signal deta hai. Saara network-kaam alag thread me —
    UI kabhi nahi atakti. (Suraksha: KEY sirf is PC ke paas — QR me nahi.)"""
    file_got = QtCore.pyqtSignal(str, str)    # (local_path, original_name)
    info = QtCore.pyqtSignal(object)          # status dict / {"ok":0,"net":1}

    def __init__(self, base, token, key, tmpdir, parent=None):
        super().__init__(parent)
        self.base, self.token, self.key = base, token, key
        self.tmpdir = tmpdir
        self._busy = False
        self.stopped = False

    def poll(self):
        if self._busy or self.stopped:
            return
        self._busy = True
        threading.Thread(target=self._work, daemon=True).start()

    def _work(self):
        try:
            st = _relay.status(self.base, self.token, self.key)
            if not self.stopped:
                self.info.emit(st)
            for f in (st.get("files") or []):
                if self.stopped:
                    break
                try:
                    p = _relay.take(self.base, self.token, self.key,
                                    f.get("id", ""), f.get("name", ""), self.tmpdir)
                    self.file_got.emit(p, f.get("name", ""))
                except Exception:
                    pass
        except Exception:
            if not self.stopped:
                self.info.emit({"ok": 0, "net": 1})
        finally:
            self._busy = False

    def shutdown(self):
        """Session band — server par bachi files + session delete (bg me)."""
        self.stopped = True
        threading.Thread(
            target=lambda: _relay.stop(self.base, self.token, self.key),
            daemon=True).start()


class PhoneServer(QtCore.QObject):
    """Local web-server (background thread) — phone se photo PC par laata hai."""
    photo = QtCore.pyqtSignal(str)          # aayi hui photo ka temp path

    def __init__(self, tmpdir, parent=None):
        super().__init__(parent)
        self._tmpdir = tmpdir
        self._httpd = None
        self._thread = None
        import secrets
        self.token = secrets.token_urlsafe(8)

    def lan_ip(self):
        import socket
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        ip = "127.0.0.1"
        try:
            s.connect(("8.8.8.8", 80)); ip = s.getsockname()[0]
        except Exception:
            pass
        finally:
            try: s.close()
            except Exception: pass
        return ip

    def start(self):
        import http.server, socketserver, threading, tempfile, os
        from urllib.parse import urlparse, parse_qs
        outer = self

        class H(http.server.BaseHTTPRequestHandler):
            def log_message(self, *a):
                pass

            def do_GET(self):
                q = parse_qs(urlparse(self.path).query)
                if q.get("t", [""])[0] != outer.token:
                    self.send_response(403); self.end_headers()
                    self.wfile.write(b"bad token"); return
                html = _PHONE_PAGE.replace("__TOKEN__", outer.token).encode("utf-8")
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(html)))
                self.end_headers(); self.wfile.write(html)

            def do_POST(self):
                q = parse_qs(urlparse(self.path).query)
                if q.get("t", [""])[0] != outer.token:
                    self.send_response(403); self.end_headers(); return
                length = int(self.headers.get("Content-Length") or 0)
                if length <= 0 or length > 40 * 1024 * 1024:
                    self.send_response(400); self.end_headers(); return
                data = self.rfile.read(length)
                try:
                    fd, tmp = tempfile.mkstemp(suffix=".jpg", dir=outer._tmpdir); os.close(fd)
                    with open(tmp, "wb") as fh:
                        fh.write(data)
                    outer.photo.emit(tmp)          # main thread me queued
                    self.send_response(200)
                    self.send_header("Access-Control-Allow-Origin", "*")
                    self.end_headers(); self.wfile.write(b"ok")
                except Exception:
                    self.send_response(500); self.end_headers()

        httpd = socketserver.ThreadingTCPServer(("0.0.0.0", 0), H)
        httpd.daemon_threads = True
        self._httpd = httpd
        port = httpd.server_address[1]
        self._thread = threading.Thread(target=httpd.serve_forever, daemon=True)
        self._thread.start()
        return self.lan_ip(), port

    def stop(self):
        try:
            if self._httpd:
                self._httpd.shutdown(); self._httpd.server_close()
        except Exception:
            pass
        self._httpd = None


# ============================================================================
#  AI DOCUMENT MEMORY (offline)  —  SQLite-backed learning system
#  Upgrade of the older JSON name-memory. 100% on-device: no cloud, no
#  internet, no external AI. Remembers every scanned document (OCR text,
#  image fingerprints, barcode/QR, keywords, folder, full name history) and
#  matches new scans to auto-suggest the LATEST filename + folder. Scales to
#  1M+ documents; a match normally completes in a few milliseconds.
# ============================================================================

# Fingerprint engine (_dm_* helpers) moved to apnescan_lib/fingerprint.py (imported at top).


# Intelligent Naming Engine moved to apnescan_lib/naming_engine.py (imported at top).


class DocMemory(object):
    """Offline learning memory. Thread-safe. See module banner above."""

    def __init__(self, path):
        self.path = path
        self._lock = threading.RLock()
        self._db = None
        self.fts = False
        self._open()

    # --- lifecycle ---
    def _open(self):
        try:
            self._db = sqlite3.connect(self.path, check_same_thread=False, timeout=8)
            self._db.row_factory = sqlite3.Row
            self._db.execute("PRAGMA journal_mode=WAL")
            self._db.execute("PRAGMA synchronous=NORMAL")
            self._db.execute("PRAGMA temp_store=MEMORY")
            self._init_schema()
        except Exception:
            self._db = None

    def ok(self):
        return self._db is not None

    def close(self):
        with self._lock:
            try:
                if self._db:
                    self._db.close()
            except Exception:
                pass
            self._db = None

    def _init_schema(self):
        c = self._db
        c.executescript("""
        CREATE TABLE IF NOT EXISTS docs(
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          ocr_text TEXT DEFAULT '', ocr_hash TEXT DEFAULT '',
          phash TEXT DEFAULT '', dhash TEXT DEFAULT '', ahash TEXT DEFAULT '',
          doc_type TEXT DEFAULT '', filename TEXT DEFAULT '', folder TEXT DEFAULT '',
          scan_date INTEGER DEFAULT 0, modified_date INTEGER DEFAULT 0,
          last_used INTEGER DEFAULT 0, usage_count INTEGER DEFAULT 1,
          ocr_conf REAL DEFAULT 0, barcode TEXT DEFAULT '', qrcode TEXT DEFAULT '',
          keywords TEXT DEFAULT '', tags TEXT DEFAULT '',
          file_size INTEGER DEFAULT 0, page_count INTEGER DEFAULT 0,
          scanner_model TEXT DEFAULT '', resolution TEXT DEFAULT '', color_mode TEXT DEFAULT '',
          document_version INTEGER DEFAULT 1
        );
        CREATE INDEX IF NOT EXISTS ix_docs_phash ON docs(phash);
        CREATE INDEX IF NOT EXISTS ix_docs_dhash ON docs(dhash);
        CREATE INDEX IF NOT EXISTS ix_docs_ocrhash ON docs(ocr_hash);
        CREATE INDEX IF NOT EXISTS ix_docs_barcode ON docs(barcode);
        CREATE INDEX IF NOT EXISTS ix_docs_qrcode ON docs(qrcode);
        CREATE INDEX IF NOT EXISTS ix_docs_type ON docs(doc_type);
        CREATE INDEX IF NOT EXISTS ix_docs_last ON docs(last_used);
        CREATE TABLE IF NOT EXISTS names(
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          doc_id INTEGER, filename TEXT, folder TEXT DEFAULT '',
          created INTEGER DEFAULT 0, last_used INTEGER DEFAULT 0, usage_count INTEGER DEFAULT 1
        );
        CREATE INDEX IF NOT EXISTS ix_names_doc ON names(doc_id);
        CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT);
        CREATE TABLE IF NOT EXISTS corrections(wrong TEXT PRIMARY KEY, correct TEXT, count INTEGER DEFAULT 1);
        """)
        try:
            c.execute("""CREATE VIRTUAL TABLE IF NOT EXISTS search USING fts5(
                ocr_text, filename, keywords, barcode, qrcode, folder, tags, doc_type)""")
            self.fts = True
        except Exception:
            self.fts = False
        self._ensure_columns()
        c.commit()

    def _ensure_columns(self):
        """Add any newer columns to an older DB (backward-compatible migration)."""
        try:
            have = {r[1] for r in self._db.execute("PRAGMA table_info(docs)").fetchall()}
            for col, ddl in (("document_version", "document_version INTEGER DEFAULT 1"),):
                if col not in have:
                    try:
                        self._db.execute("ALTER TABLE docs ADD COLUMN " + ddl)
                    except Exception:
                        pass
        except Exception:
            pass

    # --- meta ---
    def _mget(self, k, d=None):
        try:
            r = self._db.execute("SELECT v FROM meta WHERE k=?", (k,)).fetchone()
            return r["v"] if r else d
        except Exception:
            return d

    def _mset(self, k, v):
        try:
            self._db.execute("INSERT INTO meta(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=?", (k, str(v), str(v)))
        except Exception:
            pass

    # --- write path ---
    def remember(self, f):
        """Insert or update a document from a features dict. Dedupes by strong
        indexed signals. Returns (doc_id, is_new). Never raises."""
        if not self.ok():
            return (None, False)
        with self._lock:
            try:
                now = int(time.time())
                same = self._find_same(f)
                if same:
                    self._touch_update(same["id"], f, now)
                    return (same["id"], False)
                kw = f.get("keywords")
                if isinstance(kw, (list, tuple)):
                    kw = " ".join(str(x) for x in kw)
                if not kw:
                    kw = " ".join(_dm_keywords(f.get("ocr_text", "")))
                cur = self._db.execute(
                    """INSERT INTO docs(ocr_text,ocr_hash,phash,dhash,ahash,doc_type,filename,folder,
                       scan_date,modified_date,last_used,usage_count,ocr_conf,barcode,qrcode,keywords,tags,
                       file_size,page_count,scanner_model,resolution,color_mode)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (f.get("ocr_text", "")[:20000], f.get("ocr_hash", "") or _dm_text_hash(f.get("ocr_text", "")),
                     f.get("phash", ""), f.get("dhash", ""), f.get("ahash", ""), f.get("doc_type", ""),
                     f.get("filename", ""), f.get("folder", ""), now, now, now, 1,
                     float(f.get("ocr_conf", 0) or 0), f.get("barcode", ""), f.get("qrcode", ""),
                     kw, f.get("tags", ""), int(f.get("file_size", 0) or 0), int(f.get("page_count", 0) or 0),
                     f.get("scanner_model", ""), f.get("resolution", ""), f.get("color_mode", "")))
                did = cur.lastrowid
                if f.get("filename"):
                    self._db.execute("INSERT INTO names(doc_id,filename,folder,created,last_used,usage_count) VALUES(?,?,?,?,?,1)",
                                     (did, f.get("filename"), f.get("folder", ""), now, now))
                self._reindex_row(did)
                self._db.commit()
                return (did, True)
            except Exception:
                return (None, False)

    def _find_same(self, f):
        """Same-document dedup using only INDEXED exact signals (O(log N))."""
        db = self._db
        oh = f.get("ocr_hash", "") or _dm_text_hash(f.get("ocr_text", ""))
        for col, val in (("barcode", f.get("barcode", "")), ("qrcode", f.get("qrcode", "")),
                         ("ocr_hash", oh), ("phash", f.get("phash", ""))):
            if val:
                r = db.execute("SELECT * FROM docs WHERE %s=? LIMIT 1" % col, (val,)).fetchone()
                if r:
                    return r
        return None

    def _touch_update(self, did, f, now):
        self._db.execute("UPDATE docs SET last_used=?, usage_count=usage_count+1 WHERE id=?", (now, did))
        for col in ("phash", "dhash", "ahash", "barcode", "qrcode"):
            val = f.get(col, "")
            if val:
                self._db.execute("UPDATE docs SET %s=? WHERE id=? AND (%s='' OR %s IS NULL)" % (col, col, col), (val, did))
        self._reindex_row(did)
        self._db.commit()

    # --- learning (silent rename) ---
    def learn_rename(self, doc_id, new_name, folder=None):
        """User changed the name -> learn it as the LATEST. Never deletes history."""
        if not self.ok() or not doc_id or not new_name:
            return
        with self._lock:
            try:
                now = int(time.time())
                row = self._db.execute("SELECT id FROM names WHERE doc_id=? AND filename=? ORDER BY id DESC LIMIT 1",
                                       (doc_id, new_name)).fetchone()
                if row:
                    self._db.execute("UPDATE names SET last_used=?, usage_count=usage_count+1 WHERE id=?", (now, row["id"]))
                    bump_ver = ""     # same name reused -> not a new version
                else:
                    self._db.execute("INSERT INTO names(doc_id,filename,folder,created,last_used,usage_count) VALUES(?,?,?,?,?,1)",
                                     (doc_id, new_name, folder or "", now, now))
                    bump_ver = ", document_version=document_version+1"   # a genuinely new name
                if folder:
                    self._db.execute("UPDATE docs SET filename=?, folder=?, modified_date=?, last_used=?%s WHERE id=?" % bump_ver,
                                     (new_name, folder, now, now, doc_id))
                else:
                    self._db.execute("UPDATE docs SET filename=?, modified_date=?, last_used=?%s WHERE id=?" % bump_ver,
                                     (new_name, now, now, doc_id))
                self._reindex_row(doc_id)
                self._db.commit()
            except Exception:
                pass

    # --- matching ---
    def match(self, f, limit=6):
        """Return {'best':row,'confidence':0..100,'similar':[...]}. Combines
        OCR/image/keyword/barcode/QR/layout signals into one score."""
        out = {"best": None, "confidence": 0, "similar": []}
        if not self.ok():
            return out
        with self._lock:
            try:
                scored = []
                for r in self._candidates(f):
                    sc, parts = self._score(f, r)
                    if sc > 0:
                        scored.append((sc, r, parts))
                scored.sort(key=lambda x: -x[0])
                if scored:
                    out["best"] = scored[0][1]
                    out["confidence"] = scored[0][0]
                    out["similar"] = [{"id": r["id"], "name": self.latest_name(r["id"]) or r["filename"],
                                       "folder": r["folder"], "confidence": sc, "parts": parts,
                                       "doc_type": r["doc_type"], "last_used": r["last_used"]}
                                      for sc, r, parts in scored[:limit]]
                return out
            except Exception:
                return out

    def _candidates(self, f, cap=250):
        db = self._db
        seen, cands = set(), []

        def _add(rows):
            for r in rows:
                if r["id"] not in seen:
                    seen.add(r["id"])
                    cands.append(r)

        if f.get("barcode"):
            _add(db.execute("SELECT * FROM docs WHERE barcode=?", (f.get("barcode"),)).fetchall())
        if f.get("qrcode"):
            _add(db.execute("SELECT * FROM docs WHERE qrcode=?", (f.get("qrcode"),)).fetchall())
        kw = f.get("keywords") or _dm_keywords(f.get("ocr_text", ""))
        if isinstance(kw, str):
            kw = kw.split()
        if self.fts and kw:
            q = " OR ".join(re.sub(r'[^A-Za-z0-9ऀ-ॿ]', '', w) for w in kw[:10] if len(w) >= 3)
            if q.strip(" OR"):
                try:
                    _add(db.execute("SELECT d.* FROM search s JOIN docs d ON d.id=s.rowid WHERE search MATCH ? LIMIT ?",
                                    (q, cap)).fetchall())
                except Exception:
                    pass
        if len(cands) < cap and f.get("doc_type"):
            _add(db.execute("SELECT * FROM docs WHERE doc_type=? ORDER BY last_used DESC LIMIT ?",
                            (f.get("doc_type"), cap - len(cands))).fetchall())
        if len(cands) < 60:
            _add(db.execute("SELECT * FROM docs ORDER BY last_used DESC LIMIT 60").fetchall())
        return cands[:cap]

    def _score(self, f, r):
        """Content signals -> weighted average; unique codes -> identity lift.
        Exact barcode/QR match is near-proof (spec: 92 ocr + 95 img + 100 bc -> 97)."""
        parts, wsum, acc = {}, 0.0, 0.0

        def add(name, val, w):
            nonlocal wsum, acc
            parts[name] = round(val, 1)
            acc += val * w
            wsum += w

        ph = _dm_hash_sim(f.get("phash", ""), r["phash"]) if (f.get("phash") and r["phash"]) else None
        dh = _dm_hash_sim(f.get("dhash", ""), r["dhash"]) if (f.get("dhash") and r["dhash"]) else None
        if ph is not None or dh is not None:
            add("image", max([x for x in (ph, dh) if x is not None]), 3.0)
        if f.get("ahash") and r["ahash"]:
            add("layout", _dm_hash_sim(f.get("ahash", ""), r["ahash"]), 1.0)
        if f.get("ocr_text") and r["ocr_text"]:
            add("ocr", _dm_text_sim(f.get("ocr_text", ""), r["ocr_text"]), 3.0)
        kwf = f.get("keywords") or _dm_keywords(f.get("ocr_text", ""))
        if isinstance(kwf, str):
            kwf = kwf.split()
        kwr = (r["keywords"] or "").split()
        if kwf and kwr:
            add("keyword", 100.0 * _dm_jaccard(kwf, kwr), 1.0)
        content = (acc / wsum) if wsum > 0 else 0.0

        code_match = code_mismatch = False
        if f.get("barcode") and r["barcode"]:
            eq = (f.get("barcode") == r["barcode"])
            parts["barcode"] = 100.0 if eq else 0.0
            code_match = code_match or eq
            code_mismatch = code_mismatch or (not eq)
        if f.get("qrcode") and r["qrcode"]:
            eq = (f.get("qrcode") == r["qrcode"])
            parts["qr"] = 100.0 if eq else 0.0
            code_match = code_match or eq
            code_mismatch = code_mismatch or (not eq)

        if wsum <= 0 and not code_match:
            return (0, parts)
        if code_match:
            final = 0.65 * 100.0 + 0.35 * content
        elif code_mismatch:
            final = content * 0.4
        else:
            final = content
        return (int(round(min(100.0, final))), parts)

    # --- name history / timeline ---
    def latest_name(self, doc_id):
        r = self._db.execute("SELECT filename FROM names WHERE doc_id=? ORDER BY last_used DESC, id DESC LIMIT 1",
                             (doc_id,)).fetchone()
        return r["filename"] if r else None

    def names(self, doc_id):
        return [dict(r) for r in self._db.execute(
            "SELECT filename,folder,created,last_used,usage_count FROM names WHERE doc_id=? ORDER BY last_used DESC, id DESC",
            (doc_id,)).fetchall()]

    def latest_folder(self, doc_id):
        r = self._db.execute("SELECT folder FROM docs WHERE id=?", (doc_id,)).fetchone()
        return r["folder"] if r else None

    def doc(self, doc_id):
        r = self._db.execute("SELECT * FROM docs WHERE id=?", (doc_id,)).fetchone()
        return dict(r) if r else None

    # --- naming-pattern AI: suggest a name for a NEVER-SEEN document ---
    def pattern_suggest(self, doc_type, ocr_text, min_samples=3):
        """If past files of this doc-type share a naming pattern (e.g.
        '<person> - Aadhaar'), apply it to the subject detected in this scan.
        Returns a suggested filename or '' — for documents never scanned before."""
        if not self.ok() or not doc_type or not ocr_text:
            return ""
        with self._lock:
            try:
                rows = self._db.execute(
                    "SELECT DISTINCT filename FROM docs WHERE doc_type=? AND filename!='' "
                    "ORDER BY last_used DESC LIMIT 200", (doc_type,)).fetchall()
                fns = [r["filename"] for r in rows]
                if len(fns) < min_samples:
                    return ""
                pat = _dm_affix_pattern(fns, min_samples)
                if not pat:
                    return ""
                subj = _dm_guess_subject(ocr_text)
                if not subj:
                    return ""
                pre, suf = pat
                # don't repeat a subject that's already inside the fixed part
                if subj.lower() in (pre + suf).lower():
                    return ""
                # (v224) purane pattern ke underscore ab SPACE — naam me space rehta
                out = (pre + subj + suf).replace("_", " ")
                return re.sub(r'\s+', ' ', out).strip()
            except Exception:
                return ""

    def style_for(self, doc_type):
        """Learn the user's separator/order from past filenames of this type."""
        try:
            if doc_type:
                rows = self._db.execute("SELECT filename FROM docs WHERE doc_type=? AND filename!='' "
                                        "ORDER BY last_used DESC LIMIT 100", (doc_type,)).fetchall()
            else:
                rows = self._db.execute("SELECT filename FROM docs WHERE filename!='' "
                                        "ORDER BY last_used DESC LIMIT 100").fetchall()
            return _ni_learn_style([r["filename"] for r in rows])
        except Exception:
            return _ni_default_style()

    def corrections(self):
        """Learned OCR corrections {wrong: correct} (most-used first)."""
        try:
            return {r["wrong"]: r["correct"] for r in
                    self._db.execute("SELECT wrong, correct FROM corrections ORDER BY count DESC LIMIT 500").fetchall()}
        except Exception:
            return {}

    def add_correction(self, wrong, correct):
        if not self.ok() or not wrong or not correct or wrong.lower() == correct.lower():
            return
        with self._lock:
            try:
                self._db.execute(
                    "INSERT INTO corrections(wrong,correct,count) VALUES(?,?,1) "
                    "ON CONFLICT(wrong) DO UPDATE SET correct=?, count=count+1",
                    (wrong.lower(), correct, correct))
                self._db.commit()
            except Exception:
                pass

    # --- search ---
    def _reindex_row(self, did):
        if not self.fts:
            return
        try:
            self._db.execute("DELETE FROM search WHERE rowid=?", (did,))
            r = self._db.execute("SELECT ocr_text,filename,keywords,barcode,qrcode,folder,tags,doc_type FROM docs WHERE id=?", (did,)).fetchone()
            if r:
                self._db.execute("INSERT INTO search(rowid,ocr_text,filename,keywords,barcode,qrcode,folder,tags,doc_type) "
                                 "VALUES(?,?,?,?,?,?,?,?,?)", (did, r["ocr_text"], r["filename"], r["keywords"],
                                 r["barcode"], r["qrcode"], r["folder"], r["tags"], r["doc_type"]))
        except Exception:
            pass

    def search(self, query, limit=60):
        if not self.ok() or not query:
            return []
        with self._lock:
            try:
                if self.fts:
                    q = " ".join(re.sub(r'[^A-Za-z0-9ऀ-ॿ]', '', w) + "*" for w in query.split() if w.strip())
                    if not q.strip("* "):
                        return []
                    rows = self._db.execute("SELECT d.* FROM search s JOIN docs d ON d.id=s.rowid WHERE search MATCH ? "
                                            "ORDER BY d.last_used DESC LIMIT ?", (q, limit)).fetchall()
                    return [dict(r) for r in rows]
                like = "%" + query + "%"
                rows = self._db.execute("SELECT * FROM docs WHERE ocr_text LIKE ? OR filename LIKE ? OR keywords LIKE ? "
                                        "OR barcode LIKE ? OR qrcode LIKE ? OR folder LIKE ? OR tags LIKE ? "
                                        "ORDER BY last_used DESC LIMIT ?",
                                        (like, like, like, like, like, like, like, limit)).fetchall()
                return [dict(r) for r in rows]
            except Exception:
                return []

    # --- maintenance ---
    def stats(self):
        try:
            n = self._db.execute("SELECT COUNT(*) c FROM docs").fetchone()["c"]
            nm = self._db.execute("SELECT COUNT(*) c FROM names").fetchone()["c"]
            sz = os.path.getsize(self.path) if os.path.exists(self.path) else 0
            return {"docs": n, "names": nm, "bytes": sz, "fts": self.fts}
        except Exception:
            return {"docs": 0, "names": 0, "bytes": 0, "fts": self.fts}

    def integrity_ok(self):
        try:
            r = self._db.execute("PRAGMA integrity_check").fetchone()
            return bool(r) and (r[0] == "ok")
        except Exception:
            return False

    def dedupe(self):
        """Remove duplicate learning records: collapse identical (doc_id,filename)
        name rows (keep the most-recent), and drop stray exact-duplicate docs that
        share a barcode/QR/OCR-hash (keep the most-used). Returns rows removed."""
        if not self.ok():
            return 0
        removed = 0
        with self._lock:
            try:
                cur = self._db.execute(
                    "DELETE FROM names WHERE id NOT IN "
                    "(SELECT MAX(id) FROM names GROUP BY doc_id, filename)")
                removed += cur.rowcount if cur.rowcount and cur.rowcount > 0 else 0
                # duplicate docs by a strong key -> keep highest usage_count
                for key in ("barcode", "qrcode", "ocr_hash"):
                    dupes = self._db.execute(
                        "SELECT %s AS k FROM docs WHERE %s!='' GROUP BY %s HAVING COUNT(*)>1" % (key, key, key)
                    ).fetchall()
                    for d in dupes:
                        rows = self._db.execute(
                            "SELECT id FROM docs WHERE %s=? ORDER BY usage_count DESC, last_used DESC" % key,
                            (d["k"],)).fetchall()
                        keep = rows[0]["id"]
                        for r in rows[1:]:
                            self._db.execute("UPDATE names SET doc_id=? WHERE doc_id=?", (keep, r["id"]))
                            self._db.execute("DELETE FROM search WHERE rowid=?", (r["id"],)) if self.fts else None
                            self._db.execute("DELETE FROM docs WHERE id=?", (r["id"],))
                            removed += 1
                self._db.commit()
            except Exception:
                pass
        return removed

    def optimize(self):
        if not self.ok():
            return False
        with self._lock:
            try:
                self.dedupe()   # remove duplicate learning records first
                if self.fts:
                    try:
                        self._db.execute("INSERT INTO search(search) VALUES('optimize')")
                    except Exception:
                        pass
                self._db.execute("ANALYZE")
                self._db.commit()
                self._db.execute("VACUUM")   # compress the database file
                self._mset("last_optimize", int(time.time()))
                self._db.commit()
                return True
            except Exception:
                return False

    def maybe_optimize(self, every_days=7):
        """Run weekly optimize in a daemon thread (non-blocking)."""
        try:
            last = int(self._mget("last_optimize", "0") or "0")
        except Exception:
            last = 0
        if int(time.time()) - last < every_days * 86400:
            return
        try:
            threading.Thread(target=self.optimize, daemon=True).start()
        except Exception:
            pass

    def rebuild_index(self):
        if not self.ok() or not self.fts:
            return False
        with self._lock:
            try:
                self._db.execute("DELETE FROM search")
                for r in self._db.execute("SELECT id FROM docs").fetchall():
                    self._reindex_row(r["id"])
                self._db.commit()
                return True
            except Exception:
                return False

    def repair(self):
        if self.integrity_ok():
            return True
        try:
            self.rebuild_index()
            return self.integrity_ok()
        except Exception:
            return False

    def clear(self):
        with self._lock:
            try:
                self._db.executescript("DELETE FROM docs; DELETE FROM names;")
                if self.fts:
                    self._db.execute("DELETE FROM search")
                self._db.commit()
                self._db.execute("VACUUM")
                self._db.commit()
                return True
            except Exception:
                return False

    def export(self, path):
        if not self.ok():
            return False
        with self._lock:
            try:
                self._db.commit()
                dst = sqlite3.connect(path)
                self._db.backup(dst)
                dst.close()
                return True
            except Exception:
                return False

    def import_from(self, path):
        if not self.ok() or not os.path.exists(path):
            return 0
        added = 0
        with self._lock:
            try:
                src = sqlite3.connect(path)
                src.row_factory = sqlite3.Row
                for r in src.execute("SELECT * FROM docs").fetchall():
                    f = {kk: r[kk] for kk in r.keys()}
                    f["keywords"] = (r["keywords"] or "").split()
                    did, is_new = self.remember(f)
                    if is_new and did:
                        added += 1
                        try:
                            for nm in src.execute("SELECT * FROM names WHERE doc_id=?", (r["id"],)).fetchall():
                                self._db.execute("INSERT INTO names(doc_id,filename,folder,created,last_used,usage_count) VALUES(?,?,?,?,?,?)",
                                                 (did, nm["filename"], nm["folder"], nm["created"], nm["last_used"], nm["usage_count"]))
                        except Exception:
                            pass
                self._db.commit()
                src.close()
            except Exception:
                pass
        return added


class _PdfEditCanvas(QtWidgets.QLabel):
    """PDF text-editor ka page canvas — click par span-edit, hover par
    editable text ke gird halka box dikhata hai."""
    def __init__(self, dlg):
        super().__init__()
        self.dlg = dlg
        self.setMouseTracking(True)
        self.setAlignment(QtCore.Qt.AlignTop | QtCore.Qt.AlignLeft)
        self.setStyleSheet("background:#e9ecf2;")
        self._hover = None

    def mousePressEvent(self, e):
        try:
            self.dlg._canvas_click(e.pos())
        except Exception:
            pass

    def mouseMoveEvent(self, e):
        try:
            sp = self.dlg._span_at(e.pos())
            self.setCursor(QtCore.Qt.IBeamCursor if sp else QtCore.Qt.ArrowCursor)
            box = tuple(sp["bbox"]) if sp else None
            if box != self._hover:
                self._hover = box
                self.update()
        except Exception:
            pass

    def paintEvent(self, e):
        super().paintEvent(e)
        if not self._hover:
            return
        try:
            z = self.dlg.zoom
            p = QtGui.QPainter(self)
            p.setRenderHint(QtGui.QPainter.Antialiasing)
            r = QtCore.QRectF(self._hover[0] * z, self._hover[1] * z,
                              (self._hover[2] - self._hover[0]) * z,
                              (self._hover[3] - self._hover[1]) * z)
            r.adjust(-2, -2, 2, 2)
            p.setPen(QtGui.QPen(QtGui.QColor("#2563EB"), 1.4, QtCore.Qt.DashLine))
            p.setBrush(QtGui.QColor(37, 99, 235, 28))
            p.drawRoundedRect(r, 3, 3)
            p.end()
        except Exception:
            pass


class PdfTextEditDialog(QtWidgets.QDialog):
    """Digital/native PDF ke ASLI text ko badalne wala editor.
    Page par kisi bhi text par click karo -> wahin ek box khulta hai ->
    naya likho -> Enter. Har edit usi jagah, usi size/rang me lagti hai.
    (Scanned/photo-jaisi PDF par kaam nahi karta — us me asli text hi
    nahi hota.)"""

    def __init__(self, parent, src, scanned=False):
        super().__init__(parent)
        self.app = parent
        self.src = src
        self.scanned = scanned
        self.zoom = 1.6
        self.page_no = 0
        self.spans = []
        self._ocr_cache = {}
        self.dirty = False
        self._editor = None
        self._edit_span = None
        # scanned edits ke liye naye text ka font-parivaar (document se milane ko)
        self.font_family = "serif"           # zyadatar chhape documents serif hote
        L = parent.L
        self.setWindowTitle(
            (L("Scan PDF text badlo (OCR) — %s", "Edit scanned PDF text (OCR) — %s")
             if scanned else L("PDF text badlo — %s", "Edit PDF text — %s"))
            % os.path.basename(src))
        self.resize(900, 780)
        self.doc = fitz.open(src)

        v = QtWidgets.QVBoxLayout(self)
        v.setContentsMargins(8, 8, 8, 8)
        v.setSpacing(6)

        # ---- top toolbar ----
        bar = QtWidgets.QHBoxLayout()
        self.b_prev = QtWidgets.QPushButton("◀")
        self.b_next = QtWidgets.QPushButton("▶")
        self.b_prev.setFixedWidth(38); self.b_next.setFixedWidth(38)
        self.b_prev.clicked.connect(lambda: self._go(-1))
        self.b_next.clicked.connect(lambda: self._go(1))
        self.lbl_page = QtWidgets.QLabel("")
        self.lbl_page.setStyleSheet("font-weight:600;")
        b_zin = QtWidgets.QPushButton("＋"); b_zout = QtWidgets.QPushButton("－")
        b_zin.setFixedWidth(34); b_zout.setFixedWidth(34)
        b_zin.clicked.connect(lambda: self._set_zoom(self.zoom * 1.2))
        b_zout.clicked.connect(lambda: self._set_zoom(self.zoom / 1.2))
        b_find = QtWidgets.QPushButton("🔎 " + L("Dhoondo & badlo", "Find & Replace"))
        b_find.clicked.connect(self._find_replace)
        bar.addWidget(self.b_prev); bar.addWidget(self.lbl_page); bar.addWidget(self.b_next)
        bar.addStretch(1)
        if scanned:
            # naye text ka font document se milane ke liye (serif/sans/mono)
            bar.addWidget(QtWidgets.QLabel(L("Font:", "Font:")))
            self.cmb_font = QtWidgets.QComboBox()
            self.cmb_font.addItem(L("Serif (chhapa/Times jaisa)", "Serif (Times-like)"), "serif")
            self.cmb_font.addItem(L("Sans (saada/Arial jaisa)", "Sans (Arial-like)"), "sans")
            self.cmb_font.addItem(L("Mono (typewriter)", "Mono (typewriter)"), "mono")
            self.cmb_font.setCurrentIndex(0)
            self.cmb_font.currentIndexChanged.connect(self._on_font_changed)
            self.cmb_font.setToolTip(L(
                "Naye text ka font document ke akshar se milaao.",
                "Match the new text's font to the document."))
            bar.addWidget(self.cmb_font)
            bar.addSpacing(8)
        bar.addWidget(b_zout); bar.addWidget(b_zin)
        bar.addSpacing(10); bar.addWidget(b_find)
        v.addLayout(bar)

        if scanned:
            htext = L("💡 Kisi bhi line par click karke sudhaaro, phir Enter. "
                      "(Scan me naya text substitute font me aata hai — ye ek "
                      "saaf sudhaar hai, gaur se dekhne par edit dikh sakta hai.)",
                      "💡 Click any line to correct it, then Enter. (On a scan the "
                      "new text uses a substitute font — this is a clean correction, "
                      "an edit can still be noticed on close inspection.)")
        else:
            htext = L("💡 Kisi bhi text par click karke naya likho, phir Enter dabao.",
                      "💡 Click any text to edit it, then press Enter.")
        hint = QtWidgets.QLabel(htext)
        hint.setWordWrap(True)
        hint.setStyleSheet("color:#475569; padding:2px 4px;")
        v.addWidget(hint)

        # ---- scrollable page ----
        self.scroll = QtWidgets.QScrollArea()
        self.scroll.setWidgetResizable(False)
        self.scroll.setAlignment(QtCore.Qt.AlignCenter)
        self.scroll.setStyleSheet("QScrollArea{border:1px solid #cbd5e1;background:#e9ecf2;}")
        self.canvas = _PdfEditCanvas(self)
        self.scroll.setWidget(self.canvas)
        v.addWidget(self.scroll, 1)

        # ---- bottom buttons ----
        bb = QtWidgets.QHBoxLayout()
        self.lbl_status = QtWidgets.QLabel("")
        self.lbl_status.setStyleSheet("color:#16A34A;font-weight:600;")
        bb.addWidget(self.lbl_status); bb.addStretch(1)
        b_savenew = QtWidgets.QPushButton("💾 " + L("Nayi PDF me save", "Save as new PDF"))
        b_over = QtWidgets.QPushButton("♻ " + L("Isi file me save", "Overwrite original"))
        b_close = QtWidgets.QPushButton(L("Band karo", "Close"))
        b_savenew.clicked.connect(lambda: self._save(overwrite=False))
        b_over.clicked.connect(lambda: self._save(overwrite=True))
        b_close.clicked.connect(self._close_check)
        for b in (b_savenew, b_over):
            b.setStyleSheet("QPushButton{background:#2563EB;color:#fff;font-weight:600;"
                            "padding:7px 14px;border-radius:7px;}"
                            "QPushButton:hover{background:#1D4ED8;}")
        bb.addWidget(b_close); bb.addWidget(b_over); bb.addWidget(b_savenew)
        v.addLayout(bb)

        self._render()

    # ---------- rendering ----------
    def _render(self):
        page = self.doc[self.page_no]
        mat = fitz.Matrix(self.zoom, self.zoom)
        pix = page.get_pixmap(matrix=mat, alpha=False)
        img = QtGui.QImage(pix.samples, pix.width, pix.height,
                           pix.stride, QtGui.QImage.Format_RGB888)
        self.canvas.setPixmap(QtGui.QPixmap.fromImage(img.copy()))
        self.canvas.resize(pix.width, pix.height)
        self.spans = self._page_spans(self.page_no)
        self.lbl_page.setText("  %s %d / %d  " % (
            self.app.L("Page", "Page"), self.page_no + 1, self.doc.page_count))
        self.b_prev.setEnabled(self.page_no > 0)
        self.b_next.setEnabled(self.page_no < self.doc.page_count - 1)
        self._kill_editor()

    def _on_font_changed(self, _idx):
        self.font_family = self.cmb_font.currentData() or "serif"

    def _font_name(self):
        """Scanned edit ke liye base-14 font naam (document se milane ko).
        Digital edit ke liye None (asli span ke flags se decide hota)."""
        if not self.scanned:
            return None
        return {"serif": "tiro", "sans": "helv", "mono": "cour"}.get(
            self.font_family, "tiro")

    def _page_spans(self, pno):
        """Digital PDF: asli text spans. Scanned PDF: OCR se line-spans
        (ek baar chalta hai, phir cache)."""
        if not self.scanned:
            return _pdftext.page_spans(self.doc, pno)
        if pno not in self._ocr_cache:
            QtWidgets.QApplication.setOverrideCursor(QtCore.Qt.WaitCursor)
            try:
                self._ocr_cache[pno] = self.app._ocr_line_spans(self.doc, pno)
            except Exception:
                self._ocr_cache[pno] = []
            finally:
                QtWidgets.QApplication.restoreOverrideCursor()
        return self._ocr_cache[pno]

    def _set_zoom(self, z):
        self.zoom = max(0.5, min(4.0, z))
        self._render()

    def _go(self, d):
        n = self.page_no + d
        if 0 <= n < self.doc.page_count:
            self.page_no = n
            self._render()

    # ---------- hit-testing ----------
    def _span_at(self, qpos):
        x = qpos.x() / self.zoom
        y = qpos.y() / self.zoom
        best = None
        for sp in self.spans:
            b = sp["bbox"]
            if b[0] <= x <= b[2] and b[1] <= y <= b[3]:
                return sp
            # thoda margin (chhote text ke liye)
            if b[0] - 2 <= x <= b[2] + 2 and b[1] - 3 <= y <= b[3] + 3:
                best = sp
        return best

    def _canvas_click(self, qpos):
        sp = self._span_at(qpos)
        if sp:
            self._open_editor(sp)
        else:
            self._kill_editor()

    # ---------- inline edit box ----------
    def _open_editor(self, sp):
        self._kill_editor()
        z = self.zoom
        b = sp["bbox"]
        ed = QtWidgets.QLineEdit(self.canvas)
        ed.setText(sp["text"])
        fs = max(9, int(sp["size"] * z * 0.9))
        ed.setStyleSheet(
            "QLineEdit{background:#FFFDE7;border:2px solid #2563EB;border-radius:3px;"
            "padding:0 3px;font-size:%dpx;color:#111;}" % fs)
        x = int(b[0] * z) - 3
        y = int(b[1] * z) - 3
        w = max(60, int((b[2] - b[0]) * z) + 40)
        h = max(fs + 8, int((b[3] - b[1]) * z) + 8)
        ed.setGeometry(x, y, w, h)
        ed.show(); ed.setFocus(); ed.selectAll()
        ed.returnPressed.connect(self._commit_editor)
        self._editor = ed
        self._edit_span = sp

    def _kill_editor(self):
        if self._editor is not None:
            try:
                self._editor.deleteLater()
            except Exception:
                pass
        self._editor = None
        self._edit_span = None

    def _commit_editor(self):
        if self._editor is None or self._edit_span is None:
            return
        new = self._editor.text()
        old = self._edit_span["text"]
        sp = self._edit_span
        self._kill_editor()
        if new == old:
            return
        try:
            _pdftext.replace_span(self.doc, self.page_no, sp, new,
                                  scanned=self.scanned,
                                  fill=sp.get("fill", (1, 1, 1)),
                                  fontname=self._font_name())
            # scan-mode: cache me is line ka text update kar do
            if self.scanned:
                sp["text"] = new
            self.dirty = True
            self.lbl_status.setText(self.app.L("● Badlaav hue (save karna baaki)",
                                               "● Edited (unsaved)"))
            self._render()
        except Exception as exc:
            self.app._warn(self.app.L("Text badalne me dikkat:\n%s",
                                      "Could not edit text:\n%s") % exc)

    # ---------- find & replace ----------
    def _find_replace(self):
        L = self.app.L
        d = QtWidgets.QDialog(self)
        d.setWindowTitle(L("Dhoondo aur badlo", "Find & Replace"))
        fl = QtWidgets.QFormLayout(d)
        e_find = QtWidgets.QLineEdit()
        e_repl = QtWidgets.QLineEdit()
        chk_all = QtWidgets.QCheckBox(L("Saare page (poori PDF)", "All pages"))
        chk_all.setChecked(True)
        fl.addRow(L("Ye dhoondo:", "Find:"), e_find)
        fl.addRow(L("Isse badlo:", "Replace with:"), e_repl)
        fl.addRow("", chk_all)
        bx = QtWidgets.QDialogButtonBox(
            QtWidgets.QDialogButtonBox.Ok | QtWidgets.QDialogButtonBox.Cancel)
        bx.accepted.connect(d.accept); bx.rejected.connect(d.reject)
        fl.addRow(bx)
        if d.exec_() != QtWidgets.QDialog.Accepted:
            return
        find = e_find.text()
        repl = e_repl.text()
        if not find:
            return
        pages = range(self.doc.page_count) if chk_all.isChecked() else [self.page_no]
        n = 0
        try:
            for pno in pages:
                for sp in self._page_spans(pno):
                    if find in sp["text"]:
                        newt = sp["text"].replace(find, repl)
                        _pdftext.replace_span(self.doc, pno, sp, newt,
                                              scanned=self.scanned,
                                              fill=sp.get("fill", (1, 1, 1)),
                                              fontname=self._font_name())
                        if self.scanned:
                            sp["text"] = newt
                        n += 1
        except Exception as exc:
            self.app._warn(self.app.L("Badalne me dikkat:\n%s",
                                      "Replace failed:\n%s") % exc)
            return
        if n:
            self.dirty = True
            self.lbl_status.setText(self.app.L("● %d jagah badla (save baaki)" % n,
                                               "● Replaced in %d place(s) (unsaved)" % n))
        else:
            self.app._toast(self.app.L("Kuch nahi mila.", "Nothing matched."))
        self._render()

    # ---------- save ----------
    def _save(self, overwrite):
        if not self.dirty:
            self.app._toast(self.app.L("Koi badlaav nahi.", "No changes to save."))
            return
        L = self.app.L
        try:
            if overwrite:
                d = os.path.dirname(self.src)
                fd, tmp = tempfile.mkstemp(suffix=".pdf", dir=d); os.close(fd)
                self.doc.save(tmp, garbage=4, deflate=True)
                self.doc.close()
                os.replace(tmp, self.src)
                self.doc = fitz.open(self.src)
                out = self.src
            else:
                out = self.app._unique_fs_path(
                    os.path.splitext(self.src)[0] + " (edited).pdf")
                self.doc.save(out, garbage=4, deflate=True)
        except Exception as exc:
            self.app._warn(L("Save nahi hua:\n%s", "Save failed:\n%s") % exc)
            return
        self.dirty = False
        self.lbl_status.setText(L("✓ Save ho gaya", "✓ Saved"))
        try:
            self.app._invalidate_files_index(); self.app._refresh_files_root()
        except Exception:
            pass
        self.app._toast(L("✓ Save: %s" % os.path.basename(out),
                          "✓ Saved: %s" % os.path.basename(out)))
        if not overwrite:
            try:
                self.app._open_path(os.path.dirname(out))
            except Exception:
                pass

    def _close_check(self):
        if self.dirty:
            r = QtWidgets.QMessageBox.question(
                self, self.app.L("Save karein?", "Save changes?"),
                self.app.L("Badlaav save nahi hue. Save karke band karein?",
                           "You have unsaved edits. Save before closing?"),
                QtWidgets.QMessageBox.Save | QtWidgets.QMessageBox.Discard
                | QtWidgets.QMessageBox.Cancel)
            if r == QtWidgets.QMessageBox.Cancel:
                return
            if r == QtWidgets.QMessageBox.Save:
                self._save(overwrite=False)
        self.accept()

    def closeEvent(self, e):
        try:
            self.doc.close()
        except Exception:
            pass
        super().closeEvent(e)


class ScannerWindow(QtWidgets.QMainWindow):
    THUMB_W = 150
    THUMB_H = 200

    def __init__(self, auto_scan_profile=None):
        super().__init__()
        self.setWindowTitle(APP_NAME)
        try:
            self.setWindowIcon(app_icon())
        except Exception:
            pass
        self.resize(1220, 820)
        self._tmpdir = tempfile.mkdtemp(prefix="nobledoc_")
        self._config = load_config()
        # (v293) Suggested-name library — scalable local-first data model behind
        # the redesigned Rename system. Loads at startup into memory (migrates the
        # old name_history list, mirrors it back for backward-compat). No network.
        try:
            self._namelib = NameLibrary(self._config, lambda: save_config(self._config))
        except Exception:
            self._namelib = None
        self._profiles = self._config.get("profiles", [])
        # HD scan (v155, one-time): purani profiles 150/200 dpi par chal rahi
        # thin — sabko 300 dpi (HD) par le aao. User baad me kabhi bhi Settings
        # se ghata sakta hai; ye upgrade dobara zabardasti nahi hota.
        if not self._config.get("hd_dpi_upgraded"):
            for _p in self._profiles:
                try:
                    if int(_p.get("dpi", 0) or 0) < 300:
                        _p["dpi"] = 300
                except Exception:
                    _p["dpi"] = 300
            self._config["hd_dpi_upgraded"] = True
            if self._profiles:
                self._config["profiles"] = self._profiles
            try:
                save_config(self._config)
            except Exception:
                pass
        # (v242) NAPS2-EXACT: user ki tulna (NAPS2 150dpi vs ApneScan 200dpi) me
        # quality barabar nikli — farq sirf file-size, jo DPI se aata tha. User ne
        # "hubahu NAPS2" chuna, isliye SAARI profiles ek baar 150 dpi par le aao
        # (v155 ne inhe 300 par chadha diya tha). User kabhi bhi Settings se
        # kisi profile ka DPI badha sakta hai.
        if not self._config.get("naps2_dpi150_v242"):
            self._config["naps2_dpi150_v242"] = True
            for _p in (self._profiles or []):
                try:
                    _p["dpi"] = 150
                except Exception:
                    pass
            if self._profiles:
                self._config["profiles"] = self._profiles
            try:
                save_config(self._config)
            except Exception:
                pass
        # Layout v168 (one-time): scan-settings ab TOOLBAR ke neeche ek patti
        # me aur 'Meri Files' BAAYIN taraf — purani saved 'right' side ek baar
        # left kar rahe hain (Customize se wapas badla ja sakta hai).
        if not self._config.get("layout_v168"):
            self._config["layout_v168"] = True
            _lo = self._config.get("options")
            if isinstance(_lo, dict):
                _lo["files_panel_side"] = "left"
            try:
                save_config(self._config)
            except Exception:
                pass
        # v177 redesign: mockup jaisa saaf dashboard — Meri Files panel ek baar
        # chhupa do (sidebar ke 'Meri Files'/My Documents par click = wapas;
        # pasand yaad rehti hai, ye sirf EK baar hota hai).
        if not self._config.get("layout_v177"):
            self._config["layout_v177"] = True
            _lo = self._config.get("options")
            if isinstance(_lo, dict):
                _lo["show_files_panel"] = False
            try:
                save_config(self._config)
            except Exception:
                pass
        # v189: toolbar ke neeche wali "Scanner FREE (ready)" patti ek baar
        # sabke liye band (user request) — Settings se wapas on ho sakti hai
        if not self._config.get("layout_v189"):
            self._config["layout_v189"] = True
            _lo = self._config.get("options")
            if isinstance(_lo, dict):
                _lo["ui_header"] = False
            try:
                save_config(self._config)
            except Exception:
                pass
        # v206: preview ke neeche ki ApneScan stats-card ek baar sab par band
        # (user request) — Analytics ab sidebar se khulta hai; Settings ke
        # ui_analytics checkbox se wapas on ho sakti hai
        if not self._config.get("layout_v206"):
            self._config["layout_v206"] = True
            _lo = self._config.get("options")
            if isinstance(_lo, dict):
                _lo["ui_analytics"] = False
            try:
                save_config(self._config)
            except Exception:
                pass
        # v194: My Files panel ki default chaudai ek baar 290px tak badhao
        # (naam poore dikhein); user kheench kar badle to wahi yaad rahega
        if not self._config.get("layout_v194"):
            self._config["layout_v194"] = True
            _lo = self._config.get("options")
            if isinstance(_lo, dict):
                try:
                    _lo["files_panel_w"] = max(int(_lo.get("files_panel_w", 260) or 260), 290)
                except Exception:
                    _lo["files_panel_w"] = 290
            try:
                save_config(self._config)
            except Exception:
                pass
        self._opts = dict(DEFAULT_OPTIONS)
        self._opts.update(self._config.get("options", {}))
        self._recent = self._config.get("recent", [])
        self._used_claims = set(self._config.get("used_claims", []))
        self._barcode_tried = False
        self._dirty = False
        # AI Document Memory (offline learning) — remembers & recognises docs
        try:
            self._ai_memory_init()
        except Exception:
            self._memory = None
        self._undo_stack = []
        # unified multi-level undo/redo (page edits + deletes)
        self._hist = []
        self._hist_redo = []
        self._hist_max = 25
        # Startup guard: app khulte hi (jaise app ko Enter dabakar launch karne par
        # wahi Enter naye window me 'Enter = Scan' chala deta tha) galti se scan na
        # ho — pehle ~900ms tak do_scan ignore hota hai.
        self._start_timer = QtCore.QElapsedTimer(); self._start_timer.start()
        self._lang = self._opts.get("language", "en")
        # One-time migration: the app now ships as an English UI. Older installs
        # may still carry a saved Hindi/Hinglish setting — flip them to English
        # once. Users can always switch back via Settings -> Language.
        if not self._opts.get("_english_migrated"):
            self._opts["_english_migrated"] = True
            self._opts["language"] = "en"
            self._lang = "en"
            try:
                self._save_opts()
            except Exception:
                pass
        # (v233) NAPS2-MATCH: eSCL ka scan NAPS2 ke HP-WIA-driver output se feeka
        # tha (kam contrast, feeke rang, gray-maila bg). Ab auto_vivid (naps2_clean)
        # se saaf+chatak. Purana flatten_background rangeen header WASH-OUT kar deta
        # tha — use ek baar OFF karo (auto_vivid absent-key se apne aap ON hai).
        # (v237) NAPS2-FAITHFUL: user ki maang par saara tonal-processing scan se
        # HATA diya (NAPS2 bhi kuch nahi karta). auto_vivid faint address-line ko
        # safed kar raha tha, whiten bhi kinare ki halki line uda deta tha — dono
        # ek baar OFF. flatten pehle se off. (Zaroorat par Settings se ON.)
        if not self._opts.get("_naps2_faithful_v237"):
            self._opts["_naps2_faithful_v237"] = True
            self._opts["auto_flatten"] = False
            self._opts["auto_vivid"] = False
            self._opts["auto_whiten_backing"] = False
            try:
                self._save_opts()
            except Exception:
                pass
        # (v238) side/niche ki dark backing-patti ko crop karke hatao (default ON)
        if not self._opts.get("_trim_backing_v238"):
            self._opts["_trim_backing_v238"] = True
            self._opts["auto_trim_backing"] = True
            try:
                self._save_opts()
            except Exception:
                pass
        # (v244) auto_vivid ab SAFE naps2_levels chalata hai (v237 wala autocontrast
        # nahi jo line uda raha tha) — eSCL ka gray scan NAPS2 jaisa clean-white.
        # v237 ne ise OFF kar diya tha; ek baar wapas ON.
        if not self._opts.get("_naps2_levels_v244"):
            self._opts["_naps2_levels_v244"] = True
            self._opts["auto_vivid"] = True
            try:
                self._save_opts()
            except Exception:
                pass
        # (v245) naps2_levels ab HAR method par (eSCL/WIA) — pehle sirf eSCL par
        # tha, isliye WIA ke grayish scan par nahi lag raha tha. auto_vivid pakka ON.
        if not self._opts.get("_naps2_levels_all_v245"):
            self._opts["_naps2_levels_all_v245"] = True
            self._opts["auto_vivid"] = True
            try:
                self._save_opts()
            except Exception:
                pass
        # (v249) backing ab CROP (pehle "white" tha -> niche/side blank space reh
        # jaata tha). trim ab gray+dark dono kaat leta hai, page tight aata hai.
        if not self._opts.get("_backing_crop_v249"):
            self._opts["_backing_crop_v249"] = True
            self._opts["backing_mode"] = "crop"
            self._opts["auto_trim_backing"] = True
            try:
                self._save_opts()
            except Exception:
                pass
        # v100: visual-name signature ka naya (barik) format — purane (v99)
        # signatures alag size ke the, match nahi honge; hata do taaki saaf rahe.
        if not self._opts.get("_vsig_v2"):
            self._opts["_vsig_v2"] = True
            self._config["learned_visual"] = []
            try:
                self._save_opts()
            except Exception:
                pass
        # v143: "Always Auto Rotate" ab default ON — purane installs (jinme ye
        # False saved tha) me bhi ek baar chalu kar do (recommended).
        if not self._opts.get("_always_rotate_v143"):
            self._opts["_always_rotate_v143"] = True
            self._opts["auto_orient"] = True
            try:
                self._save_opts()
            except Exception:
                pass
        # v94: naye keyboard shortcuts (F2=Rename, F3=150, F4=200, F5=300,
        # F6=600, F7=Custom). Purane saved keys hata do taaki naya default lage.
        if not self._opts.get("_sc_reset_v94"):
            self._opts["_sc_reset_v94"] = True
            scm = dict(self._opts.get("shortcuts", {}) or {})
            for _sid in ("scan", "rename", "dpi_150", "dpi_200", "dpi_300",
                         "dpi_600", "dpi_custom", "save_all", "save_sel"):
                scm.pop(_sid, None)
            self._opts["shortcuts"] = scm
            try:
                self._save_opts()
            except Exception:
                pass

        # Install ke baad ek default profile khud ban jaaye (DPI 150, colour, auto).
        self._ensure_default_profile()

        self._build_menu()
        self._build_ui()
        self._apply_style()
        self._refresh_profile_combo()
        self._load_profile_to_panel(self._selected_profile())
        self._refresh_method_label()
        self._refresh_recent_menu()
        self._update_status()
        # Profile-lock ki pichhli haalat wapas laga do
        try:
            _lk = bool(self._opts.get("profile_locked"))
            self.btn_lock.blockSignals(True); self.btn_lock.setChecked(_lk); self.btn_lock.blockSignals(False)
            self._toggle_profile_lock(_lk)
        except Exception:
            pass

        QtCore.QTimer.singleShot(400, self.check_connection)
        self._conn_timer = QtCore.QTimer(self)
        self._conn_timer.setInterval(30000)
        self._conn_timer.timeout.connect(self.check_connection)
        self._conn_timer.start()

        if not self._config.get("setup_done"):
            QtCore.QTimer.singleShot(600, self._run_wizard)

        self._apply_simple_mode()

        if auto_scan_profile:
            i = self.cmb_profile.findText(auto_scan_profile)
            if i >= 0:
                self.cmb_profile.setCurrentIndex(i)
            QtCore.QTimer.singleShot(800, self.do_scan)

    # ---- config helpers ----
    def _save_opts(self):
        self._config["options"] = self._opts; save_config(self._config)

    def _save_profiles(self):
        self._config["profiles"] = self._profiles; save_config(self._config)

    def _add_recent(self, path):
        self._recent = [path] + [r for r in self._recent if r != path]
        self._recent = self._recent[:12]
        self._config["recent"] = self._recent; save_config(self._config)
        self._refresh_recent_menu()

    # ---- menu + shortcuts ----
    def _ma(self, menu, text, slot, tip="", sc=None):
        # add a menu action with a "?"-prefixed label + a Hindi/English hover tip
        a = menu.addAction(("\u2753 " + text) if tip else text, slot)
        if tip:
            a.setToolTip(tip); a.setStatusTip(tip)
        return a

    def _build_menu(self):
        mb = self.menuBar()
        mf = mb.addMenu(tr("menu_file", self._lang)); mf.setToolTipsVisible(True)
        self._ma(mf, tr("save_all", self._lang), self.save_pdf_all,
                 "हिन्दी: सभी पेजों की एक PDF बनाओ।\nEnglish: Save all pages as one PDF.", "Ctrl+S")
        self._ma(mf, tr("save_sel", self._lang), self.save_pdf_selected,
                 "हिन्दी: सिर्फ़ चुने हुए (Ctrl/Shift से) पेजों की PDF।\nEnglish: PDF of only the selected pages.")
        self._ma(mf, "Save PDF (password)…", self.save_pdf_password,
                 "हिन्दी: पासवर्ड से सुरक्षित PDF (खोलने के लिए पासवर्ड लगेगा)।\nEnglish: Password-protected PDF.")
        self._ma(mf, "Save Images…", self.save_images,
                 "हिन्दी: पेजों को JPG/PNG इमेज में सेव करो (PDF के बजाय)।\nEnglish: Save pages as JPG/PNG images.", "Ctrl+Shift+S")
        self._ma(mf, "Export OCR text…", self.export_ocr_text,
                 "हिन्दी: पेज के टेक्स्ट को पढ़कर .txt में निकालो (OCR)।\nEnglish: Extract page text to .txt via OCR.")
        pmenu = mf.addMenu("Print")
        pmenu.setToolTipsVisible(True)
        self._ma(pmenu, "All print (all pages)", self.print_all,
                 "हिन्दी: सारे पेज प्रिंट करो।\nEnglish: Print all pages.")
        self._ma(pmenu, "Selected print", self.print_selected,
                 "हिन्दी: सिर्फ़ चुने हुए (Ctrl/Shift से) पेज प्रिंट करो।\nEnglish: Print only the selected pages.")
        self._ma(pmenu, "ID print (2 IDs per page)", self.print_ids,
                 "हिन्दी: ID कार्ड को एक A4 पेज पर 2-2 करके प्रिंट करो (काग़ज़ बचेगा)।\nEnglish: Print ID cards two-per-A4-sheet to save paper.")
        self._ma(pmenu, "ID print - selected only", self.print_ids_selected,
                 "हिन्दी: सिर्फ़ चुने हुए ID को 2-per-page प्रिंट करो।\nEnglish: Print only selected IDs, two per sheet.")
        shmenu = mf.addMenu('Share')
        shmenu.setToolTipsVisible(True)
        self._ma(shmenu, "Send via WhatsApp…", self.share_whatsapp,
                 "हिन्दी: आख़िरी सेव की हुई PDF WhatsApp पर भेजो (फ़ाइल कॉपी हो जाती है, चैट में Ctrl+V या drag से attach)।\nEnglish: Send the last saved PDF via WhatsApp (file is copied; paste or drag into the chat).")
        self._ma(shmenu, "Send via Email…", self.share_email,
                 "हिन्दी: PDF को Email से भेजो (Outlook हो तो attachment के साथ draft खुलता है)।\nEnglish: Send the PDF by Email (opens an Outlook draft with the attachment if available).")
        self.recent_menu = mf.addMenu("Recent PDFs")
        self.recent_menu.setToolTipsVisible(True)
        mf.addSeparator()
        self._ma(mf, "Exit", self.close, "हिन्दी: ऐप बंद करो। (बिना सेव किए पेज हों तो चेतावनी आएगी।)\nEnglish: Close the app. (Warns if there are unsaved pages.)")

        me = mb.addMenu(tr("menu_edit", self._lang)); me.setToolTipsVisible(True)
        self._ma(me, "Rotate left", self.rotate_left, "हिन्दी: चुने हुए पेज को बाएँ घुमाओ।\nEnglish: Rotate the selected page left.")
        self._ma(me, "Rotate right", self.rotate_right, "हिन्दी: चुने हुए पेज को दाएँ घुमाओ।\nEnglish: Rotate the selected page right.")
        self._ma(me, "Brightness +", lambda: self._enhance_current(1.12, 1.0), "हिन्दी: पेज को हल्का (bright) करो।\nEnglish: Make the page brighter.")
        self._ma(me, "Brightness -", lambda: self._enhance_current(0.9, 1.0), "हिन्दी: पेज को गहरा (dim) करो।\nEnglish: Make the page darker.")
