    def _finalize_menu_help(self):
        """Poore menu-tree ko scan karke jis bhi option par abhi tak '?' /
        tooltip nahi hai, uspar khud laga do. Ye function baar-baar chalana
        safe hai (dobara prefix nahi lagta)."""
        MARK = "❓ "

        def walk(menu):
            try:
                menu.setToolTipsVisible(True)
            except Exception:
                pass
            for act in menu.actions():
                if act.isSeparator():
                    continue
                sub = act.menu()
                if sub is not None:
                    walk(sub)
                    continue
                t = act.text()
                if not t:
                    continue
                clean = t[len(MARK):] if t.startswith(MARK) else t
                if not t.startswith(MARK):
                    act.setText(MARK + t)
                # tooltip na ho (ya sirf label ki copy ho) to ek default bilingual
                # explanation laga do
                if not act.toolTip() or act.toolTip() in (t, clean):
                    label = clean.replace("&", "").replace("…", "").strip()
                    act.setToolTip("%s — runs this menu option.\n"
                                   "Runs the \"%s\" action." % (label, label))
        try:
            for act in self.menuBar().actions():
                if act.menu() is not None:
                    walk(act.menu())
        except Exception:
            pass

    def _refresh_recent_menu(self):
        self.recent_menu.clear()
        if not self._recent:
            a = self.recent_menu.addAction("(none)"); a.setEnabled(False); return
        for path in self._recent:
            self.recent_menu.addAction(os.path.basename(path),
                                       lambda checked=False, p=path: self._open_path(p))

    def _open_path(self, path):
        try:
            os.startfile(path)
        except Exception as exc:
            self._warn("Could not open file:\n%s" % exc)

    # ---- profiles / options ----
    def _ensure_default_profile(self):
        """Install ke baad (jab koi profile na ho) ek 'Default' profile khud
        bana do — SPEC:
            Display Name : Default
            Device       : jo user select kare wahi (auto-detect / device chunne
                           par is profile me apne aap bhar jaata hai)
            Resolution   : 150 DPI
            Colour Mode  : Colour
            Page Size    : Auto
        Device pehli-baar khaali reh sakta hai; user ke device chunte hi
        _sync_selected_profile_device()/_detect_device_name() ise bhar dete hain."""
        if self._profiles:
            return
        self._profiles = [{
            "name": "Default",
            "dpi": 150,                # (v242) NAPS2-EXACT: NAPS2 bhi 150 dpi par
                                       # scan karta hai — wahi look + file-size.
            "color": "color",          # Colour
            "duplex": False,
            "page_size": "auto",       # Auto
            "paper_source": "feeder",
            "source_name": self._opts.get("scanner_name", ""),   # jo user select kare
        }]
        self._config["profiles"] = self._profiles
        self._config["selected_profile"] = "Default"
        try:
            save_config(self._config)
        except Exception:
            pass

    def _fill_default_profile_device(self, name):
        """Agar 'Default' profile ka Device khaali hai to use user ke chune hue
        device se bhar do (spec: 'Device: jo user select kare')."""
        if not name:
            return
        changed = False
        for p in (self._profiles or []):
            if p.get("name") == "Default" and not p.get("source_name"):
                p["source_name"] = name
                changed = True
        if changed:
            self._config["profiles"] = self._profiles
            try:
                save_config(self._config)
            except Exception:
                pass

    def _refresh_profile_combo(self):
        self.cmb_profile.blockSignals(True); self.cmb_profile.clear()
        for p in self._profiles:
            self.cmb_profile.addItem(p.get("name", "Profile"))
        sel = self._config.get("selected_profile")
        if sel:
            i = self.cmb_profile.findText(sel)
            if i >= 0:
                self.cmb_profile.setCurrentIndex(i)
        self.cmb_profile.blockSignals(False)

    def _selected_profile(self):
        name = self.cmb_profile.currentText()
        for p in self._profiles:
            if p.get("name") == name:
                return p
        return None

    def _on_fast_toggled(self, on):
        self._opts["fast_mode"] = bool(on); self._save_opts()
        if on:
            # reflect fast settings in the panel so the user sees them
            self.cmb_dpi.setCurrentText("200 dpi")
            self.cmb_depth.setCurrentText("Black & White")
        self.status.showMessage("Fast mode ON (200 dpi, B&W)" if on else "Fast mode OFF", 3000)

    def _on_profile_changed(self, name):
        self._config["selected_profile"] = name; save_config(self._config)
        self._load_profile_to_panel(self._selected_profile())


    def open_profiles(self):
        dlg = ProfileManagerDialog(self, self._profiles)
        if dlg.exec_() == QtWidgets.QDialog.Accepted:
            self._profiles = dlg.profiles; self._save_profiles(); self._refresh_profile_combo()

    def open_options(self, _checked=False, tab=None):
        dlg = OptionsDialog(self, self._opts)
        # (v199) tab="shortcuts" → seedha ⌨ Shortcuts tab khula mile
        if tab == "shortcuts":
            try:
                dlg.tabs.setCurrentIndex(dlg.tabs.count() - 1)
            except Exception:
                pass
        if dlg.exec_() == QtWidgets.QDialog.Accepted:
            self._opts = dlg.get_opts(); self._save_opts(); self._update_status()
            self._apply_style(); self._refresh_page_numbers()
            self._refresh_files_root()   # save-folder badla ho to panel bhi

    def _refresh_page_numbers(self):
        show = self._opts.get("show_page_numbers", True)
        for i in range(self.list.count()):
            it = self.list.item(i)
            title = it.data(TITLE_ROLE)
            if title:
                it.setText(title)
            else:
                it.setText(("Page %d" % (i + 1)) if show else "")

    def _vsep(self):
        f = QtWidgets.QFrame(); f.setObjectName("hr"); f.setFrameShape(QtWidgets.QFrame.VLine); return f

    def _on_panel_dpi_changed(self, txt):
        """'Custom…' chunne par apni dpi pucho aur list me jod do."""
        if not txt.startswith("Custom"):
            return
        n, ok = QtWidgets.QInputDialog.getInt(
            self, self.L("Apni DPI", "Custom DPI"),
            self.L("DPI likho (50–1200):", "Enter DPI (50–1200):"), 300, 50, 1200, 50)
        item = ("%d dpi" % n)
        self.cmb_dpi.blockSignals(True)
        if ok:
            if self.cmb_dpi.findText(item) < 0:
                self.cmb_dpi.insertItem(self.cmb_dpi.count() - 1, item)
            self.cmb_dpi.setCurrentText(item)
        else:
            self.cmb_dpi.setCurrentText("300 dpi")
        self.cmb_dpi.blockSignals(False)

    def _panel_scan_params(self, prof):
        try:
            dpi = int(self.cmb_dpi.currentText().split()[0])
        except Exception:
            dpi = int(prof.get("dpi", 200))
        d = self.cmb_depth.currentText()
        color = "color" if d.startswith("24") else ("gray" if d.startswith("Gray") else "bw")
        duplex = "Both" in self.cmb_sides.currentText()
        return dpi, color, duplex

    def _profile_scan_params(self, prof, dpi_override=None):
        """Scan settings SIRF profile se — panel ke manual badlaav se nahi. Isi
        liye Enter/Scan hamesha profile ki saved setting par scan karta hai.
        dpi_override diya ho (DPI shortcut se) to sirf us ek scan ke liye dpi
        badal jata hai — panel/profile nahi badalta."""
        prof = prof or {}
        try:
            dpi = int(dpi_override) if dpi_override else int(prof.get("dpi", 150))
        except Exception:
            dpi = 150
        color = prof.get("color", "color")
        if color not in ("color", "gray", "bw"):
            color = "color"
        duplex = bool(prof.get("duplex"))
        page_size = (prof.get("page_size") or "auto").lower()
        source = (prof.get("paper_source") or "feeder").lower()
        return dpi, color, duplex, page_size, source

    def _refresh_method_label(self):
        if not hasattr(self, "method_lbl"):
            return
        m = self._opts.get("scanner_method", "twain")
        color = "#4F46E5" if m in ("wia", "naps2", "escl") else "#b45309"
        self.method_lbl.setText('<b>Connected via:</b> <span style="color:%s">%s</span>'
                                % (color, m.upper()))

    def _load_profile_to_panel(self, prof):
        if prof is None or not hasattr(self, "cmb_dpi"):
            return
        self.dev_lbl.setText(prof.get("source_name")
                             or self._opts.get("scanner_name") or "(no device)")
        _dpitem = str(prof.get("dpi", 200)) + " dpi"
        if self.cmb_dpi.findText(_dpitem) < 0:           # custom dpi — list me jodo
            self.cmb_dpi.blockSignals(True)
            self.cmb_dpi.insertItem(max(0, self.cmb_dpi.count() - 1), _dpitem)
            self.cmb_dpi.blockSignals(False)
        self.cmb_dpi.setCurrentText(_dpitem)
        c = prof.get("color", "gray")
        self.cmb_depth.setCurrentText("24-bit Colour" if c == "color"
                                      else ("Grayscale" if c == "gray" else "Black & White"))
        self.cmb_source.setCurrentText("Feeder (ADF)")
        self.cmb_sides.setCurrentText("Both sides (duplex)" if prof.get("duplex") else "Single side")
        # page size (per-profile)
        if hasattr(self, "cmb_pagesize"):
            _ps = (prof.get("page_size") or "auto").lower()
            for k in range(self.cmb_pagesize.count()):
                if self.cmb_pagesize.itemText(k).lower().startswith(_ps[:4]):
                    self.cmb_pagesize.setCurrentIndex(k); break

    # ================= Panel: doc-type presets / lock / simple / dup =========
    DOCTYPE_PRESETS = {
        "presc": {"dpi": 300, "color": "color", "page_size": "auto", "duplex": False},
        "lab":   {"dpi": 300, "color": "gray",  "page_size": "a4",   "duplex": False},
        "id":    {"dpi": 300, "color": "color", "page_size": "auto", "duplex": True},
        "xray":  {"dpi": 300, "color": "gray",  "page_size": "auto", "duplex": False},
    }

    def _doctype_tip(self, key):
        return {
            "presc": self.L("Prescription — 300dpi · colour", "Prescription — 300dpi · colour"),
            "lab":   self.L("Lab report — 200dpi · grayscale · A4", "Lab report — 200dpi · grayscale · A4"),
            "id":    self.L("ID card — 300dpi · colour · dono side", "ID card — 300dpi · colour · both sides"),
            "xray":  self.L("X-ray — 300dpi · grayscale", "X-ray — 300dpi · grayscale"),
        }.get(key, "")

    def _apply_doctype_preset(self, key):
        p = self.DOCTYPE_PRESETS.get(key)
        if not p:
            return
        if self._opts.get("profile_locked"):
            self.status.showMessage(self.L("Profile lock hai — pehle 🔓 unlock karo.",
                                           "Profile is locked — unlock 🔓 first."), 4000)
            return
        prof = self._selected_profile()
        if prof is None:
            return
        prof.update({"dpi": p["dpi"], "color": p["color"],
                     "page_size": p["page_size"], "duplex": p["duplex"]})
        self._save_profiles()
        self._load_profile_to_panel(prof)
        self.status.showMessage(self.L("Profile set: %s" % key, "Profile set: %s" % key), 4000)

    def _set_scan_opt(self, key, on):
        self._opts[key] = bool(on)
        self._save_opts()

    def _toggle_profile_lock(self, on):
        """Lock ON hone par SIRF 'Scanner badlo/dhoondo' khula rehta hai —
        baaki har setting (profile chunna, ➕✏️📋, Paper source, Scan sides,
        Page size, Resolution, Bit depth, Auto-fixes, 'Baad me:') lock ho
        jaati hai taaki galti se kuch na badle. Lock/unlock button khud
        hamesha khula rehta hai."""
        self._opts["profile_locked"] = bool(on)
        self._save_opts()
        try:
            self.btn_lock.setText("🔒" if on else "🔓")
            # 1) profile chunna + profile edit-buttons
            self.cmb_profile.setEnabled(not on)
            for b in getattr(self, "_profile_edit_btns", []):
                b.setEnabled(not on)
            # 2) advanced box (paper source / sides / page size / dpi / bit depth)
            if hasattr(self, "_adv_box"):
                self._adv_box.setEnabled(not on)
            # 3) advanced show/hide toggle bhi lock (setting na badle)
            if hasattr(self, "btn_adv"):
                self.btn_adv.setEnabled(not on)
            # 4) Auto-fixes chips (Crop/Straight/Blank/Clean)
            for _cb in (getattr(self, "_opt_chips", {}) or {}).values():
                _cb.setEnabled(not on)
            # 5) 'Baad me:' (After) dropdown
            if hasattr(self, "cmb_after_scan"):
                self.cmb_after_scan.setEnabled(not on)
            # scanner change (btn_change_dev) aur lock-button JAAN-boojh kar
            # khule rakhe jaate hain — inhe kabhi disable nahi karte.
        except Exception:
            pass
        self.status.showMessage(
            self.L("🔒 Lock ON — sirf scanner badla ja sakta hai" if on
                   else "🔓 Lock off — sab settings khuli",
                   "🔒 Locked — only the scanner can be changed" if on
                   else "🔓 Unlocked — all settings editable"), 3500)

    def _refresh_adv_toggle_text(self):
        if not hasattr(self, "btn_adv"):
            return
        arrow = "▲" if self.btn_adv.isChecked() else "▼"
        self.btn_adv.setText(self.L("⚙ Advanced settings %s" % arrow,
                                    "⚙ Advanced settings %s" % arrow))

    def _toggle_adv_panel(self, on):
        self._opts["panel_simple"] = not bool(on)
        self._save_opts()
        if hasattr(self, "_adv_box"):
            self._adv_box.setVisible(bool(on))
        self._refresh_adv_toggle_text()

    def _duplicate_profile(self):
        prof = self._selected_profile()
        if prof is None:
            self._quick_new_profile(); return
        import copy
        new = copy.deepcopy(prof)
        names = {p.get("name") for p in self._profiles}
        base = (prof.get("name", "Profile") + " copy")
        nm = base; i = 2
        while nm in names:
            nm = "%s %d" % (base, i); i += 1
        new["name"] = nm
        self._profiles.append(new); self._save_profiles(); self._refresh_profile_combo()
        self.cmb_profile.setCurrentText(nm)
        self.status.showMessage(self.L("Nakal bani: %s" % nm, "Duplicated: %s" % nm), 4000)

    def _scan_and_save(self):
        """Scan karo, aur scan ke baad seedha chune folder me PDF save."""
        self._save_after_scan_once = True
        self.do_scan()

    def _quick_new_profile(self):
        dlg = EditProfileDialog(self)
        if dlg.exec_() == QtWidgets.QDialog.Accepted:
            self._profiles.append(dlg.get_profile()); self._save_profiles(); self._refresh_profile_combo()
            self.cmb_profile.setCurrentIndex(self.cmb_profile.count() - 1)

    def _quick_edit_profile(self):
        name = self.cmb_profile.currentText()
        idx = next((k for k, p in enumerate(self._profiles) if p.get("name") == name), -1)
        if idx < 0:
            self._quick_new_profile(); return
        dlg = EditProfileDialog(self, self._profiles[idx])
        if dlg.exec_() == QtWidgets.QDialog.Accepted:
            self._profiles[idx] = dlg.get_profile(); self._save_profiles(); self._refresh_profile_combo()
            i = self.cmb_profile.findText(self._profiles[idx].get("name"))
            if i >= 0:
                self.cmb_profile.setCurrentIndex(i)
            self._load_profile_to_panel(self._selected_profile())

    def _open_preview_dialog(self, item):
        if item is None:
            return
        row = self.list.row(item)
        PreviewDialog(self, row).exec_()

    def auto_name_pages(self):
        items = [(i, self.list.item(i).data(QtCore.Qt.UserRole)) for i in range(self.list.count())]
        if not items:
            self._warn("Scan or import a page first."); return
        # 1) Pehle SHAKL se (design/rang/type \u2014 OCR nahi). Jo pages pehle diye
        #    naam se milte hain unhe turant naam mil jata hai.
        vnamed = 0
        remaining = []
        for row, path in items:
            vname = None
            try:
                vname = self._visual_name_for_path(path)
            except Exception:
                vname = None
            if vname:
                self._apply_visual_title(row, vname); vnamed += 1
            else:
                remaining.append((row, path))
        # 2) Baaki pages OCR (text) se \u2014 agar Tesseract ho
        if remaining and tesseract_available():
            self._named_count = vnamed
            self._named_total = len(items)
            self.status.showMessage("Reading document names... (please wait)", 0)
            self._namer = NameWorker(remaining, learned=self._learned_names())
            self._namer.named.connect(self._apply_page_title)
            self._namer.finished_all.connect(self._on_naming_done)
            self._namer.start()
            return
        # sirf visual (ya Tesseract nahi hai)
        if vnamed:
            self.status.showMessage(
                self.L("%d page pichhle naam se pehchaan liye (shakl se)." % vnamed,
                       "Named %d page(s) from their look (last-used names)." % vnamed), 6000)
        elif not tesseract_available():
            self._warn(
                "No matching page seen before, and Tesseract OCR is not installed.\n\n"
                "Tip: rename a page once (F2) \u2014 next time a similar-looking page is "
                "scanned it will get that name automatically (no OCR needed).\n\n"
                "For text-based naming, install Tesseract (free):\n"
                "https://github.com/UB-Mannheim/tesseract/wiki")
        else:
            self.status.showMessage("No names matched.", 5000)

    def _name_one_page(self, row, path, force=False):
        """Ek page ka naam TURANT lagao. Pehle SHAKL se (design/rang/type —
        OCR nahi): agar ye page pehle naam diye kisi page se ~72%+ milta ho to
        wahi naam. Warna Tesseract ho to text (OCR) se."""
        if not path:
            return
        if not force and not self._opts.get("auto_name"):
            return
        # 1) shakl se (handwritten/X-ray/ID par bhi kaam karta hai)
        try:
            vname = self._visual_name_for_path(path)
        except Exception:
            vname = None
        if vname:
            self._apply_visual_title(row, vname)
            return
        # 2) warna OCR se
        if not tesseract_available():
            return
        self._page_namers = getattr(self, "_page_namers", [])
        w = NameWorker([(row, path)], learned=self._learned_names())
        w.named.connect(self._apply_page_title)
        w.finished_all.connect(
            lambda w=w: self._page_namers.remove(w) if w in self._page_namers else None)
        self._page_namers.append(w)
        w.start()

    # ---- Visual (shakl se) naam yaad rakhna aur milaana ----
    def _learned_visual(self):
        return self._config.get("learned_visual", []) or []

    def _visual_name_for_path(self, path):
        """Is page ki shakl se pehle diya gaya naam (agar 72%+ milta ho)."""
        try:
            with Image.open(path) as im:
                sig = visual_signature(im)
        except Exception:
            return None
        name, _sc = visual_name_for(sig, self._learned_visual())
        return name

    def _store_visual_name(self, path, name):
        """Rename par page ki shakl -> naam yaad rakho (OCR nahi chahiye).
        Agli baar aisa hi dikhne wala page apne aap isi naam se aayega."""
        if not path or not name:
            return
        try:
            with Image.open(path) as im:
                sig = visual_signature(im)
        except Exception:
            sig = None
        if not sig:
            return
        lv = self._config.setdefault("learned_visual", [])
        for e in lv:                       # bahut milta-julta pehle se ho to update
            if _vsig_sim(sig, e.get("vsig")) >= 0.90:
                e["vsig"] = sig; e["name"] = name
                break
        else:
            lv.append({"vsig": sig, "name": name})
            if len(lv) > 8000:
                del lv[0:len(lv) - 8000]
        try:
            save_config(self._config)
        except Exception:
            pass

    def _apply_visual_title(self, row, label):
        """Shakl se mila naam seedha laga do (OCR post-processing nahi)."""
        if not (0 <= row < self.list.count()):
            return
        it = self.list.item(row)
        label = underscore_name(label or "")
        it.setData(TITLE_ROLE, label)
        it.setData(NAMEKEY_ROLE, name_key(label))
        it.setText(label if label.strip() else ("Page %d" % (row + 1)))
        try:
            self._pstats_bump(ocr_named=1)
        except Exception:
            pass

    def _learned_names(self):
        out = []
        for e in (self._config.get("learned_names", []) or []):
            try:
                out.append((set(e.get("words", [])), e.get("name", "")))
            except Exception:
                pass
        return out

    def _apply_page_title(self, row, title):
        if 0 <= row < self.list.count():
            it = self.list.item(row)
            key = name_key(title)
            # if this same document was saved before, reuse THAT saved name
            remembered = (self._config.get("doc_names", {}) or {}).get(key)
            label = remembered or underscore_name(title)
            # #5: naam me document-number aur/ya date apne aap jodo
            try:
                path = it.data(QtCore.Qt.UserRole)
                extra = []
                if self._opts.get("name_append_number"):
                    num = extract_doc_number(page_ocr_text(path, 0.75))
                    if num:
                        extra.append(num)
                if self._opts.get("name_append_date"):
                    extra.append(datetime.datetime.now().strftime("%Y-%m-%d"))
                if extra:
                    label = underscore_name(label + "_" + "_".join(extra))
            except Exception:
                pass
            it.setData(TITLE_ROLE, label)
            it.setData(NAMEKEY_ROLE, key)
            # naam khaali reh gaya to bhi kuch dikhe — 'Page N' fallback
            it.setText(label if (label and label.strip())
                       else ("Page %d" % (row + 1)))
            self._named_count = getattr(self, "_named_count", 0) + 1
            self._pstats_bump(ocr_named=1)
            # #2: is naam ke liye folder yaad ho to save wahin default ho
            self._apply_folder_hint_for(title)

    def _apply_folder_hint_for(self, title):
        """Seekhe naam ke saath jo folder yaad hai (agar hai) use save-hint bana do."""
        try:
            base = underscore_name(title).lower()
            for e in (self._config.get("learned_names", []) or []):
                if e.get("folder") and underscore_name(e.get("name", "")).lower() in base:
                    if os.path.isdir(e["folder"]):
                        self._doc_folder_hint = e["folder"]
                        return
        except Exception:
            pass

    def _on_naming_done(self):
        got = getattr(self, "_named_count", 0)
        total = getattr(self, "_named_total", 0)
        if got == 0:
            self.status.clearMessage()
            self._warn(
                "OCR ran, but no page name could be found.\n\n"
                "There can be 2 reasons:\n"
                "1) Tesseract was not found properly \u2014 open Help \u2192 Test/Diagnostics and "
                "check the 'Tesseract version' line (says WORKS or NOT FOUND).\n"
                "2) There is no clearly printed heading at the TOP of the page (e.g. handwritten pages) \u2014 "
                "such pages don't get a name, which is normal.")
        else:
            self.status.showMessage("Found names for %d / %d pages." % (got, total), 6000)

    def _build_shortcuts(self):
        methods = {
            "scan": self.do_scan,
            "dpi_150": lambda: self._scan_at_dpi(150),
            "dpi_200": lambda: self._scan_at_dpi(200),
            "dpi_300": lambda: self._scan_at_dpi(300),
            "dpi_600": lambda: self._scan_at_dpi(600),
            "dpi_custom": self._scan_at_dpi_custom,
            "import": self.import_images,
            "rename": self._rename_shortcut,
            "save_all": self.save_pdf_all,
            "save_sel": self.save_pdf_selected,
            "save_pw": self.save_pdf_password,
            "save_img": self.save_images,
            "ocr_text": self.export_ocr_text,
            "print": self.print_pages,
            "rotate_left": self.rotate_left,
            "rotate_right": self.rotate_right,
            "bright_up": lambda: self._enhance_current(1.12, 1.0),
            "bright_dn": lambda: self._enhance_current(0.9, 1.0),
            "contrast_up": lambda: self._enhance_current(1.0, 1.15),
            "contrast_dn": lambda: self._enhance_current(1.0, 0.88),
            "autocrop": self.autocrop_current,
            "autoname": self.auto_name_pages,
            "undo": self._hist_undo,
            "redo": self._hist_redo_do,
            "delete": self.delete_page,
            "clear": self.clear_all,
            "move_up": self.move_up,
            "move_down": self.move_down,
            "search": self.search_pdfs,
            "merge": self.merge_pdfs,
            "split": self.split_pdfs,
            "report": self.monthly_report,
            "zoom_in": lambda: self._zoom_thumbs(1.15),
            "zoom_out": lambda: self._zoom_thumbs(0.87),
            "options": self.open_options,
            "profiles": self.open_profiles,
        }
        self._sc = {}
        custom = self._opts.get("shortcuts", {}) or {}
        for sid, label, default in SHORTCUTS:
            fn = methods.get(sid)
            if fn is None:
                continue
            scut = QtWidgets.QShortcut(self)
            scut.activated.connect(fn)
            key = custom.get(sid, default)
            if key:
                scut.setKey(QtGui.QKeySequence(key))
            self._sc[sid] = scut
        # Enter/Return se Scan — LEKIN 'Meri Files' panel me focus ho to nahi
        # (wahan Enter = folder kholo). Focus badalte hi scan-shortcut on/off.
        try:
            app = QtWidgets.QApplication.instance()
            if app is not None:
                app.focusChanged.connect(self._on_focus_changed_scan)
        except Exception:
            pass
        QtCore.QTimer.singleShot(0, self._refresh_shortcut_line)

    def _on_focus_changed_scan(self, _old, now):
        """Meri Files panel me focus ho to Enter=Scan band, warna chalu."""
        sc = self._sc.get("scan")
        if sc is None:
            return
        try:
            fp = getattr(self, "files_panel", None)
            in_panel = bool(fp and now is not None and (now is fp or fp.isAncestorOf(now)))
            sc.setEnabled(not in_panel)
        except Exception:
            pass

    def _set_panel_dpi(self, n):
        """Resolution combo ko is dpi par set karo (shortcut se)."""
        if not hasattr(self, "cmb_dpi"):
            return
        item = "%d dpi" % n
        self.cmb_dpi.blockSignals(True)
        if self.cmb_dpi.findText(item) < 0:
            self.cmb_dpi.insertItem(max(0, self.cmb_dpi.count() - 1), item)
        self.cmb_dpi.setCurrentText(item)
        self.cmb_dpi.blockSignals(False)
        try:
            self.status.showMessage(self.L("Resolution: %d dpi", "Resolution: %d dpi") % n, 3000)
        except Exception:
            pass

    def _set_panel_dpi_custom(self):
        n, ok = QtWidgets.QInputDialog.getInt(
            self, self.L("Apni DPI", "Custom DPI"),
            self.L("DPI likho (50–1200):", "Enter DPI (50–1200):"), 300, 50, 1200, 50)
        if ok:
            self._set_panel_dpi(n)

    def _scan_at_dpi(self, n):
        """DPI shortcut: profile ki baaki setting + is dpi par ek scan.
        Panel/profile me kuch nahi badalta (sirf yeh ek scan us dpi par)."""
        self.do_scan(dpi_override=n)

    def _scan_at_dpi_custom(self):
        """F7: apni DPI poochho, phir usi par ek scan (panel nahi badalta)."""
        n, ok = QtWidgets.QInputDialog.getInt(
            self, self.L("Apni DPI", "Custom DPI"),
            self.L("DPI likho (50–1200):", "Enter DPI (50–1200):"), 300, 50, 1200, 50)
        if ok:
            self.do_scan(dpi_override=n)

    def _refresh_shortcut_line(self):
        """Toolbar ke neeche wali line — abhi ke (user ke) shortcuts dikhao."""
        if not hasattr(self, "lbl_shortcuts"):
            return
        custom = self._opts.get("shortcuts", {}) or {}

        def k(sid, default):
            key = custom.get(sid, default)
            return "—" if not key else key.replace("Return", "Enter")
        left = (("rename", "F2", "Rename"), ("dpi_150", "F3", "Scan 150dpi"),
                ("dpi_200", "F4", "Scan 200dpi"), ("dpi_300", "F5", "Scan 300dpi"),
                ("dpi_600", "F6", "Scan 600dpi"), ("dpi_custom", "F7", "Scan Custom"))
        right = (("scan", "Return", "Scan"), ("save_sel", "Space", "Selected save"),
                 ("save_all", "Ctrl+S", "Save all"))
        p1 = ["<b>%s</b> = %s" % (k(sid, dflt), lbl) for sid, dflt, lbl in left]
        p2 = ["<b>%s</b> = %s" % (k(sid, dflt), lbl) for sid, dflt, lbl in right]
        self.lbl_shortcuts.setText(
            "⌨&nbsp; " + "  ·  ".join(p1)
            + "&nbsp;&nbsp;|&nbsp;&nbsp;" + "  ·  ".join(p2))

    def _apply_shortcut(self, sid, key):
        scut = self._sc.get(sid)
        if scut is not None:
            scut.setKey(QtGui.QKeySequence(key) if key else QtGui.QKeySequence())
        self._refresh_shortcut_line()      # neeche wali line bhi update

    def _cur_shortcut(self, sid, default):
        return (self._opts.get("shortcuts", {}) or {}).get(sid, default)

    def show_shortcuts(self):
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle("Keyboard Shortcuts"); dlg.resize(560, 560)
        lay = QtWidgets.QVBoxLayout(dlg)
        lay.addWidget(QtWidgets.QLabel(
            "To change a shortcut: pick a row → press the new key in the 'New' box → Assign."))
        tbl = QtWidgets.QTableWidget(len(SHORTCUTS), 2)
        tbl.setHorizontalHeaderLabels(["Action", "Shortcut"])
        tbl.verticalHeader().setVisible(False)
        tbl.setEditTriggers(QtWidgets.QAbstractItemView.NoEditTriggers)
        tbl.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
        tbl.setSelectionMode(QtWidgets.QAbstractItemView.SingleSelection)
        tbl.horizontalHeader().setStretchLastSection(True); tbl.setColumnWidth(0, 300)

        def refill():
            for r, (sid, label, default) in enumerate(SHORTCUTS):
                tbl.setItem(r, 0, QtWidgets.QTableWidgetItem(label))
                tbl.setItem(r, 1, QtWidgets.QTableWidgetItem(self._cur_shortcut(sid, default) or "—"))
        refill()
        lay.addWidget(tbl, 1)

        row = QtWidgets.QHBoxLayout()
        kseq = QtWidgets.QKeySequenceEdit()
        row.addWidget(QtWidgets.QLabel("New:")); row.addWidget(kseq, 1)
        b_assign = QtWidgets.QPushButton("Assign"); b_unassign = QtWidgets.QPushButton("Unassign")
        row.addWidget(b_assign); row.addWidget(b_unassign)
        lay.addLayout(row)

        def sel():
            r = tbl.currentRow()
            return (SHORTCUTS[r][0], r) if r >= 0 else (None, -1)

        def do_assign():
            sid, r = sel()
            if sid is None:
                return
            key = kseq.keySequence().toString()
            if not key:
                return
            sm = self._opts.setdefault("shortcuts", {})
            for osid, olabel, odef in SHORTCUTS:      # clear conflicts
                if osid != sid and self._cur_shortcut(osid, odef) == key:
                    sm[osid] = ""; self._apply_shortcut(osid, "")
            sm[sid] = key; self._apply_shortcut(sid, key); self._save_opts()
            kseq.clear(); refill()

        def do_unassign():
            sid, r = sel()
            if sid is None:
                return
            self._opts.setdefault("shortcuts", {})[sid] = ""
            self._apply_shortcut(sid, ""); self._save_opts(); refill()

        b_assign.clicked.connect(do_assign); b_unassign.clicked.connect(do_unassign)

        bottom = QtWidgets.QHBoxLayout()
        b_reset = QtWidgets.QPushButton("Restore Defaults")

        def do_reset():
            self._opts["shortcuts"] = {}
            for sid, label, default in SHORTCUTS:
                self._apply_shortcut(sid, default)
            self._save_opts(); refill()
        b_reset.clicked.connect(do_reset)
        b_ok = QtWidgets.QPushButton("OK"); b_ok.clicked.connect(dlg.accept)
        bottom.addWidget(b_reset); bottom.addStretch(1); bottom.addWidget(b_ok)
        lay.addLayout(bottom)
        dlg.exec_()

    def _stats_url(self):
        if "stats_url" in self._config:
            return self._config["stats_url"]      # user override (may be "" to disable)
        return DEFAULT_STATS_URL

    def _get_client_id(self):
        cid = self._config.get("client_id")
        if not cid:
            import uuid
            cid = uuid.uuid4().hex[:16]
            self._config["client_id"] = cid
            try:
                save_config(self._config)
            except Exception:
                pass
        return cid

    def _set_stats_display(self, stats):
        if stats and isinstance(stats, tuple) and len(stats) == 3:
            ws = getattr(self, "_world_stats", {}) or {}
            ws.update({"total": stats[0], "today": stats[1], "online": stats[2]})
            self._world_stats = ws
        self._update_sidebar_stats()

    def _stats_failed(self):
        # network na ho to bhi personal stats dikhti rahein
        self._update_sidebar_stats()

    # ================= STATS (naya, seedha-saada) =================
    # NOTE: Pehle alag 'StatsWorker' (QThread + custom signals) istemal hota
    # tha — kisi wajah se uska signal sidebar tak nahi pahunchta tha aur
    # worldwide numbers '...' par atke reh jate the (jabki network theek tha).
    # Ab wahi PROVEN background system (FuncWorker, jo save/edit me chalta hai)
    # se fetch karte hain — ye bharosemand hai.

    def _run_bg_quiet(self, fn, on_done):
        """_run_bg jaisa hi — par bina 'busy' pill ke (background stats/poll ke
        liye). FuncWorker ko list me rakhta hai taaki GC na ho."""
        self._bg_workers = getattr(self, "_bg_workers", [])
        w = FuncWorker(fn)

        def _fin(res, w=w):
            try:
                self._bg_workers.remove(w)
            except ValueError:
                pass
            try:
                on_done(res)
            except Exception:
                pass
        w.done.connect(_fin)
        self._bg_workers.append(w)
        w.start()

    # =================================================================
    #  ANALYTICS (NAYA — bilkul fresh; personal + worldwide)
    #  Networking ka asli fix: background thread me SIRF unverified SSL
    #  context (ssl._create_unverified_context) — ye Windows ka cert-store
    #  LOAD hi nahi karta, isliye thread me kabhi hang/fail nahi hota
    #  (yahi purani dikkat thi: verified context thread me atak jata tha).
    # =================================================================
    def _an_url(self):
        u = self._config.get("stats_url")
        if u is None:
            u = DEFAULT_STATS_URL
        return u or ""

    def _an_fetch(self, params, on_data):
        """Server se ek request (background, UI nahi rukti). on_data(dict|None)."""
        url = self._an_url()
        if not url:
            on_data(None); return
        ver = VERSION

        def fn():
            import urllib.request as U
            import urllib.parse as P
            import json as J
            import ssl
            ctx = ssl._create_unverified_context()   # thread-safe (cert-store load nahi)
            full = url + ("&" if "?" in url else "?") + P.urlencode(params)
            req = U.Request(full, headers={"User-Agent": "ApneScan/%s" % ver})
            try:
                r = U.urlopen(req, timeout=15, context=ctx)
                return J.loads(r.read().decode("utf-8", "ignore"))
            except Exception:
                return None

        def done(res):
            on_data(res if isinstance(res, dict) else None)
        self._run_bg_quiet(fn, done)

    def _an_apply(self, data):
        if data and data.get("ok"):
            self._an_world = data
            try:
                self._an_handle_broadcast(data)
            except Exception:
                pass
            try:
                self._an_apply_rconfig(data.get("rconfig"))
            except Exception:
                pass
        self._an_update_box()

    def _an_handle_broadcast(self, data):
        """Server (admin panel) se aaya message app me ek baar dikhao."""
        msg = (data.get("broadcast") or "").strip()
        bid = int(data.get("broadcastId") or 0)
        if not msg or not bid:
            return
        if self._config.get("last_broadcast_id") == bid:
            return                       # ye message pehle dikha chuke
        self._config["last_broadcast_id"] = bid
        try:
            save_config(self._config)
        except Exception:
            pass
        try:
            self.status.showMessage("📣 " + msg, 15000)
        except Exception:
            pass
        try:
            QtWidgets.QMessageBox.information(
                self, self.L("ApneScan — Sandesh", "ApneScan — Message"), msg)
        except Exception:
            pass

    def _an_apply_rconfig(self, cfg):
        """Remote config: admin panel se bina update ke kuch safe settings badlo.
        Har naye config ko ek hi baar lagate hain (user baad me khud badal sakta)."""
        if not isinstance(cfg, dict) or not cfg:
            return
        self._rconfig = cfg
        try:
            import json as _j
            sig = _j.dumps(cfg, sort_keys=True)
        except Exception:
            sig = str(cfg)
        if self._config.get("rcfg_sig") == sig:
            return
        self._config["rcfg_sig"] = sig
        # sirf jaani-pehchaani safe key: default DPI
        dpi = cfg.get("default_dpi")
        if dpi:
            try:
                self._opts["dpi"] = max(50, min(1200, int(dpi)))
            except Exception:
                pass
        try:
            save_config(self._config)
            self._save_opts()
        except Exception:
            pass

    def _ev_push(self, name):
        """(v183) HAR chhota-bada kaam admin Activity-Feed me dikhane ke liye —
        events yahan jama hote hain aur 60 second me EK saath jaate hain
        (server halka rahta hai). Sirf kaam ka NAAM jaata hai, koi data nahi."""
        try:
            q = getattr(self, "_ev_q", None)
            if q is None:
                q = self._ev_q = []
                t = self._ev_timer = QtCore.QTimer(self)
                t.setInterval(60000)
                t.timeout.connect(self._ev_flush)
                t.start()
            q.append([int(time.time()), str(name)[:32]])
            del q[:-200]                      # memory-cap
            if len(q) >= 40:                  # bhara ho to abhi bhej do
                self._ev_flush()
        except Exception:
            pass

    def _ev_flush(self):
        q = getattr(self, "_ev_q", None)
        if not q:
            return
        batch, self._ev_q = q[:40], q[40:]
        try:
            p = {"action": "evbatch", "client": self._get_client_id(),
                 "v": VERSION, "c": self._an_country(), "u": self._user_name(),
                 "events": json.dumps(batch, separators=(",", ":"))}
            self._an_fetch(p, lambda _d: None)
        except Exception:
            pass

    def _hook_menu_events(self):
        """Menu ke HAR option par chupchaap event-ginti (admin feed ke liye)."""
        def walk(menu):
            for a in menu.actions():
                sub = a.menu()
                if sub is not None:
                    walk(sub)
                elif not a.isSeparator() and a.text():
                    a.triggered.connect(
                        lambda _c=False, nm=a.text():
                        self._ev_push("menu:" + nm.replace("&", "").replace("❓ ", "")[:24]))
        try:
            for act in self.menuBar().actions():
                if act.menu() is not None:
                    walk(act.menu())
        except Exception:
            pass

    def _an_event(self, feat, kb=0, pg=0):
        """Feature usage worldwide bhejo (OCR/compress/merge/sign/print…).
        kb = kitne KB bache (compress), pg = kitne pages (merge/print)."""
        try:
            meta = {}
            if kb:
                meta["kb"] = int(kb)
            if pg:
                meta["pg"] = int(pg)
            self._an_report("event", feat=feat, meta=(meta or None))
        except Exception:
            pass

    def _an_scan_meta(self):
        """Scan ke settings (DPI / colour / size) + scanner model — worldwide
        breakdown ke liye. Sirf ginti/setting jaati hai, koi document nahi."""
        col = {"color": "Colour", "gray": "Grayscale", "bw": "B&W"}.get(
            str(self._opts.get("color", "")), str(self._opts.get("color", "")))
        m = {"dpi": self._opts.get("dpi", ""), "col": col,
             "sz": self._opts.get("page_size", ""),
             "sm": (self._opts.get("scanner_name", "") or "")[:40]}
        # (v183) scan-detail: kitne second laga + srot + profile (privacy-safe)
        try:
            si = getattr(self, "_scan_info", None) or {}
            if si.get("t0"):
                m["dur"] = int(max(0, min(3600, time.time() - si["t0"])))
            if si.get("src"):
                m["src"] = si["src"]
            if si.get("prof"):
                m["prof"] = si["prof"]
        except Exception:
            pass
        # (v204) auto-rotate ka nateeja bhi: rot="ghumaye/kul", tess=0/1
        try:
            lo = getattr(self, "_last_orient", None)
            if lo:
                m["rot"] = "%d/%d" % (lo[0], lo[1])
                m["tess"] = 1 if lo[2] else 0
        except Exception:
            pass
        return m

    def _an_feedback(self, rating, msg):
        """User feedback + rating admin panel ko bhejo."""
        p = {"action": "feedback", "client": self._get_client_id(), "v": VERSION,
             "c": self._an_country(), "u": self._user_name(),
             "rating": str(int(rating)), "msg": (msg or "")[:400]}
        self._an_fetch(p, self._an_apply)

    def send_feedback(self):
        """Feedback/rating dialog — seedha admin panel me pahunchta hai."""
        items = ["⭐⭐⭐⭐⭐  (5)", "⭐⭐⭐⭐  (4)", "⭐⭐⭐  (3)",
                 "⭐⭐  (2)", "⭐  (1)"]
        r, ok = QtWidgets.QInputDialog.getItem(
            self, self.L("Feedback bhejo", "Send feedback"),
            self.L("App ko kitne star doge?", "How many stars?"),
            items, 0, False)
        if not ok:
            return
        rating = 5 - items.index(r)
        msg, ok2 = QtWidgets.QInputDialog.getMultiLineText(
            self, self.L("Aapki raay", "Your feedback"),
            self.L("Kya achha laga / kya sudhaar chahiye? (optional)",
                   "What did you like / what to improve? (optional)"), "")
        if not ok2:
            return
        try:
            self._an_feedback(rating, msg.strip())
            self.status.showMessage(
                self.L("🙏 Shukriya! Aapki raay bhej di gayi.",
                       "🙏 Thanks! Your feedback was sent."), 6000)
        except Exception:
            pass

    # ===================== OCR LANGUAGES (feature 12) =====================
    OCR_LANGS = [("eng", "English"), ("hin", "हिन्दी Hindi"), ("guj", "ગુજરાતી Gujarati"),
                 ("mar", "मराठी Marathi"), ("tam", "தமிழ் Tamil"), ("tel", "తెలుగు Telugu"),
                 ("ben", "বাংলা Bengali"), ("pan", "ਪੰਜਾਬੀ Punjabi"), ("kan", "ಕನ್ನಡ Kannada"),
                 ("mal", "മലയാളം Malayalam"), ("ori", "ଓଡ଼ିଆ Odia"), ("urd", "اردو Urdu")]

    def _ocr_lang(self):
        """OCR ke liye chuni gayi bhashaayein (Tesseract format, jaise 'eng+hin')."""
        return self._opts.get("ocr_langs") or "eng+hin"

    def choose_ocr_langs(self):
        """User chun sakta hai OCR kin bhashaon me padhe."""
        cur = set((self._opts.get("ocr_langs") or "eng+hin").split("+"))
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle(self.L("OCR bhashaayein", "OCR languages"))
        v = QtWidgets.QVBoxLayout(dlg)
        v.addWidget(QtWidgets.QLabel(self.L(
            "OCR kin bhashaon me text padhe? (zyada = thoda dheere)",
            "Which languages should OCR read? (more = a bit slower)")))
        boxes = {}
        lw = QtWidgets.QWidget(); lg = QtWidgets.QVBoxLayout(lw)
        for code, name in self.OCR_LANGS:
            cb = QtWidgets.QCheckBox(name + "  (" + code + ")")
            cb.setChecked(code in cur)
            lg.addWidget(cb); boxes[code] = cb
        sc = QtWidgets.QScrollArea(); sc.setWidget(lw); sc.setWidgetResizable(True); sc.setMinimumHeight(300)
        v.addWidget(sc)
        note = QtWidgets.QLabel(self.L(
            "Note: nayi bhasha ke liye us bhasha ka Tesseract language-pack install hona chahiye.",
            "Note: a language needs its Tesseract language-pack installed to work."))
        note.setStyleSheet("color:#64748b;font-size:11px"); note.setWordWrap(True); v.addWidget(note)
        bb = QtWidgets.QDialogButtonBox(QtWidgets.QDialogButtonBox.Ok | QtWidgets.QDialogButtonBox.Cancel)
        bb.accepted.connect(dlg.accept); bb.rejected.connect(dlg.reject); v.addWidget(bb)
        if dlg.exec_() != QtWidgets.QDialog.Accepted:
            return
        chosen = [c for c, _ in self.OCR_LANGS if boxes[c].isChecked()]
        if not chosen:
            chosen = ["eng", "hin"]
        self._opts["ocr_langs"] = "+".join(chosen)
        self._save_opts()
        self.status.showMessage(self.L("🔤 OCR bhasha set: ", "🔤 OCR languages: ")
                                + self._opts["ocr_langs"], 5000)

