    # ===================== PHONE COMPANION (feature 9) =====================
    def phone_scan(self, send_files=None):
        """Phone se scan — INTERNET se (kahin se bhi; same WiFi zaroori NahI).
        Relay session bane to internet-mode dialog; na bane (net band /
        server down / URL khaali) to purana local-WiFi mode.
        send_files diya ho (My Files -> right-click -> Phone ko bhejo) to QR
        dikhte hi wo file(s) apne aap phone ko bhej di jaati hain."""
        L = self.L
        self._an_event("phonescan")
        send_files = [f for f in (send_files or []) if os.path.isfile(f)]
        base = (self._opts.get("phone_relay_url") or "").strip()
        sess = None
        if base:
            try:
                QtWidgets.QApplication.setOverrideCursor(QtCore.Qt.WaitCursor)
                try:
                    sess = _relay.create_session(base, ttl=1800)
                finally:
                    QtWidgets.QApplication.restoreOverrideCursor()
            except Exception:
                sess = None
        if sess is None:
            # (v217) internet-relay fail — local par gir rahe hain PAR user ko
            # bata do kyun (warna 'sirf local par chalta hai' lagta hai)
            self._phone_scan_local(relay_failed=bool(base))
            return

        url = sess["url"]
        poller = RelayPoller(base, sess["token"], sess["key"], self._tmpdir, self)
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle(L("📱 Phone se scan — kahin se bhi", "📱 Scan from phone — anywhere"))
        dlg.setMinimumWidth(400)
        v = QtWidgets.QVBoxLayout(dlg)
        v.addWidget(QtWidgets.QLabel(L(
            "<b>Internet se — phone kahin bhi ho, chalega.</b><br>"
            "Phone ke camera se ye QR scan karo:",
            "<b>Works over the internet — the phone can be anywhere.</b><br>"
            "Scan this QR with the phone camera:")))
        try:
            qimg = self._app_qr_image(url=url, box=8)
        except Exception:
            qimg = None
        if qimg is not None:
            try:
                data = qimg.tobytes("raw", "RGB")
                qim = QtGui.QImage(data, qimg.width, qimg.height, 3 * qimg.width, QtGui.QImage.Format_RGB888)
                lab = QtWidgets.QLabel(); lab.setAlignment(QtCore.Qt.AlignCenter)
                lab.setPixmap(QtGui.QPixmap.fromImage(qim.copy()).scaled(
                    250, 250, QtCore.Qt.KeepAspectRatio, QtCore.Qt.SmoothTransformation))
                v.addWidget(lab)
            except Exception:
                pass
        lrow = QtWidgets.QHBoxLayout()
        link = QtWidgets.QLabel("<b>%s</b>" % url)
        link.setWordWrap(True); link.setTextInteractionFlags(QtCore.Qt.TextSelectableByMouse)
        link.setStyleSheet("color:#475569;font-size:11px")
        bcopy = QtWidgets.QPushButton(L("📋 Copy link", "📋 Copy link"))
        bcopy.setFixedWidth(110)

        def _copy():
            try:
                QtWidgets.QApplication.clipboard().setText(url)
                bcopy.setText(L("✅ Copy ho gayi", "✅ Copied"))
                QtCore.QTimer.singleShot(1800, lambda: bcopy.setText(L("📋 Copy link", "📋 Copy link")))
            except Exception:
                pass
        bcopy.clicked.connect(_copy)
        lrow.addWidget(link, 1); lrow.addWidget(bcopy)
        lw = QtWidgets.QWidget(); lw.setLayout(lrow); v.addWidget(lw)
        status_lbl = QtWidgets.QLabel(L("🟡 Intezaar… (link WhatsApp se bhi bhej sakte ho)",
                                        "🟡 Waiting… (you can also send the link on WhatsApp)"))
        status_lbl.setWordWrap(True)
        status_lbl.setStyleSheet("color:#64748b;font-size:11.5px"); v.addWidget(status_lbl)
        count_lbl = QtWidgets.QLabel(L("Abhi tak 0 file aayi", "0 files received"))
        count_lbl.setStyleSheet("font-weight:700;color:#4F46E5;margin-top:4px"); v.addWidget(count_lbl)
        exp_lbl = QtWidgets.QLabel("")
        exp_lbl.setStyleSheet("color:#94a3b8;font-size:11px"); v.addWidget(exp_lbl)
        # (v281) Downloads-folder link — har aayi file yahin save hoti hai;
        # click par folder khulta hai aur nayi file HIGHLIGHT (sabse upar) dikhti.
        dl_lbl = QtWidgets.QLabel("")
        dl_lbl.setTextFormat(QtCore.Qt.RichText)
        dl_lbl.setOpenExternalLinks(False)
        dl_lbl.setStyleSheet("font-size:12px;margin-top:4px")
        dl_lbl.linkActivated.connect(lambda _h: self._open_downloads_select(
            getattr(self, "_last_download", None)))
        dl_lbl.hide(); v.addWidget(dl_lbl)

        self._phone_n = 0
        self._last_download = None
        self._relay_left = int(sess.get("ttl") or 1800)

        _IMGX = (".jpg", ".jpeg", ".png", ".bmp", ".webp", ".heic", ".heif", ".tif", ".tiff")

        def on_file(path, name):
            low = str(name or path).lower()
            # (v281) HAR aayi file ki ek copy Downloads folder me — turant.
            dest = self._save_to_downloads(path, os.path.basename(str(name or "file")))
            if dest:
                self._last_download = dest
                self._phone_n += 1
                count_lbl.setText(L("✅ '%s' Downloads me save ho gayi (kul %d)",
                                    "✅ '%s' saved to Downloads (total %d)")
                                  % (os.path.basename(dest), self._phone_n))
                dl_lbl.setText(
                    '📂 <a href="#" style="color:#2563EB;font-weight:700;text-decoration:none;">%s</a>'
                    % L("Downloads folder kholo (nayi file upar)", "Open Downloads (newest on top)"))
                dl_lbl.show()
                try:
                    QtWidgets.QApplication.beep()
                except Exception:
                    pass
            # image/PDF ko scan-page bhi banao (scan-from-phone feature)
            try:
                if low.endswith(".pdf"):
                    for pg in (pdf_to_images(path, self._tmpdir) or []):
                        self._add_item_for_path(pg)
                elif low.endswith(_IMGX):
                    self._add_item_for_path(self._clean_incoming_photo(path))
            except Exception:
                pass

        def on_info(st):
            try:
                if st.get("ok"):
                    self._relay_left = int(st.get("left") or self._relay_left)
                    if st.get("files"):
                        status_lbl.setText(L("📥 File aa rahi hai…", "📥 Receiving…"))
                    elif self._phone_n:
                        status_lbl.setText(L("🟢 Jude hue — aur files ka intezaar",
                                             "🟢 Connected — waiting for more"))
                    else:
                        status_lbl.setText(L("🟡 Intezaar… QR scan hone ka",
                                             "🟡 Waiting for the QR to be scanned…"))
                elif st.get("net"):
                    status_lbl.setText(L("🌐 Internet me rukavat — dobara koshish ho rahi…",
                                         "🌐 Network hiccup — retrying…"))
                else:
                    status_lbl.setText(L("⛔ Link expire ho gayi — dobara kholo",
                                         "⛔ Link expired — open again"))
                    poll_t.stop(); tick_t.stop()
            except Exception:
                pass
        poller.file_got.connect(on_file)     # thread -> queued (main thread)
        poller.info.connect(on_info)

        def _tick():
            self._relay_left = max(0, self._relay_left - 1)
            mm, ss = divmod(self._relay_left, 60)
            exp_lbl.setText(L("⏱ Link %d:%02d me apne aap band ho jayegi · files server se turant delete hoti hain",
                              "⏱ Link auto-expires in %d:%02d · files are deleted from the server immediately") % (mm, ss))
            if self._relay_left <= 0:
                tick_t.stop()
        poll_t = QtCore.QTimer(dlg); poll_t.timeout.connect(poller.poll); poll_t.start(3000)
        tick_t = QtCore.QTimer(dlg); tick_t.timeout.connect(_tick); tick_t.start(1000)
        _tick(); poller.poll()

        # (v277) DO-TARFA: computer se phone ko bhi file bhejo (koi bhi file).
        # Phone apne QR-page par "Computer se aayi files" me download kar lega.
        sent_lbl = QtWidgets.QLabel("")
        sent_lbl.setWordWrap(True)
        sent_lbl.setStyleSheet("color:#0D9488;font-size:11.5px"); v.addWidget(sent_lbl)

        def _do_send(files):
            files = [f for f in (files or []) if os.path.isfile(f)]
            if not files:
                return
            sent_lbl.setText(L("📤 Phone ko bhej rahe…", "📤 Sending to the phone…"))

            def job():
                ok = 0
                for f in files:
                    try:
                        _relay.send_to_phone(base, sess["token"], sess["key"], f)
                        ok += 1
                    except Exception:
                        pass
                return ok

            def done(n):
                if isinstance(n, Exception):
                    n = 0
                if n:
                    try:
                        self._an_event("sendphone")   # (v286) admin analytics
                    except Exception:
                        pass
                sent_lbl.setText(L(
                    "📤 %d file phone ko bhej di — phone par QR scan karke '⬇️ Computer se aayi files' me download karo" % n,
                    "📤 Sent %d file(s) — on the phone, scan the QR and download under '⬇️ Files from computer'" % n))
            self._run_bg(job, done, L("Phone ko bhej rahe…", "Sending to the phone…"))

        def _send_to_phone():
            files, _ = QtWidgets.QFileDialog.getOpenFileNames(
                dlg, L("Phone ko bhejne ke liye file(s) chuno", "Choose file(s) to send to the phone"),
                self._opts.get("save_folder", os.path.expanduser("~")), "All files (*.*)")
            _do_send(files)

        # (v284) SAAF FLOW — pehle QR (upar) phone se scan karo; PHIR yahan se
        # jitni chaahe file(s) attach karke bhejo. Dialog khula rehne tak har
        # attach turant phone par download ke liye pahunch jaati hai.
        bsend = QtWidgets.QPushButton(L("➕ File attach karke phone ko bhejo",
                                        "➕ Attach file(s) to send to the phone"))
        bsend.setStyleSheet(
            "QPushButton{background:#0D9488;color:#fff;font-weight:700;border:none;"
            "border-radius:9px;padding:11px 14px;font-size:14px;}"
            "QPushButton:hover{background:#0B7C72;}")
        bsend.clicked.connect(_send_to_phone); v.addWidget(bsend)
        note = QtWidgets.QLabel(L(
            "Pehle upar wala QR phone se scan karo — phir jitni chaahe file(s) attach karo, sab phone par '⬇️ Computer se aayi files' me aa jayengi.",
            "Scan the QR above on the phone first — then attach as many files as you like; all appear on the phone under 'Files from computer'."))
        note.setWordWrap(True); note.setStyleSheet("color:#94a3b8;font-size:10.5px"); v.addWidget(note)

        b = QtWidgets.QPushButton(L("Ho gaya (band karo)", "Done (close)"))
        b.clicked.connect(dlg.accept); v.addWidget(b)
        # right-click 'Phone ko bhejo' se aayi ho to QR dikhte hi wo file bhej do
        if send_files:
            QtCore.QTimer.singleShot(300, lambda: _do_send(send_files))
        dlg.exec_()
        poll_t.stop(); tick_t.stop()
        poller.shutdown()
        if self._phone_n:
            self.status.showMessage(L("📱 %d file phone se aayi.", "📱 %d file(s) from phone.") % self._phone_n, 6000)

    def _send_files_to_phone(self, files):
        """(v284) My Files -> 'Phone ko bhejo': QR-dialog kholo; QR scan hote hi
        chuni file(s) phone ko bhej di jaati hain (phir aur bhi attach kar sakte)."""
        files = [f for f in (files or []) if os.path.isfile(f)]
        if not files:
            return
        self.phone_scan(send_files=files)

    def _downloads_dir(self):
        """(v281) Windows/Linux ka Downloads folder (na ho to ~ )."""
        d = os.path.join(os.path.expanduser("~"), "Downloads")
        try:
            if not os.path.isdir(d):
                os.makedirs(d, exist_ok=True)
        except Exception:
            d = os.path.expanduser("~")
        return d

    def _save_to_downloads(self, tmp_path, name):
        """(v281) Phone se aayi file ki copy Downloads folder me — asli naam se
        (takraaye to '1','2'…). Returns saved path ya None."""
        try:
            base = self._downloads_dir()
            safe = re.sub(r'[<>:"/\\|?*]', "_", name or "file").strip() or "file"
            dest = os.path.join(base, safe)
            if hasattr(self, "_unique_fs_path"):
                dest = self._unique_fs_path(dest)
            shutil.copy2(tmp_path, dest)
            return dest
        except Exception:
            return None

    def _open_downloads_select(self, path=None):
        """(v281) Downloads folder kholo; nayi file ho to use HIGHLIGHT karke
        (Explorer /select — file dikh jaati hai, chahe kahin bhi ho)."""
        d = self._downloads_dir()
        try:
            if path and os.path.isfile(path) and sys.platform.startswith("win"):
                import subprocess
                subprocess.Popen(["explorer", "/select,", os.path.normpath(path)])
                return
        except Exception:
            pass
        try:
            self._open_path(d)
        except Exception:
            pass

    def _phone_save_other(self, tmp_path, name):
        """(v279) Phone se aayi image/PDF ke alawa koi bhi file (video/office/
        zip…) ko save-folder (My Files) me rakho. Returns saved path ya None."""
        try:
            base = (self._opts.get("save_folder")
                    or (self._files_root() if hasattr(self, "_files_root") else "")
                    or os.path.expanduser("~"))
            if not os.path.isdir(base):
                os.makedirs(base, exist_ok=True)
            safe = re.sub(r'[<>:"/\\|?*]', "_", name or "file").strip() or "file"
            dest = os.path.join(base, safe)
            if hasattr(self, "_unique_fs_path"):
                dest = self._unique_fs_path(dest)
            shutil.copy2(tmp_path, dest)
            try:
                if hasattr(self, "_refresh_files_root"):
                    self._refresh_files_root()
            except Exception:
                pass
            return dest
        except Exception:
            return None

    def _phone_scan_local(self, relay_failed=False):
        """Purana LOCAL WiFi mode (internet/relay na ho to) — same-WiFi QR."""
        L = self.L
        srv = PhoneServer(self._tmpdir, self)
        try:
            ip, port = srv.start()
        except Exception as e:
            self._warn(L("Phone-server chalu nahi hua: ", "Could not start phone server: ") + str(e))
            return
        if ip == "127.0.0.1":
            self._warn(L("WiFi/network nahi mila. PC ko WiFi/LAN se jodo aur dobara koshish karo.",
                         "No WiFi/network found. Connect the PC to WiFi/LAN and try again."))
            srv.stop(); return
        url = "http://%s:%d/?t=%s" % (ip, port, srv.token)

        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle(L("📱 Phone se scan (same WiFi)", "📱 Scan from phone (same WiFi)"))
        dlg.setMinimumWidth(380)
        v = QtWidgets.QVBoxLayout(dlg)
        # (v217) relay fail hua to saaf batao: abhi sirf same-WiFi kyun
        if relay_failed:
            _wn = QtWidgets.QLabel(L(
                "⚠ <b>Internet-mode abhi uplabdh nahi</b> — isliye abhi sirf "
                "same-WiFi. Internet se (kahin se bhi) chalane ke liye server "
                "par <b>phone_relay.php</b> hona chahiye (ya internet check karo).",
                "⚠ <b>Internet mode unavailable</b> — using same-WiFi for now. "
                "For internet (from anywhere), the server needs "
                "<b>phone_relay.php</b> (or check your internet)."))
            _wn.setWordWrap(True)
            _wn.setStyleSheet("background:#FEF3C7;color:#92400E;border:1px solid #FCD34D;"
                              "border-radius:8px;padding:7px 9px;font-size:11px;")
            v.addWidget(_wn)
        v.addWidget(QtWidgets.QLabel(L(
            "<b>1.</b> Phone aur PC ek hi WiFi par ho.<br>"
            "<b>2.</b> Phone ke camera se ye QR scan karo:",
            "<b>1.</b> Put phone &amp; PC on the same WiFi.<br>"
            "<b>2.</b> Scan this QR with your phone camera:")))
        # QR (PIL image -> QPixmap, jaise show_app_qr me)
        try:
            qimg = self._app_qr_image(url=url, box=8)
        except Exception:
            qimg = None
        if qimg is not None:
            try:
                data = qimg.tobytes("raw", "RGB")
                qim = QtGui.QImage(data, qimg.width, qimg.height, 3 * qimg.width, QtGui.QImage.Format_RGB888)
                lab = QtWidgets.QLabel(); lab.setAlignment(QtCore.Qt.AlignCenter)
                lab.setPixmap(QtGui.QPixmap.fromImage(qim.copy()).scaled(
                    240, 240, QtCore.Qt.KeepAspectRatio, QtCore.Qt.SmoothTransformation))
                v.addWidget(lab)
            except Exception:
                pass
        link = QtWidgets.QLabel(L("Ya phone browser me kholo:<br><b>%s</b>", "Or open in phone browser:<br><b>%s</b>") % url)
        link.setWordWrap(True); link.setStyleSheet("color:#475569;font-size:11px"); v.addWidget(link)
        count_lbl = QtWidgets.QLabel(L("Abhi tak 0 photo aayi — intezaar…", "0 photos received — waiting…"))
        count_lbl.setStyleSheet("font-weight:700;color:#4F46E5;margin-top:6px"); v.addWidget(count_lbl)

        self._phone_n = 0

        def on_photo(path):
            try:
                # (v211) photo aate hi scan-jaisi saaf (auto)
                self._add_item_for_path(self._clean_incoming_photo(path))
            except Exception:
                return
            self._phone_n += 1
            count_lbl.setText(L("✅ %d photo aa gayi — phone se aur bhej sakte ho",
                                "✅ %d photo(s) received — send more from the phone") % self._phone_n)
            try:
                QtWidgets.QApplication.beep()
            except Exception:
                pass
        srv.photo.connect(on_photo)          # cross-thread -> queued (main thread me chalta)

        note = QtWidgets.QLabel(L(
            "Pehli baar Windows 'Firewall' puche to <b>Allow</b> dabao.",
            "If Windows Firewall asks the first time, click <b>Allow</b>."))
        note.setStyleSheet("color:#94a3b8;font-size:11px"); note.setWordWrap(True); v.addWidget(note)
        b = QtWidgets.QPushButton(L("Ho gaya (band karo)", "Done (close)"))
        b.clicked.connect(dlg.accept); v.addWidget(b)
        dlg.exec_()
        srv.stop()
        if self._phone_n:
            self.status.showMessage(L("📱 %d photo phone se aayi.", "📱 %d photo(s) from phone.") % self._phone_n, 6000)

    def _an_country(self):
        """System se desh-code (jaise 'IN') — sirf ginti/desh-breakdown ke liye."""
        try:
            nm = QtCore.QLocale.system().name()   # jaise 'en_IN'
            if "_" in nm:
                return nm.split("_", 1)[1][:2].upper()
        except Exception:
            pass
        return ""

    def _user_name(self):
        """Analytics me dikhane ke liye user ka naam (config me)."""
        return (self._config.get("user_name") or "")[:40]

    def _ensure_user_name(self):
        """(v186) Install ke baad pehli baar naam likhna ZAROORI hai —
        admin panel me 'kaun kya kar raha hai' naam ke SAATH dikhta hai.
        3 baar tak puchte hain; phir bhi na de to Windows-username apne
        aap naam ban jaata hai (khaali kabhi nahi rahta). Jin purane
        users ka naam khaali hai, unse bhi (update ke baad) puchega."""
        if (self._config.get("user_name") or "").strip():
            return
        try:
            import getpass
            _pre = getpass.getuser()
        except Exception:
            _pre = ""
        got = ""
        for _try in range(3):
            try:
                name, ok = QtWidgets.QInputDialog.getText(
                    self, self.L("Apna naam likhein (zaroori)",
                                 "Enter your name (required)"),
                    self.L("Shuru karne se pehle apna naam ya clinic/PC ka naam\n"
                           "likhna ZAROORI hai (jaise 'Dr Subhash', 'ECHS OPD',\n"
                           "'OPD-2'). Sirf naam jaata hai — koi document/patient\n"
                           "data nahi:",
                           "Before you start, you MUST enter your name or your\n"
                           "clinic/PC name (e.g. 'Dr Subhash', 'ECHS OPD',\n"
                           "'OPD-2'). Only the name is sent — no document or\n"
                           "patient data:"),
                    text=_pre)
            except Exception:
                ok = False; name = ""
            name = (name or "").strip()
            if ok and len(name) >= 2:
                got = name
                break
            if _try < 2:
                try:
                    QtWidgets.QMessageBox.warning(
                        self, APP_NAME,
                        self.L("Naam likhna zaroori hai — bina naam ke aage nahi "
                               "badh sakte. Krupya apna naam likhein.",
                               "A name is required — you cannot continue without "
                               "one. Please enter your name."))
                except Exception:
                    pass
        if not got:
            # 3 baar mana kiya -> Windows-username hi naam ban jaata hai
            got = (_pre or "User") + " (PC)"
        self._config["user_name"] = got[:40]
        self._config["user_name_asked"] = True
        try:
            save_config(self._config)
        except Exception:
            pass
        # naam turant server ko bhejo
        try:
            self._an_report("ping")
        except Exception:
            pass

    def set_user_name(self):
        """Analytics wala naam kabhi bhi badlo."""
        cur = self._config.get("user_name", "")
        name, ok = QtWidgets.QInputDialog.getText(
            self, self.L("Analytics me naam", "Analytics name"),
            self.L("Aapka naam / clinic (analytics me dikhega):",
                   "Your name / clinic (shown in analytics):"), text=cur)
        if not ok:
            return
        self._config["user_name"] = name.strip()[:40]
        self._config["user_name_asked"] = True
        try:
            save_config(self._config)
        except Exception:
            pass
        try:
            self._an_report("ping")
        except Exception:
            pass
        self.status.showMessage(self.L("👤 Naam set: ", "👤 Name set: ")
                                + (self._config["user_name"] or "—"), 5000)

    def _an_refresh(self):
        """Worldwide numbers laao + sidebar/box taaza karo. client + desh + method
        + naam bhejte hain taaki server rank/desh/method/naam bhi bhar sake."""
        self._an_fetch({"action": "stats", "client": self._get_client_id(),
                        "v": VERSION, "c": self._an_country(),
                        "m": self._opts.get("scanner_method", ""),
                        "u": self._user_name(),
                        "lang": self._opts.get("language", ""),
                        "mode": ("simple" if self._opts.get("simple_mode") else "full")},
                       self._an_apply)

    def _an_report(self, action, n=0, imp=0, prt=0, feat="", meta=None):
        """scan / ping / event (import-print-feature) server ko bhejo + display taaza."""
        p = {"action": action, "client": self._get_client_id(), "v": VERSION,
             "c": self._an_country(), "m": self._opts.get("scanner_method", ""),
             "u": self._user_name(),
             "lang": self._opts.get("language", ""),
             "mode": ("simple" if self._opts.get("simple_mode") else "full")}
        if n:
            p["n"] = str(n)
        if imp:
            p["imp"] = str(imp)
        if prt:
            p["prt"] = str(prt)
        if feat:
            p["feat"] = str(feat)[:20]
        if meta:
            for k, v in meta.items():
                if v not in (None, ""):
                    p[k] = str(v)[:40]
        self._an_fetch(p, self._an_apply)

    def _an_wv(self, key):
        w = getattr(self, "_an_world", {}) or {}
        v = w.get(key)
        try:
            return "{:,}".format(int(v))
        except Exception:
            return "…"

    def _an_rawv(self, key):
        """(v262) raw int value (missing→0) — world table sort ke liye."""
        w = getattr(self, "_an_world", {}) or {}
        try:
            return int(w.get(key))
        except Exception:
            return 0

    def _update_world_lbl(self):
        """(v257) Sidebar (storage box ke upar) me duniya ke live counters:
        Total/Today scan + Import + Print + WhatsApp + Rename + Phone scan."""
        lbl = getattr(self, "_world_lbl", None)
        if lbl is None:
            return
        try:
            lbl.setWordWrap(True)
        except Exception:
            pass
        try:
            wv = self._an_wv
            rawv = self._an_rawv
            # (v261) 3-column TABLE — col1: analytics ka naam, col2: World Total,
            # col3: Aaj (Today) ka total. Har metric ki dono value ek saath.
            # (v262) column headers CLICKABLE — single click par us column se sort,
            # dobara click par direction ulta (upar-se-niche / niche-se-upar).
            # rows = (icon, label, total_key, today_key, icon_colour)
            rows = [
                ("🖨", self.L("Scan", "Scan"),    "total",     "today",           "#4F46E5"),
                ("💾", self.L("PDF Save", "PDF Save"), "pdfs",  "pdfs_today",      "#DC2626"),
                ("📥", self.L("Import", "Import"), "imports",   "imports_today",   "#EA580C"),
                ("🖨", "Print",                    "prints",    "prints_today",    "#2563EB"),
                ("🟢", "WhatsApp",                 "whatsapps", "whatsapps_today", "#16A34A"),
                ("✏", "Rename",                    "renames",   "renames_today",   "#9333EA"),
                ("📱", self.L("Phone", "Phone"),   "phones",    "phones_today",    "#DB2777"),
            ]
            # sort state: (column, descending). default = Aaj (Today), bada upar.
            scol, sdesc = getattr(self, "_world_sort", ("today", True))
            if scol == "name":
                rows.sort(key=lambda r: r[1].lower(), reverse=sdesc)
            elif scol == "today":
                rows.sort(key=lambda r: rawv(r[3]), reverse=sdesc)
            else:  # "world"
                rows.sort(key=lambda r: rawv(r[2]), reverse=sdesc)

            def _arw(col):
                # active column par direction arrow, warna khaali
                if col == scol:
                    return " ▼" if sdesc else " ▲"
                return ""

            # (v264) REDESIGN — chhoti font + slim colour-dot (emoji ki jagah).
            # (v266) font aur chhoti (8px) + padding kam => teeno column ek saath
            # poore dikhein, kuch cut na ho. white-space:nowrap => kabhi wrap nahi.
            h = ['<table width="100%" cellspacing="0" cellpadding="1" '
                 'style="font-size:8px;">']
            # heading
            h.append('<tr><td colspan="3" style="padding:0px 2px 2px;">'
                     '<b style="color:#4338CA;font-size:9.5px;">🌍 %s</b></td></tr>'
                     % self.L("Duniya", "World"))
            # column headers (Name | World | Today) — clickable links.
            # white-space:nowrap => koi bhi text/number kabhi wrap nahi hoga.
            def _hcell(col, text, align):
                return ('<td align="%s" bgcolor="#4F46E5" '
                        'style="color:#FFFFFF;font-size:7.5px;padding:2px 3px;'
                        'white-space:nowrap;">'
                        '<a href="wsort:%s" style="color:#FFFFFF;text-decoration:none;">'
                        '<b>%s%s</b></a></td>'
                        % (align, col, text, _arw(col)))
            h.append(
                '<tr>'
                + _hcell("name", self.L("Analytics", "Analytics"), "left")
                + _hcell("world", self.L("World", "World"), "right")
                + _hcell("today", self.L("Aaj", "Today"), "right")
                + '</tr>')
            for i, (ic, lab, tkey, dkey, col) in enumerate(rows):
                bg = "#F1F3FC" if (i % 2 == 0) else "#FFFFFF"
                # value me comma ki jagah non-breaking rakho — number kabhi na tute
                vt = wv(tkey).replace(",", "&#8239;")
                vd = wv(dkey).replace(",", "&#8239;")
                h.append(
                    '<tr>'
                    '<td bgcolor="%s" style="color:#374151;padding:2px 3px;'
                    'white-space:nowrap;">'
                    '<span style="color:%s;font-size:9px;">&#9679;</span>&nbsp;%s</td>'
                    '<td bgcolor="%s" align="right" style="padding:2px 3px;'
                    'white-space:nowrap;"><b style="color:#111827;">%s</b></td>'
                    '<td bgcolor="%s" align="right" style="padding:2px 3px;'
                    'white-space:nowrap;"><b style="color:#0D9488;">%s</b></td>'
                    '</tr>' % (bg, col, lab, bg, vt, bg, vd))
            h.append('</table>')
            lbl.setText("".join(h))
        except Exception:
            pass

    def _world_sort_click(self, link):
        """(v262) World table column header click — us column se sort; agar
        wahi column dobara click ho to direction ulta kar do."""
        try:
            col = str(link).split(":", 1)[1] if ":" in str(link) else str(link)
        except Exception:
            return
        if col not in ("name", "world", "today"):
            return
        scol, sdesc = getattr(self, "_world_sort", ("today", True))
        if col == scol:
            sdesc = not sdesc            # same column → direction toggle
        else:
            # naya column → naam A→Z se, numbers bade-se-chhote se shuru
            sdesc = (col != "name")
        self._world_sort = (col, sdesc)
        self._update_world_lbl()

