    def _an_report_lines(self):
        L = self.L
        st = self._pstats(); t = st.get("totals", {})
        now = datetime.datetime.now()
        day = (st.get("days") or {}).get(now.strftime("%Y-%m-%d"), {})
        bd, bh, wkday, wkend = self._an_busiest()
        return [
            "ApneScan — %s" % now.strftime("%d %b %Y, %I:%M %p"),
            "",
            L("Aaj: %d pages, %d PDF", "Today: %d pages, %d PDF") % (day.get("pages", 0), day.get("pdfs", 0)),
            L("Is hafte: %d pages", "This week: %d pages") % self._pstats_sum(7),
            L("Is mahine: %d pages", "This month: %d pages") % self._an_range_sum(0, 30),
            L("Kul: %s pages, %s PDF", "Total: %s pages, %s PDF")
            % ("{:,}".format(t.get("pages", 0)), "{:,}".format(t.get("pdfs", 0))),
            L("Import: %s, Print: %s, Share: %s",
              "Imports: %s, Prints: %s, Shares: %s")
            % (t.get("imports", 0), t.get("prints", 0), t.get("shared", 0)),
            L("Streak: %d din (sabse lamba %d)", "Streak: %d days (longest %d)")
            % (self._pstats_streak(), self._an_longest_streak()),
            L("Sabse busy: %s, %s", "Busiest: %s, %s") % (bd, bh),
        ]

    def _analytics_daily_summary(self):
        txt = "\n".join(self._an_report_lines())
        QtWidgets.QApplication.clipboard().setText(txt)
        self.status.showMessage(self.L("📋 Summary copy ho gaya", "📋 Summary copied"), 4000)
        QtWidgets.QMessageBox.information(self, self.L("Aaj ka summary", "Today's summary"), txt)

    def _an_report_pdf_path(self):
        """Report ko ek A4 PDF (image) me banakar path do."""
        img = Image.new("RGB", (1240, 1754), "white")
        d = ImageDraw.Draw(img)
        try:
            f_big = ImageFont.truetype("arialbd.ttf", 54)
            f = ImageFont.truetype("arial.ttf", 34)
        except Exception:
            f_big = ImageFont.load_default(); f = f_big
        d.rectangle([0, 0, 1240, 120], fill=(15, 118, 110))
        d.text((50, 34), "ApneScan — Analytics", fill="white", font=f_big)
        y = 180
        for line in self._an_report_lines()[2:]:
            d.text((60, y), line, fill=(30, 41, 59), font=f); y += 64
        fd, out = tempfile.mkstemp(suffix=".pdf", dir=self._tmpdir); os.close(fd)
        img.save(out, "PDF", resolution=150.0)
        return out

    def _analytics_report_pdf(self):
        try:
            tmp = self._an_report_pdf_path()
        except Exception as e:
            self._warn(str(e)); return
        out, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, self.L("Report PDF save", "Save report PDF"),
            os.path.join(self._files_root(), "ApneScan_Report.pdf"), "PDF (*.pdf)")
        if not out:
            return
        try:
            shutil.copyfile(tmp, out)
            self.status.showMessage(self.L("📄 Report save: ", "📄 Report saved: ") + os.path.basename(out), 6000)
        except Exception as e:
            self._warn(str(e))

    def _analytics_report_xlsx(self):
        out, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, self.L("Excel/CSV save", "Save Excel/CSV"),
            os.path.join(self._files_root(), "ApneScan_Stats.csv"), "CSV (*.csv)")
        if not out:
            return
        try:
            days = self._pstats().get("days", {})
            import csv
            with open(out, "w", newline="", encoding="utf-8") as fh:
                wcsv = csv.writer(fh)
                wcsv.writerow(["date", "pages", "pdfs", "imports", "prints", "shared"])
                for ds in sorted(days.keys()):
                    dd = days[ds]
                    wcsv.writerow([ds, dd.get("pages", 0), dd.get("pdfs", 0),
                                   dd.get("imports", 0), dd.get("prints", 0), dd.get("shared", 0)])
            self.status.showMessage(self.L("📊 Save ho gaya: ", "📊 Saved: ") + os.path.basename(out), 6000)
        except Exception as e:
            self._warn(str(e))

    def _analytics_print_report(self):
        try:
            self._do_print([self._an_report_pdf_path()], per_page=1)
        except Exception as e:
            self._warn(str(e))

    def _analytics_share_report(self):
        try:
            self.share_whatsapp(self._an_report_pdf_path())
        except Exception as e:
            self._warn(str(e))

    def _stats_nam(self):
        """Qt ka apna network manager (main event-loop par — koi thread nahi).
        Redirect follow karta hai aur SSL-error ko ignore (sirf public ginti)."""
        if getattr(self, "_nam", None) is None:
            self._nam = QNetworkAccessManager(self)
            try:    # HTTPS cert dikkat ho to bhi ruke nahi (yahan sirf ginti hai)
                self._nam.sslErrors.connect(lambda reply, errs: reply.ignoreSslErrors())
            except Exception:
                pass
            try:    # Apps Script 302 redirect follow karo (Qt 5.9+)
                self._nam.setRedirectPolicy(QNetworkRequest.NoLessSafeRedirectPolicy)
            except Exception:
                pass
        return self._nam

    def _stats_fetch(self, action="stats", n=0, imp=0, prt=0, want_display=True):
        """Stats server se ek request — Qt network se (UI nahi rukti, thread
        nahi). Naye sire se banaya — pehle urllib+thread wala rasta kuch
        machino par kaam nahi karta tha."""
        url = self._stats_url()
        if not url:
            return
        if not HAS_QTNET:      # Qt-network na ho to seedha urllib fallback
            self._stats_fetch_urllib(action, n, imp, prt, want_display)
            return
        import urllib.parse as P
        try:
            country = (QtCore.QLocale().name().split("_") + [""])[1][:2]
        except Exception:
            country = ""
        q = {"action": action, "client": self._get_client_id(),
             "v": VERSION, "c": country}
        if action == "scan" and n:
            q["n"] = str(n)
        if imp:
            q["imp"] = str(imp)
        if prt:
            q["prt"] = str(prt)
        full = url + ("&" if "?" in url else "?") + P.urlencode(q)
        req = QNetworkRequest(QtCore.QUrl(full))
        req.setHeader(QNetworkRequest.UserAgentHeader, "ApneScan/%s" % VERSION)
        try:    # purane Qt (5.6-5.14) me redirect isse follow hota hai
            req.setAttribute(QNetworkRequest.FollowRedirectsAttribute, True)
        except Exception:
            pass
        reply = self._stats_nam().get(req)
        self._stat_replies = getattr(self, "_stat_replies", [])
        self._stat_replies.append(reply)

        def _done():
            try:
                self._stat_replies.remove(reply)
            except Exception:
                pass
            data = None
            try:
                raw = bytes(reply.readAll()).decode("utf-8", "ignore")
                import json
                data = json.loads(raw)
            except Exception:
                data = None
            try:
                reply.deleteLater()
            except Exception:
                pass
            if not want_display:
                return
            if isinstance(data, dict) and data.get("ok"):
                self._on_world_stats(data)
                self._set_stats_display((int(data.get("total", 0)),
                                         int(data.get("today", 0)),
                                         int(data.get("online", 0))))
            else:
                # Qt se na aaya to purana (urllib+thread) rasta ek baar aajma lo
                self._stats_fetch_urllib(action, n, imp, prt, want_display)
        reply.finished.connect(_done)

    def _stats_fetch_urllib(self, action="stats", n=0, imp=0, prt=0, want_display=True):
        """Fallback: agar Qt-network kaam na kare to urllib se (background thread).
        FuncWorker ka proven rasta — GC-safe."""
        url = self._stats_url()
        if not url:
            self._stats_failed(); return
        client = self._get_client_id(); ver = VERSION
        try:
            country = (QtCore.QLocale().name().split("_") + [""])[1][:2]
        except Exception:
            country = ""

        def fn():
            import urllib.request as U
            import urllib.parse as P
            import json as J
            import ssl
            q = {"action": action, "client": client, "v": ver, "c": country}
            if action == "scan" and n:
                q["n"] = str(n)
            if imp:
                q["imp"] = str(imp)
            if prt:
                q["prt"] = str(prt)
            full = url + ("&" if "?" in url else "?") + P.urlencode(q)
            req = U.Request(full, headers={"User-Agent": "ApneScan/%s" % ver})
            for mk in (lambda: U.urlopen(req, timeout=20),
                       lambda: U.urlopen(req, timeout=20, context=ssl._create_unverified_context())):
                try:
                    r = mk()
                    return J.loads(r.read().decode("utf-8", "ignore"))
                except Exception:
                    continue
            return None

        def on_done(data):
            if not want_display:
                return
            if isinstance(data, dict) and data.get("ok"):
                self._on_world_stats(data)
                self._set_stats_display((int(data.get("total", 0)),
                                         int(data.get("today", 0)),
                                         int(data.get("online", 0))))
            else:
                self._stats_failed()
        self._run_bg_quiet(fn, on_done)

