        _GRP = {
            "blue":   _grp_qss("#bfdbfe", "#eff6ff", "#1d4ed8"),
            "green":  _grp_qss("#bbf7d0", "#f0fdf4", "#15803d"),
            "purple": _grp_qss("#e9d5ff", "#faf5ff", "#7e22ce"),
            "slate":  _grp_qss("#e2e8f0", "#f1f5f9", "#475569"),
        }

