    # ---- G) mark ----
    def _img_watermark(self, path):
        txt, ok = QtWidgets.QInputDialog.getText(
            self, self.L("Watermark", "Watermark"),
            self.L("Kya likhein?", "Watermark text:"),
            text=self.L("COPY", "COPY"))
        txt = (txt or "").strip()
        if not ok or not txt:
            return
