    def _unique_fs_path(self, path, is_dir=False, exclude=None):
        """Agar 'path' (file/folder) pehle se maujood hai to naam ke aage
        ' 1', ' 2'... lagakar ek NAYA na-takraane wala path lauta do.
        File me number extension SE PEHLE aata hai ('Bill 1.pdf'),
        folder me naam ke aant me ('Reports 1').
        'exclude' path (jaise rename me khud source file) ko takraav nahi
        maana jaata, taaki same-naam par bewajah number na lage."""
        exclude_norm = None
        if exclude:
            try:
                exclude_norm = os.path.normcase(os.path.abspath(exclude))
            except Exception:
                exclude_norm = None

        def _taken(p):
            if exclude_norm is not None:
                try:
                    if os.path.normcase(os.path.abspath(p)) == exclude_norm:
                        return False
                except Exception:
                    pass
            return os.path.exists(p)

        if not _taken(path):
            return path
        d = os.path.dirname(path)
        base = os.path.basename(path)
        if is_dir:
            stem, ext = base, ""
        else:
            stem, ext = os.path.splitext(base)
        n = 1
        while True:
            cand = os.path.join(d, "%s %d%s" % (stem, n, ext))
            if not _taken(cand):
                return cand
            n += 1
            if n > 100000:          # safety — kabhi lagna nahi chahiye
                return cand

    def _new_folder_in(self, base):
        name, ok = QtWidgets.QInputDialog.getText(
            self, "New folder",
            "Folder name:\n(will be created inside: '%s')" % (os.path.basename(base) or "My Files"))
        if not ok or not name.strip():
            return
        p = os.path.join(base, folder_safe_name(name))   # NEW folders: spaces, readable
        # (v231) same naam ka folder pehle se ho to ' 1', ' 2'... apne aap
        p = self._unique_fs_path(p, is_dir=True)
        try:
            os.makedirs(p, exist_ok=True)
        except Exception as exc:
            self._warn("Could not create folder:\n%s" % exc)
            return
        # (v196) naya folder bante hi APNE AAP khul jaata hai
        try:
            self._jump_to_folder(p)
        except Exception:
            pass
        self.status.showMessage("Folder created: %s" % os.path.basename(p), 4000)

    def _toggle_fav(self, path):
        favs = self._opts.setdefault("fav_folders", [])
        if path in favs:
            favs.remove(path)
            msg = self.L("⭐ Favourite hata diya", "⭐ Removed from favourites")
        else:
            favs.append(path)
            while len(favs) > 12:
                favs.pop(0)
            msg = self.L("⭐ Favourite me jud gaya", "⭐ Added to favourites")
        self._save_opts()
        self._rebuild_fav_bar()
        try:
            self.status.showMessage(msg, 3000)
        except Exception:
            pass

    def _toggle_pin(self, path):
        """File ko 📌 pin/unpin — pinned files '📌 Pinned' filter me upar dikhti hain."""
        pins = self._opts.setdefault("pinned_files", [])
        if path in pins:
            pins.remove(path); msg = self.L("📌 Pin hataya", "📌 Unpinned")
        else:
            pins.append(path)
            while len(pins) > 50:
                pins.pop(0)
            msg = self.L("📌 Pin kar diya (📌 Pinned filter me dekho)",
                         "📌 Pinned (see the 📌 Pinned filter)")
        self._save_opts()
        self.status.showMessage(msg, 3000)
        try:
            if hasattr(self, "files_filter") and self.files_filter.currentData() == "pinned":
                self._apply_files_filter()
        except Exception:
            pass

    def _print_library_file(self, path):
        """(v201) Saved file APNE print-dialog se — printer/copies/pages
        chunne ke poore option ke saath (pehle seedha default printer par
        chala jaata tha, kuch pooche bina)."""
        try:
            ext = os.path.splitext(path)[1].lower()
            if ext == ".pdf":
                self.status.showMessage(self.L("PDF ke pages taiyaar ho rahe hain…",
                                               "Preparing PDF pages…"), 0)
                QtWidgets.QApplication.processEvents()
                pages = pdf_to_images(path, self._tmpdir, dpi=200) or []
                self.status.showMessage("", 1)
                if pages:
                    self._do_print(pages)
                    return
            elif ext in (".png", ".jpg", ".jpeg", ".bmp", ".tif", ".tiff", ".webp"):
                self._do_print([path])
                return
            # PDF pages nahi ban paye ya Word/Excel jaisa format —
            # purana raasta: system se print
            os.startfile(path, "print")
            self.status.showMessage(self.L("🖨 Print par bhej diya", "🖨 Sent to printer"), 4000)
        except Exception:
            try:
                self._open_path(path)
            except Exception as e:
                self._warn(str(e))

    def _zip_folder(self, folder):
        """Poore folder ki ek ZIP banao (backup / bhejne ke liye) — background me."""
        if not folder or not os.path.isdir(folder):
            return
        default = os.path.join(os.path.dirname(folder),
                               (os.path.basename(folder) or "files") + ".zip")
        out, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, self.L("ZIP save karein", "Save ZIP"), default, "ZIP (*.zip)")
        if not out:
            return
        if not out.lower().endswith(".zip"):
            out += ".zip"

        def job():
            import zipfile
            base = os.path.dirname(folder)
            with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
                for dp, _dns, fn in os.walk(folder):
                    for f in fn:
                        fp = os.path.join(dp, f)
                        if os.path.abspath(fp) == os.path.abspath(out):
                            continue
                        z.write(fp, os.path.relpath(fp, base))
            return out

        def done(res):
            if isinstance(res, Exception):
                self._warn(self.L("ZIP nahi bani:\n", "ZIP failed:\n") + str(res)); return
            self.status.showMessage(self.L("🗜 ZIP ban gayi: ", "🗜 ZIP created: ")
                                    + os.path.basename(res), 8000)
            try:
                self._open_path(os.path.dirname(res))
            except Exception:
                pass
        self._run_bg(job, done, self.L("ZIP bana rahe…", "Zipping…"))

    def _bulk_rename(self, files):
        """Kai files ko ek naam + number (naam_001, naam_002…) me rename karo."""
        if not files:
            return
        base, ok = self._ask_name(
            self.L("Bulk rename", "Bulk rename"),
            self.L("Sabhi ke liye ek naam (aage number apne aap lagega):",
                   "One base name (a number is appended automatically):"), "doc")
        if not ok or not base.strip():
            return
        base = underscore_name(base.strip()) or "doc"     # (v227) space rehta — sanitize nahi
        n = 0
        for i, p in enumerate(sorted(files, key=lambda x: os.path.basename(x).lower()), 1):
            try:
                ext = os.path.splitext(p)[1]
                new = os.path.join(os.path.dirname(p), "%s_%03d%s" % (base, i, ext))
                if os.path.abspath(new) == os.path.abspath(p):
                    n += 1; continue
                if os.path.exists(new):
                    continue
                os.rename(p, new)
                n += 1
            except Exception:
                pass
        self._invalidate_files_index()
        self.status.showMessage(self.L("✏ %d files rename ho gayi" % n,
                                       "✏ Renamed %d files" % n), 5000)

    def _resplit_legacy_name(self, stem):
        """Purane version ke bina-space/underscore naam me space wapas laao.
        'Prem_Kanwar' -> 'Prem Kanwar'; '2391300SohanSingh' -> '2391300 Sohan Singh'.
        Naye version pehle se theek naam banate hain — ye sirf purani files ke liye."""
        s = re.sub(r"[_]+", " ", stem or "")
        s = re.sub(r"(?<=\d)(?=[A-Za-z])", " ", s)         # 2391300Sohan -> 2391300 Sohan
        s = re.sub(r"(?<=[A-Za-z])(?=\d)", " ", s)         # Sohan12 -> Sohan 12
        s = re.sub(r"(?<=[a-z])(?=[A-Z])", " ", s)         # SohanSingh -> Sohan Singh
        s = re.sub(r"(?<=[A-Z])(?=[A-Z][a-z])", " ", s)    # ABCFoo -> ABC Foo
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _fix_old_names_in_folder(self, folder):
        """Ek folder ki purani files ke naam theek karo — space wapas (underscore /
        juda hua naam). Pehle preview + confirm, phir rename. Turant chalta hai."""
        if not folder or not os.path.isdir(folder):
            return
        exts = (".pdf", ".jpg", ".jpeg", ".png", ".tif", ".tiff", ".bmp", ".webp")
        plan = []
        try:
            for fn in sorted(os.listdir(folder)):
                fp = os.path.join(folder, fn)
                if not os.path.isfile(fp):
                    continue
                stem, ext = os.path.splitext(fn)
                if ext.lower() not in exts:
                    continue
                fixed = underscore_name(self._resplit_legacy_name(stem))
                if fixed and fixed != stem:
                    plan.append((fp, stem, fixed, ext))
        except Exception as exc:
            self._warn(self.L("Folder padha nahi ja saka:\n%s" % exc,
                              "Could not read folder:\n%s" % exc))
            return
        if not plan:
            QtWidgets.QMessageBox.information(
                self, self.L("Purane naam theek karo", "Fix old names"),
                self.L("Is folder ke sabhi naam pehle se theek hain — kuch badalne "
                       "ki zaroorat nahi.",
                       "All names in this folder already look fine — nothing to change."))
            return
        lines = ["  %s%s   →   %s%s" % (old, ext, new, ext)
                 for (_fp, old, new, ext) in plan[:12]]
        more = ("" if len(plan) <= 12 else
                self.L("\n  …aur %d aur" % (len(plan) - 12),
                       "\n  …and %d more" % (len(plan) - 12)))
        msg = self.L(
            "%d files ke naam theek honge (space wapas):\n\n%s%s\n\nAage badhein?",
            "%d files will be renamed (spaces restored):\n\n%s%s\n\nProceed?"
        ) % (len(plan), "\n".join(lines), more)
        if QtWidgets.QMessageBox.question(
                self, self.L("Purane naam theek karo", "Fix old names"), msg,
                QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
                QtWidgets.QMessageBox.No) != QtWidgets.QMessageBox.Yes:
            return
        done = 0
        for fp, _old, new, ext in plan:
            try:
                newp = os.path.join(folder, new + ext)
                if os.path.abspath(newp) == os.path.abspath(fp):
                    continue
                if os.path.exists(newp):                    # naam takra jaye to number lagao
                    k = 2
                    while os.path.exists(os.path.join(folder, "%s %d%s" % (new, k, ext))):
                        k += 1
                    newp = os.path.join(folder, "%s %d%s" % (new, k, ext))
                os.rename(fp, newp)
                done += 1
            except Exception:
                pass
        self._invalidate_files_index()
        try:
            self._jump_to_folder(folder)
        except Exception:
            pass
        self.status.showMessage(self.L("✓ %d naam theek kiye" % done,
                                       "✓ Fixed %d names" % done), 6000)

    def _find_duplicates(self):
        """Ek jaisi (nakli) files dhoondo — pehle size, phir content (md5) se."""
        scope = self._panel_current_dir()
        if not (scope and os.path.isdir(scope)):
            scope = self._files_root()

        def job():
            import hashlib
            by_size = {}
            for dp, _dns, fn in os.walk(scope):
                for f in fn:
                    if not f.lower().endswith(self._FILE_EXTS):
                        continue
                    fp = os.path.join(dp, f)
                    try:
                        by_size.setdefault(os.path.getsize(fp), []).append(fp)
                    except Exception:
                        pass
            dups = []
            for _sz, group in by_size.items():
                if len(group) < 2:
                    continue
                seen = {}
                for fp in group:
                    try:
                        h = hashlib.md5()
                        with open(fp, "rb") as fh:
                            for chunk in iter(lambda: fh.read(65536), b""):
                                h.update(chunk)
                        seen.setdefault(h.hexdigest(), []).append(fp)
                    except Exception:
                        pass
                for _k, same in seen.items():
                    if len(same) >= 2:
                        dups.extend(same)
            return [("file", p) for p in dups]

        def done(res):
            if isinstance(res, Exception):
                return
            if not res:
                self.status.showMessage(self.L("Koi nakli file nahi mili.",
                                               "No duplicate files found."), 4000)
                return
            try:
                self.files_filter.blockSignals(True)
                self.files_filter.setCurrentIndex(0)
                self.files_filter.blockSignals(False)
            except Exception:
                pass
            self._render_files_results(res)
            self.status.showMessage(self.L("🔁 %d nakli files mili (ek jaisi)" % len(res),
                                           "🔁 %d duplicate files found" % len(res)), 6000)
        self._run_bg(job, done, self.L("Nakli files dhoondh rahe…", "Finding duplicates…"))

    def _rebuild_fav_bar(self):
        """Favourites ko dropdown me bharo (galat/hata diye gaye folder chhod do)."""
        # (v187) sidebar ki favourite-folder list bhi saath me taaza karo
        try:
            self._nav_refresh_favs()
        except Exception:
            pass
        if not hasattr(self, "fav_combo"):
            return
        self.fav_combo.blockSignals(True)
        self.fav_combo.clear()
        favs = [p for p in (self._opts.get("fav_folders") or []) if os.path.isdir(p)]
        if favs:
            self.fav_combo.addItem(self.L("⭐ Favourites… (chuno)", "⭐ Favourites… (pick)"), "")
            for p in favs:
                self.fav_combo.addItem("⭐ " + (os.path.basename(p) or p), p)
            self.fav_combo.setEnabled(True)
        else:
            self.fav_combo.addItem(self.L("⭐ (koi favourite nahi)", "⭐ (no favourites yet)"), "")
            self.fav_combo.setEnabled(False)
        self.fav_combo.setCurrentIndex(0)
        self.fav_combo.blockSignals(False)

    def _on_fav_selected(self, _idx):
        p = self.fav_combo.currentData()
        if p:
            self._jump_to_folder(p)
        # wapas placeholder par le aao taaki dobara wahi chuna ja sake
        self.fav_combo.blockSignals(True)
        self.fav_combo.setCurrentIndex(0)
        self.fav_combo.blockSignals(False)

    def _fav_star_clicked(self):
        p = self._selected_library_folder()
        if p and os.path.isdir(p):
            self._toggle_fav(p)

    def _jump_to_folder(self, p):
        """Kisi folder me SEEDHA chalo (drill-in). Base ke andar ho to bas
        usme; bahar ho to use naya base bana do."""
        if not p or not os.path.isdir(p):
            return
        try:
            self.files_search.clear()
            self.files_results.hide(); self.files_tree.show()
        except Exception:
            pass
        base = os.path.normpath(self._files_root())
        npath = os.path.normpath(p)
        under = (npath == base) or npath.startswith(base + os.sep)
        if under:
            self._panel_show(p)
        else:
            self._opts["files_panel_root"] = p
            self._save_opts()
            self._refresh_files_root()

    def _files_result_activated(self, it):
        """Search-result par double-click: folder ho to panel me usme chale
        jao (uske andar ki files dikhein), file ho to use kholo."""
        p = it.data(QtCore.Qt.UserRole)
        if not p:
            return
        if os.path.isdir(p):
            self._jump_to_folder(p)
        else:
            self._open_path(p)

    def _focus_files_search(self):
        """(v290) Ctrl+F — Meri Files panel (band ho to) kholo aur seedha live
        sidebar-search box par focus; pehle se likha text select ho jaye."""
        try:
            fp = getattr(self, "files_panel", None)
            if fp is not None and not fp.isVisible():
                self.toggle_files_panel()
        except Exception:
            pass
        try:
            self.files_search.setFocus(QtCore.Qt.ShortcutFocusReason)
            self.files_search.selectAll()
        except Exception:
            pass

    def _move_results_selection(self, step):
        """(v290) Search-box me ↑/↓ — sidebar-list me agla/pichhla ASLI result
        chuno (header/khaali items skip). Focus search-box me hi rehta hai."""
        lw = self.files_results
        n = lw.count()
        if not n:
            return
        r = lw.currentRow()
        r = 0 if r < 0 else r + step
        while 0 <= r < n:
            it = lw.item(r)
            if it and (it.flags() & QtCore.Qt.ItemIsSelectable) and it.data(QtCore.Qt.UserRole):
                lw.setCurrentRow(r)
                lw.scrollToItem(it)
                return
            r += step

    def _files_search_open_selected(self):
        """(v290) Enter: chuna result kholo; koi na chuna ho to pehla result."""
        lw = self.files_results
        it = lw.currentItem()
        if it is None or not it.data(QtCore.Qt.UserRole):
            it = None
            for i in range(lw.count()):
                c = lw.item(i)
                if c and c.data(QtCore.Qt.UserRole):
                    it = c
                    break
        if it is not None and it.data(QtCore.Qt.UserRole):
            self._files_result_activated(it)

    def _on_result_clicked(self, it):
        """Search-result par EK click: document ho to uska preview panel me
        dikhao (PDF ka pehla page / image seedha). Folder par kuch nahi."""
        p = it.data(QtCore.Qt.UserRole)
        if p and os.path.isfile(p):
            self._preview_file_in_panel(p)

    def _pdf_text_cached(self, path):
        """PDF ke andar ka text (pehle 15 page) — content-search ke liye.
        Har file ka result yaad rakhte hain (path+time se) taaki dobara search
        turant ho. (Sirf digital text wali PDF me milta hai; poori scanned image
        PDF me embedded text nahi hota.)"""
        if not HAS_FITZ:
            return ""
        try:
            mt = os.path.getmtime(path)
        except Exception:
            return ""
        cache = getattr(self, "_pdf_text_cache", None)
        if cache is None:
            cache = self._pdf_text_cache = {}
        key = (path, mt)
        if key in cache:
            return cache[key]
        txt = ""
        try:
            doc = fitz.open(path)
            parts = []
            for i, page in enumerate(doc):
                if i >= 15:
                    break
                parts.append(page.get_text())
            txt = " ".join(parts).lower()
            doc.close()
        except Exception:
            txt = ""
        cache[key] = txt
        if len(cache) > 500:                 # cache bahut bada na ho
            try:
                cache.pop(next(iter(cache)))
            except Exception:
                pass
        return txt

    def _render_file_pixmap(self, path):
        """Kisi file ka QPixmap banao — image seedha, PDF ka pehla page fitz se."""
        ext = os.path.splitext(path)[1].lower()
        if ext in (".jpg", ".jpeg", ".png", ".bmp", ".tif", ".tiff"):
            pm = QtGui.QPixmap(path)
            return pm if not pm.isNull() else None
        if ext == ".pdf" and HAS_FITZ:
            try:
                doc = fitz.open(path)
                page = doc.load_page(0)
                pix = page.get_pixmap(matrix=fitz.Matrix(1.6, 1.6), alpha=False)
                img = QtGui.QImage(pix.samples, pix.width, pix.height,
                                   pix.stride, QtGui.QImage.Format_RGB888)
                pm = QtGui.QPixmap.fromImage(img.copy())
                doc.close()
                return pm if not pm.isNull() else None
            except Exception:
                return None
        return None

    def _render_pdf_all_pages_qimage(self, path, cap=30, zoom=1.3):
        """PDF ke SAARE pages (cap tak) ko ek lambi image me jodo — user neeche
        scroll karke sab dekh sake. QImage/QPainter background thread me safe
        hai, isliye UI kabhi atkegi nahi. Lautata hai (qimage, total_pages,
        offsets) — offsets = har page ke top ka HISSA (0..1) lambi image me,
        taaki filmstrip par click karke us page tak scroll ho jaye."""
        try:
            doc = fitz.open(path)
        except Exception:
            return None, 0, []
        total = doc.page_count
        n = min(total, cap)
        imgs = []
        maxw = 1
        for i in range(n):
            try:
                pix = doc.load_page(i).get_pixmap(matrix=fitz.Matrix(zoom, zoom), alpha=False)
                qi = QtGui.QImage(pix.samples, pix.width, pix.height,
                                  pix.stride, QtGui.QImage.Format_RGB888).copy()
                imgs.append(qi); maxw = max(maxw, qi.width())
            except Exception:
                pass
        doc.close()
        if not imgs:
            return None, total, []
        gap = 14
        total_h = sum(im.height() for im in imgs) + gap * (len(imgs) + 1)
        canvas = QtGui.QImage(maxw, total_h, QtGui.QImage.Format_RGB888)
        canvas.fill(QtGui.QColor("#e5e7eb"))     # halka grey — pages ke beech gap dikhe
        p = QtGui.QPainter(canvas)
        y = gap
        offsets = []
        for im in imgs:
            offsets.append(y / float(total_h))   # is page ka top (fraction)
            x = (maxw - im.width()) // 2
            p.fillRect(x, y, im.width(), im.height(), QtGui.QColor("#ffffff"))
            p.drawImage(x, y, im)
            y += im.height() + gap
        p.end()
        return canvas, total, offsets

    def _pv_file_date(self, path):
        """File ki modified date/time — complete info me dikhane ke liye."""
        try:
            return datetime.datetime.fromtimestamp(
                os.path.getmtime(path)).strftime("%d %b %Y, %I:%M %p")
        except Exception:
            return "-"

    def _pv_img_meta(self, path):
        """Image ki (DPI, colour-mode) — complete info me dikhane ke liye."""
        mode = "-"; dpi = None
        try:
            with Image.open(path) as im:
                mode = {"1": "Black & White", "L": "Grayscale", "RGB": "Colour",
                        "RGBA": "Colour"}.get(im.mode, im.mode)
                dpi = im.info.get("dpi")
        except Exception:
            pass
        dpitxt = ("%d dpi" % int(dpi[0])) if (dpi and dpi[0]) else "—"
        return dpitxt, mode

    def _preview_file_in_panel(self, path):
        """Preview panel me is file ki jhalak dikhao (band ho to khol do).
        Multi-page PDF ke SAARE pages neeche-neeche dikhte hain (scroll)."""
        if not getattr(self, "preview_panel", None):
            return
        if not self.preview_panel.isVisible():
            self.preview_panel.setVisible(True)
            self._opts["ui_preview"] = True
            self._place_an_box()
        name = os.path.basename(path)
        try:
            self.pv_tabs.setCurrentIndex(0)
        except Exception:
            pass
        self._pv_file_path = path            # race-guard (beech me doosri file to)
        try:
            kb = os.path.getsize(path) / 1024.0
            szt = ("%.0f KB" % kb) if kb < 1024 else ("%.1f MB" % (kb / 1024))
        except Exception:
            szt = "-"
        ext = os.path.splitext(path)[1].lower()

        # Multi-page PDF -> saare pages ek lambi image me (BACKGROUND me)
        if ext == ".pdf" and HAS_FITZ:
            self.pv_title.setText(self.L("👁 Khul raha hai…", "👁 Loading…"))

            def job():
                return self._render_pdf_all_pages_qimage(path)

            def done(res):
                if getattr(self, "_pv_file_path", None) != path:
                    return                    # tab tak user ne doosri file chun li
                if isinstance(res, tuple):
                    qi = res[0] if len(res) > 0 else None
                    total = res[1] if len(res) > 1 else 0
                    offsets = res[2] if len(res) > 2 else []
                else:
                    qi, total, offsets = None, 0, []
                if qi is None or qi.isNull():
                    self.pv_img.clear(); self._pv_pm = None
                    self.pv_title.setText(self.L("👁 Preview nahi bana", "👁 No preview"))
                    self.pv_info.setText(name); self.pv_text.setPlainText("")
                    self._pv_showing_file = None
                    self._pv_build_filmstrip()
                    return
                self._pv_pm = QtGui.QPixmap.fromImage(qi)
                self._pv_zoom = 1.0
                capd = self.L(" (pehle 30)", " (first 30)") if total > 30 else ""
                self.pv_title.setText("%s — %d %s%s"
                                      % (name, total, self.L("page", "pages"), capd))
                self._pv_render()
                QtCore.QTimer.singleShot(30, self._pv_render)
                # (v303) filmstrip me is PDF ke SAARE pages 1,2,3… dikhao;
                # kisi par click = us page tak preview scroll ho jaye
                self._pv_showing_file = path
                self._pv_page_offsets = offsets
                self._pv_fill_pdf_strip(offsets)
                self.pv_info.setText(
                    "<b>%s</b><br>🗂 PDF · 📄 %d %s<br>💾 %s<br>📅 %s<br>"
                    "<span style='color:#94a3b8'>%s</span>"
                    % (name, total, self.L("page", "pages"), szt,
                       self._pv_file_date(path), path))
                self.pv_text.setPlainText("")
            self._run_bg_quiet(job, done)
            return

        # Image / single -> seedha (ek hi page — filmstrip saaf)
        self._pv_showing_file = path
        self._pv_page_offsets = []
        try:
            self.pv_strip.clear()
        except Exception:
            pass
        pm = self._render_file_pixmap(path)
        if pm is None:
            self.pv_img.clear(); self._pv_pm = None
            self.pv_title.setText(self.L("👁 Preview nahi bana", "👁 No preview"))
            self.pv_info.setText(name)
            self.pv_info2.setText("<b>%s</b><br><span style='color:#94a3b8'>%s</span>"
                                  % (name, path))
            self.pv_text.setPlainText("")
            return
        self._pv_pm = pm
        self._pv_zoom = 1.0
        self.pv_title.setText(name)
        self._pv_render()
        QtCore.QTimer.singleShot(30, self._pv_render)
        ext = (os.path.splitext(path)[1].lstrip(".").upper() or "FILE")
        dpitxt, mode = self._pv_img_meta(path)
        self.pv_info.setText(
            "<b>%s</b><br>🗂 %s · 📐 %d × %d px<br>🖨 %s · 🎨 %s<br>💾 %s<br>📅 %s<br>"
            "<span style='color:#94a3b8'>%s</span>"
            % (name, ext, pm.width(), pm.height(), dpitxt, mode, szt,
               self._pv_file_date(path), path))
        self.pv_text.setPlainText("")

    # ---- Fast in-memory index (turant search) ----
    _FILE_EXTS = (".pdf", ".jpg", ".jpeg", ".png", ".tif", ".tiff", ".docx", ".xlsx")

    def _invalidate_files_index(self):
        """Folder badla / nayi file bani / delete-import hua — index dobara
        banega, search-cache saaf. (Search kabhi purani list par na atke.)"""
        self._files_index = None
        self._files_index_time = 0
        try:
            _search_engine.clear_cache()
        except Exception:
            pass
        # (v291) index turant (background me) dobara garam kar do — taaki agli
        # baar type karte hi results INSTANT aayein, pehle-keystroke par index
        # banne ka intezaar na karna pade.
        self._prewarm_files_index()

    def _prewarm_files_index(self):
        """(v291) Meri-Files search ka index BACKGROUND me pehle se taiyaar rakho
        (panel khulte hi / folder badalte hi). Isse jab user search likhe to
        index pehle se ready hota hai aur result turant dikhta hai — cold-build
        ka intezaar nahi. Bilkul chup-chaap; UI kabhi nahi rukti."""
        try:
            if not hasattr(self, "files_tree"):
                return
            scope = self._search_scope()
            if scope and os.path.isdir(scope):
                self._ensure_files_index_async(scope)
        except Exception:
            pass

    _FILES_INDEX_TTL = 45      # seconds — stale-while-revalidate window

    def _build_files_index(self, scope):
        """scope ke andar sabhi folder+file ka index. Har entry:
        (kind, full, name_lower, rel_lower, norm, compact, ext, size, mtime).
        norm/compact EK hi baar banate hain — har keystroke par sirf scoring.

        (v300) SPEED: index banate waqt ab har file par os.stat NAHI karte —
        yahi 883-folder jaise bade folder me 4-5 second laga deta tha (Windows +
        antivirus par har file ka metadata padhna mehnga hai). Naam-search ko
        size/mtime chahiye hi nahi. size/mtime = None rakhte hain; sirf tab (aur
        sirf ussi file par) stat karte hain jab user 'today'/'>1mb' jaisa filter
        likhe (_search_index_entries me lazy stat). Isse index ab bijli-tez banta
        hai aur pehla akshar likhte hi natije aa jaate hain."""
        SE = FileSearchEngine
        idx = []
        exts = self._FILE_EXTS
        try:
            for dp, dns, fn in os.walk(scope):
                for d in dns:
                    full = os.path.join(dp, d)
                    n = SE.norm(d)
                    idx.append(("dir", full, d.lower(),
                                os.path.relpath(full, scope).lower(),
                                n, SE.compact(n), "", None, None))
                for f in fn:
                    if f.lower().endswith(exts):
                        full = os.path.join(dp, f)
                        n = SE.norm(f)
                        idx.append(("file", full, f.lower(),
                                    os.path.relpath(full, scope).lower(),
                                    n, SE.compact(n),
                                    os.path.splitext(f)[1].lower(), None, None))
                if len(idx) >= 120000:
                    break
        except Exception:
            pass
        return idx

    def _ensure_files_index_async(self, scope, force=False):
        """scope ka index memory me tayyar rakho (background me). Jab tak na bane
        tab tak None rehta hai. force=True => TTL ke baad chupchap taaza banao
        (purana index tab tak kaam karta rehta hai — UI kabhi na ruke)."""
        if (not force) and getattr(self, "_files_index", None) is not None and \
                getattr(self, "_files_index_scope", None) == scope:
            return
        if getattr(self, "_files_index_building", False):
            return
        self._files_index_building = True

        def _done(idx):
            self._files_index_building = False
            if isinstance(idx, Exception):
                return
            self._files_index = idx
            self._files_index_scope = scope
            self._files_index_time = time.time()
            try:
                _search_engine.clear_cache()
            except Exception:
                pass
            # (v290) index ban gaya — agar search-box me abhi bhi kuch likha hai
            # to results turant sidebar-list me dikha do (progressive; blank nahi).
            try:
                if len(self.files_search.text().strip()) >= 1:
                    self._run_files_search()
            except Exception:
                pass
        self._run_bg_quiet(lambda: self._build_files_index(scope), _done)

    def _search_index_entries(self, terms, filters, idx, limit=1000):
        """Score every index entry with the SearchEngine. Two passes: an instant
        substring pass over ALL entries; a fuzzy (typo) pass only when the first
        pass found little — so 50,000 files stay live-fast, but 'Garma' still
        finds 'Garima'. Returns [('dir'|'file', path), ...] ranked best-first."""
        SE = FileSearchEngine
        dir_hits, file_hits = [], []
        misses = []
        fcache = {}                       # folder-path -> (norm, compact), once per dir

        def _folder_strs(rel):
            d = os.path.dirname(rel)
            if d not in fcache:
                fn = SE.norm(d)
                fcache[d] = (fn, SE.compact(fn))
            return fcache[d]

        for e in idx:
            kind, full, name = e[0], e[1], e[2]
            norm = e[4] if len(e) > 4 else SE.norm(name)
            comp = e[5] if len(e) > 5 else SE.compact(norm)
            ext = e[6] if len(e) > 6 else os.path.splitext(name)[1]
            size = e[7] if len(e) > 7 else None
            mtime = e[8] if len(e) > 8 else None
            if kind == "dir":
                if filters.get("ext") or filters.get("size") or filters.get("days"):
                    continue           # metadata filters are about FILES
                if not terms:
                    continue
                ok, key = _folder_search_score(terms, norm)
                if ok:
                    dir_hits.append((key, name, full))
                elif all(t in comp for t in terms):     # across-separator fallback
                    dir_hits.append(((1, 1, 4, 4 * len(terms), len(norm), norm),
                                     name, full))
                continue
            # (v300) size/mtime index me nahi rakhe (speed) — sirf tab (aur ussi
            # file par) stat karo jab query me date/size filter ho.
            if size is None and (filters.get("size") or filters.get("days")):
                try:
                    st = os.stat(full)
                    size, mtime = st.st_size, st.st_mtime
                except Exception:
                    pass
            if not SE.passes_filters(filters, ext, size, mtime):
                continue
            if not terms:                # pure filter query ('pdf', 'today', '>1mb')
                file_hits.append(((3, 9, 9, len(norm), norm), name, full))
                continue
            fn_norm, fn_comp = _folder_strs(e[3]) if len(e) > 3 else ("", "")
            # (v226) file ko sirf uske APNE naam se match karo — kewal parent-folder
            # ke naam se nahi. Isse folder-naam search par woh FOLDER dikhta hai
            # (uske andar ki saari files nahi). 'folder + file' jaise 2-term search
            # phir bhi chalte hain kyunki file-naam wala term match karta hai.
            m = SE.match_file(terms, norm, comp, None, fn_norm, fn_comp,
                              fuzzy=False, require_name_hit=True)
            if m is not None:
                file_hits.append((SE.rank_key(m[0], m[1], norm), name, full))
            elif len(misses) < 6000:        # (v228) misses ko bounded rakho — bade
                misses.append((norm, comp, fn_norm, fn_comp, name, full))
            if len(dir_hits) + len(file_hits) >= limit:
                break
        # fuzzy (typo) pass — MEHNGA (difflib). Sirf tab chalao jab seedhe match
        # bahut kam ho (asli typo), aur tab bhi ek budget tak — warna bade folder
        # (7000+ files) me har keystroke par hazaaron difflib calls se search
        # slow ho jaata tha. Folder match mil gaya to fuzzy ki zaroorat nahi.
        if (terms and not dir_hits and len(file_hits) < 6 and misses
                and len("".join(terms)) >= 3):
            _budget = 2500              # zyada se zyada itni files par typo-jaanch
            for norm, comp, fn_norm, fn_comp, name, full in misses:
                _budget -= 1
                if _budget < 0:
                    break
                m = SE.match_file(terms, norm, comp, norm.split(), fn_norm, fn_comp,
                                  fuzzy=True, require_name_hit=True)
                if m is not None:
                    file_hits.append((SE.rank_key(m[0], m[1], norm), name, full))
                if len(file_hits) >= limit:
                    break
        dir_hits.sort(key=lambda h: (h[0], h[1]))
        file_hits.sort(key=lambda h: (h[0], h[1]))
        return ([("dir", h[2]) for h in dir_hits] +
                [("file", h[2]) for h in file_hits])

    def _run_files_search(self):
        """Live search — POORE panel-folder (sab subfolders) me. In-memory index
        + SearchEngine: har partial (naam/number/beech-ka-tukda), _-/space
        farak nahi, Hindi/English, typo-tolerant, 'pdf'/'today'/'>1mb' filter.
        Index purana ho to purane se TURANT jawab + background me taaza."""
        q = self.files_search.text().strip().lower()
        self._search_snippets = {}          # (v272) purane snippet saaf; sirf
        #                                     inside-text search inko bharta hai
        # (v290) INSTANT: pehle akshar se hi search. Khaali box -> normal list.
        if len(q) < 1:
            self.files_results.hide()
            self.files_tree.show()
            self.files_results._hl_terms = None
            return
        SE = FileSearchEngine
        t0 = time.time()
        # halki telemetry: 'search' feature — zyada se zyada 10 min me 1 baar
        # (har keystroke par nahi; sirf ginti jaati hai, query kabhi nahi)
        try:
            if t0 - getattr(self, "_an_search_t", 0) > 600:
                self._an_search_t = t0
                self._an_event("search")
        except Exception:
            pass
        # (v275) operators: "exact phrase" + -exclude nikaalo; baaki engine ko
        clean_q, ex_ops, ph_ops = self._parse_ops(q)
        self._search_ops = (ex_ops, ph_ops)
        terms, filters = SE.parse_query(clean_q)
        self._remember_search(q)                         # (v274) pichhli searches yaad
        scope = self._search_scope()                     # (v274) toggle: folder / poora My Files
        search_text = self.btn_search_text.isChecked()   # PDF ke andar bhi?
        self.files_results._hl_terms = terms              # results me match highlight

        # ---- TEZ RAASTA: naam/path search — memory index se turant ----
        if not search_text:
            idx = getattr(self, "_files_index", None)
            if idx is None or getattr(self, "_files_index_scope", None) != scope:
                # (v290) index abhi nahi bana — CHUP-CHAAP background me banao.
                # Koi "Indexing…" nahi, sidebar blank nahi (jo dikh raha hai wahi
                # dikhta rahe). Index aate hi results khud aa jate hain (_done).
                self._ensure_files_index_async(scope)
                return
            # AUTO-REFRESH: index TTL paar kar gaya? purane se abhi jawab do,
            # background me naya banao (naya aate hi results khud refresh).
            if time.time() - getattr(self, "_files_index_time", 0) > self._FILES_INDEX_TTL:
                self._ensure_files_index_async(scope, force=True)
            ckey = "%s|%s" % (scope, q)
            res = _search_engine.cached(ckey)
            if res is None:
                # (v291) live-search me sirf top ~500 hi chahiye — sidebar itne se
                # bhar jaata hai; isse hazaaron item render karke lag nahi hota.
                res = self._search_index_entries(terms, filters, idx, limit=500)
                res = self._apply_ops(res, ex_ops, ph_ops, False)   # (v275) operators
                _search_engine.remember(ckey, res)
            SE.log(q, time.time() - t0, len(res))
            self._render_files_results(res, q, preserve_order=True)
            return

        # ---- BHAARI RAASTA: PDF ke andar ka text bhi — background me ----
        exts = self._FILE_EXTS

        def job():
            dir_hits, file_hits = [], []
            snips = {}                       # (v272) path -> jis line me mila uska tukda
            _img_budget = [120]              # (v274) itni images tak hi OCR (hang na ho)
            _img_exts = (".png", ".jpg", ".jpeg", ".bmp", ".tif", ".tiff")
            for dp, dns, fn in os.walk(scope):
                for d in dns:
                    if not terms:
                        continue
                    nd = SE.norm(d)
                    ok, key = _folder_search_score(terms, nd)
                    if ok:
                        dir_hits.append((key, d.lower(), os.path.join(dp, d)))
                for f in fn:
                    if not f.lower().endswith(exts):
                        continue
                    full = os.path.join(dp, f)
                    try:
                        st = os.stat(full)
                        size, mtime = st.st_size, st.st_mtime
                    except Exception:
                        size, mtime = None, None
                    if not SE.passes_filters(filters, os.path.splitext(f)[1], size, mtime):
                        continue
                    n = SE.norm(f)
                    txt = ""
                    fl = full.lower()
                    if fl.endswith(".pdf"):
                        txt = (self._pdf_text_cached(full) or "")
                    elif fl.endswith(_img_exts) and _img_budget[0] > 0:
                        # (v274) scan ki hui IMAGE ke andar bhi OCR se dhoondo
                        _img_budget[0] -= 1
                        txt = (self._img_text_cached(full) or "")
                    m = SE.match_file(terms, n, SE.compact(n), n.split(),
                                      SE.norm(dp), SE.compact(SE.norm(dp)),
                                      txt.lower()) if terms else (3, [9])
                    if m is not None:
                        file_hits.append((SE.rank_key(m[0], m[1], n), f.lower(), full))
                        if txt:
                            sn = self._make_snippet(txt, terms)
                            if sn:
                                snips[full] = sn
                if len(dir_hits) + len(file_hits) >= 1000:
                    break
            dir_hits.sort(key=lambda h: (h[0], h[1]))
            file_hits.sort(key=lambda h: (h[0], h[1]))
            return (([("dir", h[2]) for h in dir_hits] +
                     [("file", h[2]) for h in file_hits]), snips)

        def done(res):
            if isinstance(res, Exception):
                SE.log(q, time.time() - t0, 0, error=str(res))
                return
            if self.files_search.text().strip().lower() != q:
                return
            results, snips = res
            results = self._apply_ops(results, ex_ops, ph_ops, True)   # (v275) operators
            self._search_snippets = snips     # render me file ke neeche dikhega
            SE.log(q, time.time() - t0, len(results))
            self._render_files_results(results, q, preserve_order=True)
        self._run_bg(job, done, self.L("Andar ka text dhoondh rahe…",
                                       "Searching inside text…"))

    def _make_snippet(self, txt, terms, width=42):
        """PDF-andar-search: jis term par match hua uske aas-paas ka chhota tukda
        (context) — file ke neeche dikhane ke liye. txt pehle se lowercase hai."""
        if not txt or not terms:
            return ""
        pos = -1
        for t in terms:
            i = txt.find(t)
            if i >= 0 and (pos < 0 or i < pos):
                pos = i
        if pos < 0:
            return ""
        start = max(0, pos - width)
        end = min(len(txt), pos + width)
        seg = " ".join(txt[start:end].split())
        if start > 0:
            seg = "… " + seg
        if end < len(txt):
            seg = seg + " …"
        return seg[:130]

    def _update_files_suggest(self):
        """(v270) LIVE dropdown: jaise-jaise type karo, top matches search box ke
        neeche turant (pehle akshar se) dikhao. In-memory index se — bahut tez."""
        sg = getattr(self, "_sugg", None)
        if sg is None:
            return
        self._sugg_nav = False                # nayi type => koi manual selection nahi
        try:
            if not self.files_search.isVisible():
                sg.hide(); return
        except Exception:
            return
        q = self.files_search.text().strip().lower()
        if len(q) < 1:                        # pehle akshar se hi
            sg.hide(); return
        SE = FileSearchEngine
        try:
            clean_q, _ex, _ph = self._parse_ops(q)       # (v275) operators hatao
            terms, filters = SE.parse_query(clean_q or q)
        except Exception:
            sg.hide(); return
        scope = self._search_scope()                     # (v274) folder / poora My Files
        idx = getattr(self, "_files_index", None)
        if idx is None or getattr(self, "_files_index_scope", None) != scope:
            self._ensure_files_index_async(scope)   # ban jaate hi dobara aa jayega
            return
        try:
            res = self._search_index_entries(terms, filters, idx, limit=80)
        except Exception:
            sg.hide(); return
        _icon = {".pdf": "📕", ".docx": "📘", ".doc": "📘", ".xlsx": "📗",
                 ".xls": "📗", ".txt": "📄", ".png": "🖼", ".jpg": "🖼",
                 ".jpeg": "🖼", ".tif": "🖼", ".tiff": "🖼"}
        sg.clear()
        shown = 0
        for kind, p in res:
            if shown >= 12:
                break
            base = os.path.basename(p) or p
            ic = "📁" if kind == "dir" else _icon.get(os.path.splitext(p)[1].lower(), "🖼")
            it = QtWidgets.QListWidgetItem("%s  %s" % (ic, base))
            it.setData(QtCore.Qt.UserRole, p)
            it.setToolTip(p)
            sg.addItem(it)
            shown += 1
        if shown == 0:
            sg.hide(); return
        # position: search box ke theek neeche, usi width me (global coords)
        try:
            gp = self.files_search.mapToGlobal(
                QtCore.QPoint(0, self.files_search.height() + 2))
            row_h = 30
            h = min(shown, 8) * row_h + 8
            sg.setGeometry(gp.x(), gp.y(), max(180, self.files_search.width()), h)
        except Exception:
            pass
        sg.setCurrentRow(-1)                  # default koi highlight nahi
        sg.raise_()
        sg.show()

    def _files_sugg_pick(self, it):
        """Dropdown me kisi item par click/Enter — folder ho to usme chale jao,
        file ho to kholo."""
        p = it.data(QtCore.Qt.UserRole) if it else None
        try:
            self._sugg.hide()
        except Exception:
            pass
        if not p:
            return
        # (v274) recent-search item? -> us query se dobara search
        if isinstance(p, str) and p.startswith(self._RS_SENTINEL):
            self.files_search.setText(p[len(self._RS_SENTINEL):])
            self._files_search_enter()
            return
        if os.path.isdir(p):
            self._jump_to_folder(p)
        else:
            self._open_path(p)

    def _files_search_enter(self):
        """Enter: agar user ne ↓/↑ se koi suggestion chuna hai to wahi kholo;
        warna poori search-list panel me dikhao."""
        sg = getattr(self, "_sugg", None)
        if (sg is not None and sg.isVisible() and getattr(self, "_sugg_nav", False)
                and sg.currentItem() is not None):
            self._files_sugg_pick(sg.currentItem())
            return
        if sg is not None:
            sg.hide()
        self._run_files_search()

    # ---- (v274) scope toggle: sirf folder vs poora My Files ----
    def _search_scope(self):
        if self._opts.get("search_all_scope"):
            return self._files_root()
        scope = self._panel_current_dir()
        if not (scope and os.path.isdir(scope)):
            scope = self._files_root()
        return scope

    def _refresh_scope_btn(self):
        try:
            on = bool(self._opts.get("search_all_scope"))
            self.btn_scope.setText("🌐" if on else "📂")
            self.btn_scope.setToolTip(self.L(
                "Poore My Files me dhoondo" if on else "Sirf is folder me dhoondo (click: poore My Files me)",
                "Searching all of My Files" if on else "Searching this folder only (click: all of My Files)"))
        except Exception:
            pass

    def _on_scope_toggle(self, on):
        self._opts["search_all_scope"] = bool(on)
        self._save_opts()
        self._refresh_scope_btn()
        # index scope badla — dobara search/suggest
        self._sugg_timer.start()
        if len(self.files_search.text().strip()) >= 2:
            self._files_search_timer.start()

    # ---- (v274) recent searches — pichhli searches yaad rakho ----
    _RS_SENTINEL = "\x00rs\x00"

    def _remember_search(self, q):
        q = (q or "").strip()
        if len(q) < 2:
            return
        rs = self._opts.setdefault("recent_searches", [])
        low = [x.lower() for x in rs]
        if q.lower() in low:
            rs.pop(low.index(q.lower()))
        rs.insert(0, q)
        del rs[12:]
        self._save_opts()

    def _show_recent_searches(self):
        """Search-box focus (khaali) par — pichhli searches dropdown me."""
        sg = getattr(self, "_sugg", None)
        if sg is None:
            return
        if self.files_search.text().strip():
            return
        saved = self._opts.get("saved_searches", []) or []
        rs = self._opts.get("recent_searches", []) or []
        if not saved and not rs:
            return
        sg.clear()
        for q in saved[:8]:                          # ⭐ saved sabse upar
            it = QtWidgets.QListWidgetItem("⭐  " + q)
            it.setData(QtCore.Qt.UserRole, self._RS_SENTINEL + q)
            sg.addItem(it)
        for q in rs[:10]:
            if q in saved:
                continue
            it = QtWidgets.QListWidgetItem("🕘  " + q)
            it.setData(QtCore.Qt.UserRole, self._RS_SENTINEL + q)
            sg.addItem(it)
        if sg.count() == 0:
            return
        try:
            gp = self.files_search.mapToGlobal(
                QtCore.QPoint(0, self.files_search.height() + 2))
            h = min(sg.count(), 8) * 30 + 8
            sg.setGeometry(gp.x(), gp.y(), max(180, self.files_search.width()), h)
        except Exception:
            pass
        sg.setCurrentRow(-1)
        sg.raise_(); sg.show()

    def _render_files_results(self, res, q=None, preserve_order=False):
        """Search/filter ke natije (list) ko panel me dikhao. q diya ho to sirf
        tabhi render karo jab search-box me abhi bhi wahi likha ho.
        preserve_order=True (smart-search) => ranking ka kram bana rahe (folder
        jo sabse relevant hai wo sabse upar); filters/recent purane jaise
        alphabetical hi."""
        if q is not None and self.files_search.text().strip().lower() != q:
            return                          # tab tak nayi search shuru ho gayi
        if not preserve_order:
            self.files_results._hl_terms = None   # non-search view => no highlight
        self._last_files_res = res          # grid toggle par dobara render ke liye
        self._last_files_preserve = preserve_order
        # (v228) SEARCH ke natije hamesha LIST me — user request; list zyada
        # scannable hai (folder + uske documents saaf dikhe). Grid toggle sirf
        # normal folder-browse par lagta hai.
        grid = bool(self._opts.get("files_grid")) and not preserve_order
        self.files_results.clear()
        # FOLDER ke hisaab se group karo: upar folder ka naam (header),
        # neeche usi folder ke documents. preserve_order me folder RANK ke kram me
        # aate hain (res me jaise mile), warna group banake alphabetical.
        groups, order = {}, []
        if preserve_order:
            for kind, p in res:
                fol = p if kind == "dir" else os.path.dirname(p)
                if fol not in groups:
                    groups[fol] = []; order.append(fol)
                if kind == "file":
                    groups[fol].append(p)
        else:
            for kind, p in res:
                if kind == "file":
                    par = os.path.dirname(p)
                    if par not in groups:
                        groups[par] = []; order.append(par)
                    groups[par].append(p)
            for kind, p in res:                     # naam-se-mile khali folder bhi
                if kind == "dir" and p not in groups:
                    groups[p] = []; order.append(p)
            order.sort(key=lambda f: os.path.basename(f).lower())
        n_dir = len(order)
        n_file = sum(len(v) for v in groups.values())
        # (v300) SPEED: bahut saare result par har file ka size (os.path.getsize)
        # nikaalna har keystroke ko slow kar deta hai. Isliye size sirf tab dikhao
        # jab result kam hon (narrow ho gaye); bade result-set me size chhodo.
        _show_sizes = n_file <= 80
        if grid:
            self.files_results.setViewMode(QtWidgets.QListView.IconMode)
            self.files_results.setIconSize(QtCore.QSize(96, 124))
            self.files_results.setGridSize(QtCore.QSize(108, 150))
            self.files_results.setResizeMode(QtWidgets.QListView.Adjust)
            self.files_results.setMovement(QtWidgets.QListView.Static)
        else:
            self.files_results.setViewMode(QtWidgets.QListView.ListMode)
            self.files_results.setGridSize(QtCore.QSize())
        head = QtWidgets.QListWidgetItem(
            self.L("🔎 %d folder · %d file" % (n_dir, n_file),
                   "🔎 %d folders · %d files" % (n_dir, n_file))
            + ("+" if len(res) >= 1000 else ""))
        head.setFlags(QtCore.Qt.NoItemFlags)
        _hf = head.font(); _hf.setBold(True); head.setFont(_hf)
        head.setForeground(QtGui.QColor("#4F46E5"))
        if not grid:
            self.files_results.addItem(head)
        _icon = {".pdf": "📕", ".docx": "📘", ".xlsx": "📗"}
        pinned = set(self._opts.get("pinned_files") or [])
        grid_files = []
        for folder in order:
            if not grid:
                fh = QtWidgets.QListWidgetItem("📁  " + (os.path.basename(folder) or folder))
                _ff = fh.font(); _ff.setBold(True); fh.setFont(_ff)
                fh.setForeground(QtGui.QColor("#4F46E5"))
                fh.setBackground(QtGui.QColor("#eef4f3"))
                fh.setToolTip(folder + self.L("   (folder — 2x click = kholo)",
                                              "   (folder — double-click to open)"))
                fh.setData(QtCore.Qt.UserRole, folder)
                self.files_results.addItem(fh)
            elif not groups[folder]:
                # (v227) GRID mode me folder-header nahi banta tha; isliye jab
                # folder KHUD match hota (uske andar koi file result me nahi) to
                # kuch nahi dikhta tha (khaali). Ab folder ko ek TILE me dikhao —
                # 2x click par khul jaata hai.
                fh = QtWidgets.QListWidgetItem("📁\n" + (os.path.basename(folder) or folder))
                fh.setTextAlignment(QtCore.Qt.AlignHCenter | QtCore.Qt.AlignTop)
                fh.setSizeHint(QtCore.QSize(108, 150))
                fh.setToolTip(folder + self.L("   (folder — 2x click = kholo)",
                                              "   (folder — double-click to open)"))
                fh.setData(QtCore.Qt.UserRole, folder)
                self.files_results.addItem(fh)
            for p in sorted(groups[folder], key=lambda x: os.path.basename(x).lower()):
                ext = os.path.splitext(p)[1].lower()
                pin = "📌 " if p in pinned else ""
                if grid:
                    it = QtWidgets.QListWidgetItem(pin + os.path.basename(p))
                    it.setTextAlignment(QtCore.Qt.AlignHCenter | QtCore.Qt.AlignTop)
                    it.setSizeHint(QtCore.QSize(108, 150))
                    grid_files.append((self.files_results.count(), p))
                else:
                    # (v274) file ke aage size + (v307) DATE bhi dikhe — (v300)
                    # sirf jab result kam hon (warna har keystroke slow). Ek hi
                    # os.stat se size aur date dono (do alag call se tez).
                    _sz = ""
                    if _show_sizes:
                        try:
                            _st = os.stat(p)
                            _b = _st.st_size
                            _szt = ("%d KB" % round(_b / 1024.0)) if _b < 1048576 \
                                else ("%.1f MB" % (_b / 1048576.0))
                            _dt = time.strftime("%d-%m-%Y", time.localtime(_st.st_mtime))
                            _sz = "  ·  %s  ·  📅 %s" % (_szt, _dt)
                        except Exception:
                            _sz = ""
                    it = QtWidgets.QListWidgetItem("      " + pin + _icon.get(ext, "🖼")
                                                   + "  " + os.path.basename(p) + _sz)
                _note = self._file_note(p)       # (v275) file ka note (agar hai)
                it.setToolTip(p + (("\n📝 " + _note) if _note else "")
                              + self.L("   (click = preview · 2x = kholo · drag = import)",
                                       "   (click = preview · double-click = open · drag = import)"))
                it.setData(QtCore.Qt.UserRole, p)
                self.files_results.addItem(it)
                # (v275) file ka note — neeche halki line me
                if _note and not grid:
                    nz = QtWidgets.QListWidgetItem("           📝 " + _note.replace("\n", " "))
                    nz.setData(QtCore.Qt.UserRole, p)
                    _nf = nz.font(); _nf.setPointSizeF(max(7.5, _nf.pointSizeF() - 0.5))
                    nz.setFont(_nf); nz.setForeground(QtGui.QColor("#B45309"))
                    nz.setToolTip(p)
                    self.files_results.addItem(nz)
                # (v272) PDF-andar-search ka snippet — file ke neeche grey line me
                # (jis line me mareez/claim ka naam mila). Term khud highlight hota.
                snip = (getattr(self, "_search_snippets", None) or {}).get(p)
                if snip and not grid:
                    s = QtWidgets.QListWidgetItem("           💬 " + snip)
                    s.setData(QtCore.Qt.UserRole, p)     # click par bhi wahi file
                    _sf = s.font(); _sf.setItalic(True)
                    _sf.setPointSizeF(max(7.5, _sf.pointSizeF() - 1.0)); s.setFont(_sf)
                    s.setForeground(QtGui.QColor("#6B7280"))
                    s.setToolTip(p)
                    self.files_results.addItem(s)
        if not order:
            # (v290) saaf empty-state (blank sidebar nahi)
            it = QtWidgets.QListWidgetItem(
                self.L("\n🔍\n\nKoi file/folder nahi mila\nkoi doosra shabd aajmao\n",
                       "\n🔍\n\nNo matching files or folders\nTry a different search term\n"))
            it.setFlags(QtCore.Qt.NoItemFlags)
            it.setTextAlignment(QtCore.Qt.AlignHCenter)
            it.setForeground(QtGui.QColor("#94A3B8"))
            self.files_results.addItem(it)
        self.files_tree.hide()
        self.files_results.show()
        if grid and grid_files:
            self._build_grid_thumbs(grid_files[:60])

    def _build_grid_thumbs(self, items):
        """Grid view ke liye har file ki thumbnail (PDF ka pehla page ya image)
        background me banao, phir icon laga do — UI kabhi atke nahi."""
        rows = [(r, p) for r, p in items]

        def job():
            out = []
            for r, p in rows:
                png = None
                try:
                    ext = os.path.splitext(p)[1].lower()
                    if ext == ".pdf" and HAS_FITZ:
                        doc = fitz.open(p)
                        page = doc.load_page(0)
                        pix = page.get_pixmap(matrix=fitz.Matrix(0.5, 0.5), alpha=False)
                        fd, png = tempfile.mkstemp(suffix=".png", dir=self._tmpdir)
                        os.close(fd); pix.save(png); doc.close()
                    elif ext in (".jpg", ".jpeg", ".png", ".tif", ".tiff"):
                        png = p
                except Exception:
                    png = None
                out.append((r, png))
            return out

        def done(res):
            if isinstance(res, Exception):
                return
            for r, png in res:
                if not png:
                    continue
                try:
                    it = self.files_results.item(r)
                    if it is not None and it.data(QtCore.Qt.UserRole):
                        it.setIcon(QtGui.QIcon(self._make_thumb(png)))
                except Exception:
                    pass
        self._run_bg_quiet(job, done)

    def _toggle_files_grid(self, on):
        self._opts["files_grid"] = bool(on)
        self._save_opts()
        # jo abhi dikh raha hai use usi tarah dobara render karo
        if self.files_results.isVisible() and getattr(self, "_last_files_res", None) is not None:
            self._render_files_results(self._last_files_res,
                                       preserve_order=getattr(self, "_last_files_preserve", False))
        else:
            self._apply_files_filter()

    def _files_index_ready(self, scope):
        """scope ka index chahiye — na ho to background me banwao, ready hone par
        given callback ke bajaye seedha filter/recent dobara chala do."""
        idx = getattr(self, "_files_index", None)
        if idx is not None and getattr(self, "_files_index_scope", None) == scope:
            return idx
        self._ensure_files_index_async(scope)
        return None

    def _apply_files_filter(self):
        """Filter dropdown: sab / PDF / photo / aaj / hafta / pinned."""
        mode = self.files_filter.currentData() if hasattr(self, "files_filter") else "all"
        if mode in (None, "all"):
            # normal folder-browser wapas
            try:
                self.files_search.clear()
            except Exception:
                pass
            self.files_results.hide(); self.files_tree.show()
            return
        scope = self._panel_current_dir()
        if not (scope and os.path.isdir(scope)):
            scope = self._files_root()
        if mode == "pinned":
            res = [("file", p) for p in (self._opts.get("pinned_files") or [])
                   if os.path.isfile(p)]
            self._render_files_results(res)
            return
        idx = self._files_index_ready(scope)
        if idx is None:
            self.files_results.clear()
            _w = QtWidgets.QListWidgetItem(self.L("⏳ Taiyaari…", "⏳ Indexing…"))
            _w.setFlags(QtCore.Qt.NoItemFlags)
            self.files_results.addItem(_w)
            self.files_tree.hide(); self.files_results.show()
            QtCore.QTimer.singleShot(400, self._apply_files_filter)
            return
        files = [e[1] for e in idx if e[0] == "file"]
        if mode == "pdf":
            res = [("file", p) for p in files if p.lower().endswith(".pdf")]
        elif mode == "img":
            res = [("file", p) for p in files
                   if p.lower().endswith((".jpg", ".jpeg", ".png", ".tif", ".tiff"))]
        elif mode in ("today", "week"):
            import time as _t
            now = _t.time()
            span = 86400 if mode == "today" else 7 * 86400
            hit = []
            for p in files:
                try:
                    if now - os.path.getmtime(p) <= span:
                        hit.append(p)
                except Exception:
                    pass
            res = [("file", p) for p in hit]
        else:
            res = [("file", p) for p in files]
        self._render_files_results(res)

    def _show_recent_files(self):
        """Haal me bani/badli files — naye sabse upar (poore scope me)."""
        scope = self._panel_current_dir()
        if not (scope and os.path.isdir(scope)):
            scope = self._files_root()
        idx = self._files_index_ready(scope)
        if idx is None:
            self.status.showMessage(self.L("Taiyaari… phir se dabao.",
                                           "Indexing… tap again."), 2000)
            return
        files = [e[1] for e in idx if e[0] == "file"]

        def job():
            dated = []
            for p in files:
                try:
                    dated.append((os.path.getmtime(p), p))
                except Exception:
                    pass
            dated.sort(reverse=True)
            return [("file", p) for _m, p in dated[:60]]

        def done(res):
            if isinstance(res, Exception):
                return
            try:
                self.files_filter.blockSignals(True)
                self.files_filter.setCurrentIndex(0)
                self.files_filter.blockSignals(False)
            except Exception:
                pass
            self._render_files_results(res)
        self._run_bg(job, done, self.L("Haal ki files…", "Recent files…"))

    def _update_folder_info(self):
        """Is folder me kitni files + kul size — chhoti patti me dikhao."""
        scope = self._panel_current_dir()
        if not (scope and os.path.isdir(scope)):
            self.lbl_folder_info.setText("")
            return

        def job():
            n = 0; total = 0
            try:
                for dp, dns, fn in os.walk(scope):
                    for f in fn:
                        if f.lower().endswith(self._FILE_EXTS):
                            n += 1
                            try:
                                total += os.path.getsize(os.path.join(dp, f))
                            except Exception:
                                pass
                    if n >= 40000:
                        break
            except Exception:
                pass
            return (n, total)

        def done(res):
            if isinstance(res, Exception) or not isinstance(res, tuple):
                return
            n, total = res
            gb = total / (1024.0 ** 3)
            sz = ("%.1f GB" % gb) if gb >= 1 else ("%.0f MB" % (total / 1048576.0))
            self.lbl_folder_info.setText(self.L("📦 %d files · %s" % (n, sz),
                                                "📦 %d files · %s" % (n, sz)))
        self._run_bg_quiet(job, done)

    def _merge_folder_pdfs(self, folder):
        if not HAS_OCR_LIBS:
            self._warn("pypdf is not installed.")
            return
        pdfs = sorted(os.path.join(folder, f) for f in os.listdir(folder)
                      if f.lower().endswith(".pdf"))
        if len(pdfs) < 2:
            self._warn("This folder has fewer than 2 PDFs.")
            return
        out, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, 'Save the merged PDF',
            os.path.join(folder, (os.path.basename(folder) or "sab") + "_sab.pdf"),
            "PDF (*.pdf)")
        if not out:
            return
        try:
            writer = PdfWriter()
            used = 0
            for p in pdfs:
                if os.path.abspath(p) == os.path.abspath(out):
                    continue
                try:
                    for pg in PdfReader(p).pages:
                        writer.add_page(pg)
                    used += 1
                except Exception:
                    pass
            with open(out, "wb") as fh:
                writer.write(fh)
        except Exception:
            self._warn("Merge failed:\n%s" % traceback.format_exc())
            return
        QtWidgets.QMessageBox.information(
            self, "Done", "Merged %d PDFs into one:\n%s" % (used, out))

    def _rename_library_file(self, path):
        stem, ext = os.path.splitext(os.path.basename(path))
        name, ok = self._ask_name("Rename", "New name:", stem)
        if not ok or not name.strip():
            return
        # (v227) sanitize() space hata deta tha ('Sohan Singh' -> 'SohanSingh').
        # underscore_name khud safe filename banata hai AUR space rakhta hai.
        new = os.path.join(os.path.dirname(path),
                           (underscore_name(name.strip()) or "scan") + ext)
        # (v231) us naam ki file pehle se ho to ' 1', ' 2'... apne aap
        # (khud is file ko chhodkar — same naam par bewajah number na lage)
        new = self._unique_fs_path(new, is_dir=False, exclude=path)
        try:
            os.rename(path, new)
        except Exception as exc:
            self._warn("Rename failed: %s" % exc)

    def _delete_library_file(self, path):
        if QtWidgets.QMessageBox.question(
                self, "Delete",
                "Move '%s' to the Recycle Bin?\n(You can restore it later.)"
                % os.path.basename(path),
                QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
                QtWidgets.QMessageBox.No) != QtWidgets.QMessageBox.Yes:
            return
        if self._trash_file(path):
            self.status.showMessage(self.L("🗑 Recycle Bin me daal diya — wapas la sakte hain",
                                           "🗑 Moved to Recycle Bin — you can restore it"), 5000)
        else:
            self._warn(self.L("Delete fail ho gaya", "Delete failed"))

    # ---------- Recycle Bin (kachra-peti) ----------
    def _trash_index_path(self):
        return os.path.join(TRASH_DIR, "index.json")

    def _load_trash_index(self):
        import json
        try:
            with open(self._trash_index_path(), "r", encoding="utf-8") as fh:
                return json.load(fh) or []
        except Exception:
            return []

    def _save_trash_index(self, items):
        import json
        try:
            os.makedirs(TRASH_DIR, exist_ok=True)
            with open(self._trash_index_path(), "w", encoding="utf-8") as fh:
                json.dump(items, fh, ensure_ascii=False)
        except Exception:
            pass

    def _rename_shortcut(self):
        """(v201) F2 — jahan FOCUS wahan rename: My Files panel me ho to
        file/folder ka naam, warna thumbnail page ka naam."""
        try:
            fw = QtWidgets.QApplication.focusWidget()
            ft = getattr(self, "files_tree", None)
            if ft is not None and fw is not None and (fw is ft or ft.isAncestorOf(fw)):
                self._panel_rename_current()
                return
        except Exception:
            pass
        self.rename_current_page()

    def _panel_rename_current(self):
        """(v196) My Files me F2 — chuni file YA folder ka naam badlo."""
        try:
            idx = self.files_tree.currentIndex()
            if not idx.isValid():
                return
            path = self.files_model.filePath(idx)
        except Exception:
            return
        if os.path.isfile(path):
            try:
                self._rename_library_file(path)
            except Exception:
                pass
            return
        old = os.path.basename(path) or path
        name, ok = QtWidgets.QInputDialog.getText(
            self, self.L("Naam badlo", "Rename"),
            self.L("Folder ka naya naam:", "New folder name:"), text=old)
        name = (name or "").strip()
        if not ok or not name or name == old:
            return
        newp = os.path.join(os.path.dirname(path), folder_safe_name(name))
        # (v231) same naam ka folder pehle se ho to ' 1', ' 2'... apne aap
        # (khud is folder ko chhodkar)
        newp = self._unique_fs_path(newp, is_dir=True, exclude=path)
        try:
            os.rename(path, newp)
            self._invalidate_files_index()
            self._update_panel_nav()
            self.status.showMessage(self.L('✏ "%s" → "%s"', '✏ "%s" → "%s"')
                                    % (old, os.path.basename(newp)), 5000)
        except Exception as exc:
            self._warn(self.L("Naam nahi badla ja saka:\n%s",
                              "Could not rename:\n%s") % exc)

    def _delete_folder(self, path):
        """(v195) Poora folder Recycle Bin me — pehle poochta hai (andar ki
        files ki ginti ke saath); wapas Recycle Bin se laa sakte hain."""
        try:
            n = self._fcnt(path)
        except Exception:
            n = -1
        nm = os.path.basename(path) or path
        msg = (self.L('"%s" folder (andar %d files) Recycle Bin me daalein?\n(wapas la sakte hain)',
                      'Move folder "%s" (%d files inside) to Recycle Bin?\n(restorable)') % (nm, max(0, n))
               if n >= 0 else
               self.L('"%s" folder Recycle Bin me daalein? (wapas la sakte hain)',
                      'Move folder "%s" to Recycle Bin? (restorable)') % nm)
        if QtWidgets.QMessageBox.question(
                self, "Delete", msg,
                QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
                QtWidgets.QMessageBox.No) != QtWidgets.QMessageBox.Yes:
            return
        if self._trash_file(path):
            self.status.showMessage(self.L('🗑 "%s" Recycle Bin me chala gaya',
                                           '🗑 "%s" moved to Recycle Bin') % nm, 6000)
            try:
                self._ev_push("folder:delete")
            except Exception:
                pass
        else:
            self._warn(self.L("Folder delete nahi ho paya (koi file khuli ho sakti hai).",
                              "Could not delete the folder (a file inside may be open)."))

    def _trash_file(self, path):
        """File ko Recycle Bin me le jao (delete karne ke bajay) — wapas laai
        ja sake."""
        import uuid
        try:
            os.makedirs(TRASH_DIR, exist_ok=True)
            base = os.path.basename(path)
            trash_name = uuid.uuid4().hex[:12] + "__" + base
            shutil.move(path, os.path.join(TRASH_DIR, trash_name))
            idx = self._load_trash_index()
            idx.append({"trash": trash_name, "orig": path, "name": base,
                        "when": datetime.datetime.now().strftime("%Y-%m-%d %H:%M")})
            self._save_trash_index(idx)
            self._invalidate_files_index()      # deleted file search me na dikhe
            return True
        except Exception:
            return False

    def show_recycle_bin(self):
        """Delete ki hui files — wapas laao ya hamesha ke liye hatao."""
        idx = self._load_trash_index()
        # sirf wahi jo sach me bin me maujood hain
        idx = [e for e in idx if os.path.exists(os.path.join(TRASH_DIR, e.get("trash", "")))]
        self._save_trash_index(idx)
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle(self.L("🗑 Recycle Bin", "🗑 Recycle Bin"))
        dlg.resize(560, 460)
        v = QtWidgets.QVBoxLayout(dlg)
        v.addWidget(QtWidgets.QLabel(self.L(
            "Delete ki hui files yahan hain. Chuno phir 'Wapas laao' ya 'Hamesha ke liye hatao'.",
            "Deleted files are here. Select, then Restore or Delete forever.")))
        lw = QtWidgets.QListWidget()
        lw.setSelectionMode(QtWidgets.QAbstractItemView.ExtendedSelection)
        for e in reversed(idx):     # naye upar
            it = QtWidgets.QListWidgetItem("📄 %s\n       %s · %s" %
                                           (e.get("name", "?"), e.get("when", ""),
                                            os.path.dirname(e.get("orig", ""))))
            it.setData(QtCore.Qt.UserRole, e)
            lw.addItem(it)
        if not idx:
            it = QtWidgets.QListWidgetItem(self.L("(Recycle Bin khaali hai)", "(Recycle Bin is empty)"))
            it.setFlags(QtCore.Qt.NoItemFlags)
            lw.addItem(it)
        v.addWidget(lw, 1)

        def _restore():
            picked = [i.data(QtCore.Qt.UserRole) for i in lw.selectedItems() if i.data(QtCore.Qt.UserRole)]
            if not picked:
                return
            cur = self._load_trash_index()
            done = 0
            for e in picked:
                src = os.path.join(TRASH_DIR, e["trash"])
                dst = e["orig"]
                try:
                    os.makedirs(os.path.dirname(dst), exist_ok=True)
                    n = 2
                    while os.path.exists(dst):
                        stem, ext = os.path.splitext(e["orig"])
                        dst = "%s_%d%s" % (stem, n, ext); n += 1
                    shutil.move(src, dst)
                    cur = [c for c in cur if c.get("trash") != e["trash"]]
                    done += 1
                except Exception:
                    pass
            self._save_trash_index(cur)
            self.status.showMessage(self.L("♻ %d file wapas aa gayi" % done,
                                           "♻ Restored %d file(s)" % done), 5000)
            self._refresh_files_root()
            dlg.accept()

        def _delete_forever():
            picked = [i.data(QtCore.Qt.UserRole) for i in lw.selectedItems() if i.data(QtCore.Qt.UserRole)]
            if not picked:
                return
            if QtWidgets.QMessageBox.question(
                    dlg, self.L("Pakka?", "Sure?"),
                    self.L("%d file HAMESHA ke liye hat jayengi (wapas nahi aayengi). Theek?",
                           "%d file(s) will be deleted FOREVER (cannot restore). OK?") % len(picked),
                    QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
                    QtWidgets.QMessageBox.No) != QtWidgets.QMessageBox.Yes:
                return
            cur = self._load_trash_index()
            for e in picked:
                try:
                    os.remove(os.path.join(TRASH_DIR, e["trash"]))
                except Exception:
                    pass
                cur = [c for c in cur if c.get("trash") != e["trash"]]
            self._save_trash_index(cur)
            dlg.accept()

        def _empty():
            if not idx:
                return
            if QtWidgets.QMessageBox.question(
                    dlg, self.L("Bin khaali karein?", "Empty bin?"),
                    self.L("Saari files HAMESHA ke liye hat jayengi. Theek?",
                           "All files will be deleted FOREVER. OK?"),
                    QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
                    QtWidgets.QMessageBox.No) != QtWidgets.QMessageBox.Yes:
                return
            for e in self._load_trash_index():
                try:
                    os.remove(os.path.join(TRASH_DIR, e["trash"]))
                except Exception:
                    pass
            self._save_trash_index([])
            dlg.accept()

        bb = QtWidgets.QHBoxLayout()
        b1 = QtWidgets.QPushButton(self.L("♻ Wapas laao", "♻ Restore")); b1.clicked.connect(_restore)
        b2 = QtWidgets.QPushButton(self.L("❌ Hamesha ke liye hatao", "❌ Delete forever")); b2.clicked.connect(_delete_forever)
        b3 = QtWidgets.QPushButton(self.L("🧹 Bin khaali karo", "🧹 Empty bin")); b3.clicked.connect(_empty)
        b4 = QtWidgets.QPushButton("OK"); b4.clicked.connect(dlg.accept)
        bb.addWidget(b1); bb.addWidget(b2); bb.addWidget(b3); bb.addStretch(1); bb.addWidget(b4)
        v.addLayout(bb)
        dlg.exec_()

    # ---------- Multi-select bulk (kai files ek saath) ----------
    def _selected_library_files(self):
        out, seen = [], set()
        try:
            for idx in self.files_tree.selectionModel().selectedIndexes():
                if idx.column() != 0:
                    continue
                p = self.files_model.filePath(idx)
                if p and os.path.isfile(p) and p not in seen:
                    seen.add(p); out.append(p)
        except Exception:
            pass
        return out

    # ---- (v274) naye bulk/single actions ----
    _IMPORTABLE_EXTS = (".pdf", ".png", ".jpg", ".jpeg", ".bmp", ".tif", ".tiff")

    def _open_in_editor(self, files):
        """(v274) Saved file(s) ko wapas kaam-wali page-list me laao — dobara
        crop/sidha/AI-Auto/rotate ke liye (jaise import)."""
        paths = [p for p in files
                 if os.path.isfile(p) and p.lower().endswith(self._IMPORTABLE_EXTS)]
        if not paths:
            self._warn(self.L("Sirf PDF/photo editor me khul sakti hai.",
                              "Only PDF/photo files can be opened in the editor.")); return
        try:
            self.list.setFocus()
        except Exception:
            pass
        self._start_import(paths, "normal")

    def _bulk_tag(self, files):
        """(v274) Kai files par ek saath tag lagao (ek baar likho — sab par lage)."""
        files = [f for f in files if os.path.isfile(f)]
        if not files:
            return
        tags = self._opts.setdefault("tags", {})
        # pehle se kisi ek ka tag suggest ke liye
        cur = ", ".join(tags.get(files[0], []))
        text, ok = QtWidgets.QInputDialog.getText(
            self, self.L("Tags (%d files)" % len(files), "Tags (%d files)" % len(files)),
            self.L("Sab par yahi tag lagao (comma se, jaise: Insurance, ज़रूरी):",
                   "Apply these tags to all (comma-separated, e.g.: Insurance, Urgent):"),
            text=cur)
        if not ok:
            return
        lst = [t.strip() for t in text.split(",") if t.strip()]
        for f in files:
            if lst:
                tags[f] = lst
            else:
                tags.pop(f, None)
        if lst:
            self._ensure_tag_colors(lst)
            try:
                self._an_event("tag")            # (v286) admin analytics
            except Exception:
                pass
        self._save_opts()
        self.status.showMessage(self.L("🏷 %d files par tag: %s" % (len(files), ", ".join(lst) or "(hataya)"),
                                       "🏷 Tagged %d files: %s" % (len(files), ", ".join(lst) or "(removed)")), 5000)

    def _bulk_share(self, files):
        """(v274) Kai files ek saath WhatsApp — ek ZIP bana ke share (clipboard
        par ZIP, WhatsApp khul jaata hai; Ctrl+V se attach)."""
        files = [f for f in files if os.path.isfile(f)]
        if not files:
            return
        if len(files) == 1:
            self.share_whatsapp(files[0]); return
        try:
            import zipfile
            fd, z = tempfile.mkstemp(suffix=".zip", dir=self._tmpdir); os.close(fd)
            with zipfile.ZipFile(z, "w", zipfile.ZIP_DEFLATED) as zf:
                for f in files:
                    zf.write(f, os.path.basename(f))
        except Exception as exc:
            self._warn("ZIP failed: %s" % exc); return
        self.share_whatsapp(z)

    def _img_text_cached(self, path):
        """(v274) Scan ki hui IMAGE ke andar ka text (OCR) — content-search ke
        liye. Result yaad rakhte hain (path+time). Tesseract bundled hai."""
        if not HAS_OCR_LIBS:
            return ""
        try:
            mt = os.path.getmtime(path)
        except Exception:
            return ""
        cache = getattr(self, "_img_text_cache", None)
        if cache is None:
            cache = self._img_text_cache = {}
        key = (path, mt)
        if key in cache:
            return cache[key]
        txt = ""
        try:
            txt = (pytesseract.image_to_string(Image.open(path), lang="hin+eng") or "").lower()
        except Exception:
            txt = ""
        cache[key] = txt
        if len(cache) > 300:
            try:
                cache.pop(next(iter(cache)))
            except Exception:
                pass
        return txt

    def _bulk_delete(self, files):
        if QtWidgets.QMessageBox.question(
                self, "Delete",
                self.L("%d files Recycle Bin me daalein? (wapas la sakte hain)",
                       "Move %d files to Recycle Bin? (restorable)") % len(files),
                QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
                QtWidgets.QMessageBox.No) != QtWidgets.QMessageBox.Yes:
            return
        n = sum(1 for f in files if self._trash_file(f))
        self.status.showMessage(self.L("🗑 %d file Recycle Bin me" % n,
                                       "🗑 %d file(s) to Recycle Bin" % n), 5000)

    def _bulk_merge(self, files):
        if not HAS_OCR_LIBS:
            self._warn("pypdf is not installed (required for merge)."); return
        pdfs = [f for f in files if f.lower().endswith(".pdf")]
        if len(pdfs) < 2:
            self._warn(self.L("Merge ke liye kam se kam 2 PDF chuno.",
                              "Pick at least 2 PDFs to merge.")); return
        folder = os.path.dirname(pdfs[0])
        out, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, self.L("Jodi hui PDF save karein", "Save merged PDF"),
            os.path.join(folder, "merged.pdf"), "PDF (*.pdf)")
        if not out:
            return

        def job():
            writer = PdfWriter()
            used = 0
            for p in pdfs:
                if os.path.abspath(p) == os.path.abspath(out):
                    continue
                try:
                    for pg in PdfReader(p).pages:
                        writer.add_page(pg)
                    used += 1
                except Exception:
                    pass
            with open(out, "wb") as fh:
                writer.write(fh)
            return used

        def on_done(res):
            if isinstance(res, Exception):
                self._warn("Merge failed:\n%s" % res); return
            self.status.showMessage(self.L("🧩 %d PDF jud kar ek ban gayi" % res,
                                           "🧩 Merged %d PDFs into one" % res), 6000)
            self._refresh_files_root()
        self._run_bg(job, on_done, self.L("PDFs jud rahi hain…", "Merging PDFs…"))

    def _bulk_move(self, files, copy=False):
        dest = QtWidgets.QFileDialog.getExistingDirectory(
            self, self.L("Kaunse folder me?", "Into which folder?"),
            self._panel_current_dir())
        if not dest:
            return

        def job():
            done = 0
            for f in files:
                try:
                    dst = os.path.join(dest, os.path.basename(f))
                    stem, ext = os.path.splitext(os.path.basename(f))
                    k = 2
                    while os.path.exists(dst):
                        dst = os.path.join(dest, "%s_%d%s" % (stem, k, ext)); k += 1
                    if copy:
                        shutil.copy2(f, dst)
                    else:
                        shutil.move(f, dst)
                    done += 1
                except Exception:
                    pass
            return done

        def on_done(res):
            if isinstance(res, Exception):
                self._warn("Failed:\n%s" % res); return
            self.status.showMessage(
                (self.L("📄 %d file copy ho gayi", "📄 Copied %d file(s)") if copy
                 else self.L("📁 %d file le jaayi gayi", "📁 Moved %d file(s)")) % res, 5000)
            self._refresh_files_root()
        self._run_bg(job, on_done, self.L("Ho raha hai…", "Working…"))

    def toggle_files_panel(self):
        vis = not self.files_panel.isVisible()
        self.files_panel.setVisible(vis)
        self._opts["show_files_panel"] = vis
        self._save_opts()
        if vis:
            # (v184) khulte hi zyada CHAUDI na ho — compact 230px se khule;
            # bachi jagah pages-column ko (user chahe to kheench kar badi kare)
            try:
                spl = self._body_split
                sizes = spl.sizes()
                idx = spl.indexOf(self.files_panel)
                pidx = spl.indexOf(self._pages_col)
                if 0 <= idx < len(sizes) and 0 <= pidx < len(sizes) and pidx != idx:
                    # (v194) default chaudai 290 — naam poore dikhein
                    extra = sizes[idx] - 290
                    sizes[pidx] += extra
                    sizes[idx] = 290
                    spl.setSizes(sizes)
            except Exception:
                pass
            # (v196) panel khulte hi list HAMESHA TOP se — beech se nahi
            try:
                QtCore.QTimer.singleShot(0, self.files_tree.scrollToTop)
            except Exception:
                pass
            # (v291) panel khulte hi search-index background me garam kar do —
            # taaki pehla keystroke bhi INSTANT result de (cold-build ka wait nahi)
            self._prewarm_files_index()

    def _fcnt(self, path):
        """(v192) Folder ke andar kitni files — card-view ke liye; cache ke
        saath (mtime badle to hi dobara ginta hai). Fail par -1."""
        try:
            mt = os.path.getmtime(path)
        except Exception:
            return -1
        c = self._fcnt_cache.get(path)
        if c is not None and c[1] == mt:
            return c[0]
        try:
            n = 0
            with os.scandir(path) as it:
                for e in it:
                    if e.is_file():
                        n += 1
                    if n > 999:
                        break
        except Exception:
            n = -1
        self._fcnt_cache[path] = (n, mt)
        if len(self._fcnt_cache) > 3000:
            self._fcnt_cache.clear()
        return n

