    def _nav_refresh_favs(self):
        """(v187) Sidebar me favourite FOLDERS ke seedhe buttons — jab bhi
        favourites badlein, list yahan bhi taaza ho jaati hai."""
        lay = getattr(self, "_nav_fav_lay", None)
        if lay is None:
            return
        while lay.count():
            it = lay.takeAt(0)
            w = it.widget()
            if w is not None:
                w.deleteLater()
        favs = [p for p in (self._opts.get("fav_folders") or []) if os.path.isdir(p)]
        mk = getattr(self, "_nav_mk_icon", None)

        def _go(pp):
            if not self.files_panel.isVisible():
                self.toggle_files_panel()
            self._jump_to_folder(pp)
        # (v221) SAARE favourites dikhao — koi '…N more' nahi. Bahut zyada hon
        # to buttons thode compact ho jaate hain taaki sab ek saath aa jaayen.
        _compact = len(favs) > 8
        for p in favs:
            nm = os.path.basename(p) or p
            if len(nm) > 20:
                nm = nm[:19] + "…"
            b = QtWidgets.QPushButton(" " + nm.replace("&", "&&"))
            if mk is not None:
                b.setIcon(mk("star", "#F59E0B"))
                b.setIconSize(QtCore.QSize(15 if _compact else 18, 15 if _compact else 18))
            if _compact:
                b.setStyleSheet("QPushButton{padding:3px 9px;font-size:11.5px;}")
