    def _pv_backup(self, paths):
        """Undo ke liye: edit se pehle in pages ki asli copy rakh lo (1 level)."""
        self._pv_undo_backup = {}
        for p in paths:
            try:
                fd, tmp = tempfile.mkstemp(suffix=os.path.splitext(p)[1] or ".png")
                os.close(fd)
                shutil.copy2(p, tmp)
                self._pv_undo_backup[p] = tmp
            except Exception:
                pass

    def _pv_undo(self):
        """Aakhri edit wapas lo — backup se pages bahal karo."""
        bak = getattr(self, "_pv_undo_backup", None)
        if not bak:
            self.status.showMessage(self.L("Undo ke liye kuch nahi", "Nothing to undo"), 3000)
            return
        n = 0
        for p, tmp in list(bak.items()):
            try:
                if os.path.exists(tmp):
                    shutil.copy2(tmp, p)
                    os.remove(tmp)
                    n += 1
            except Exception:
                pass
        self._pv_undo_backup = {}
        self._refresh_all_thumbs()
        self._update_preview_panel()
        self.status.showMessage(self.L("↶ %d page wapas aaye" % n,
                                       "↶ Reverted %d page(s)" % n), 3000)

    # ================= Unified multi-level Undo / Redo =================
    # One history for page EDITS (rotate/crop/deskew/enhance/whiten…) and
    # DELETES. Each edit stores a small before+after file snapshot in a cache;
    # undo/redo just copy the right snapshot back. Deletes store the item so the
    # page (and its name) comes back. Ctrl+Z undo, Ctrl+Shift+Z / Ctrl+Y redo.
    def _hist_dir(self):
        d = getattr(self, "_histdir", None)
        if not d:
            d = os.path.join(self._tmpdir, "_history")
            try:
                os.makedirs(d, exist_ok=True)
            except Exception:
                pass
            self._histdir = d
        return d

    def _hist_snapshot(self, paths):
        """Copy each page file into the history cache; return {path: copy}."""
        snap = {}
        for p in paths:
            try:
                fd, tmp = tempfile.mkstemp(suffix=os.path.splitext(p)[1] or ".png", dir=self._hist_dir())
                os.close(fd)
                shutil.copy2(p, tmp)
                snap[p] = tmp
            except Exception:
                pass
        return snap

    def _hist_free(self, entry):
        try:
            for key in ("before", "after"):
                for tmp in (entry.get(key) or {}).values():
                    if tmp and os.path.exists(tmp):
                        try:
                            os.remove(tmp)
                        except Exception:
                            pass
        except Exception:
            pass

    def _hist_record(self, entry):
        """Push a new undoable action; clears the redo branch (standard model)."""
        if not hasattr(self, "_hist"):
            self._hist, self._hist_redo = [], []
        self._hist.append(entry)
        while len(self._hist) > getattr(self, "_hist_max", 25):
            self._hist_free(self._hist.pop(0))
        for e in self._hist_redo:
            self._hist_free(e)
        self._hist_redo = []

    def _hist_undo(self):
        if not getattr(self, "_hist", None):
            if getattr(self, "_undo_stack", None):
                return self.undo_delete()        # legacy fallback
            self.status.showMessage(self.L("Undo ke liye kuch nahi", "Nothing to undo"), 2500)
            return
        entry = self._hist.pop()
        self._hist_apply(entry, "undo")
        self._hist_redo.append(entry)

    def _hist_redo_do(self):
        if not getattr(self, "_hist_redo", None):
            self.status.showMessage(self.L("Redo ke liye kuch nahi", "Nothing to redo"), 2500)
            return
        entry = self._hist_redo.pop()
        self._hist_apply(entry, "redo")
        self._hist.append(entry)

    def _hist_apply(self, entry, direction):
        t = entry.get("type")
        if t == "edit":
            src = entry["before"] if direction == "undo" else entry["after"]
            n = 0
            for path, tmp in (src or {}).items():
                try:
                    if os.path.exists(tmp):
                        shutil.copy2(tmp, path)
                        n += 1
                except Exception:
                    pass
            try:
                self._refresh_all_thumbs()
                self._update_preview_panel()
            except Exception:
                pass
            self._dirty = True
            self.status.showMessage(("↶ " if direction == "undo" else "↷ ")
                                    + (self.L("%d page badle", "%d page(s) changed") % n), 2500)
        elif t == "delete":
            if direction == "undo":
                for it in sorted(entry.get("items", []), key=lambda x: x.get("row", 0)):
                    self._hist_reinsert(it)
            else:
                for it in entry.get("items", []):
                    self._hist_remove_path(it.get("path"))
            try:
                self._renumber_pages()
                self._update_status()
                self._update_empty_state()
            except Exception:
                pass
            self._dirty = True
            self.status.showMessage(("↶ " if direction == "undo" else "↷ ")
                                    + self.L("delete wapas", "delete reverted"), 2500)
        elif t == "reorder":
            self._reorder_to(entry["before"] if direction == "undo" else entry["after"])
            try:
                self._renumber_pages()
                self._update_preview_panel()
            except Exception:
                pass
            self._dirty = True
            self.status.showMessage(("↶ " if direction == "undo" else "↷ ")
                                    + self.L("kram wapas", "order reverted"), 2500)

    def _reorder_to(self, paths):
        """Reorder the page list so items follow the given path order (used by
        undo/redo of a drag-reorder). Items not in the list are ignored."""
        items = {}
        for i in range(self.list.count()):
            it = self.list.item(i)
            items[it.data(QtCore.Qt.UserRole)] = it
        for i in reversed(range(self.list.count())):
            self.list.takeItem(i)
        for p in paths:
            it = items.pop(p, None)
            if it is not None:
                self.list.addItem(it)
        for it in items.values():            # any leftovers (shouldn't happen) go last
            self.list.addItem(it)

    def _hist_reinsert(self, it):
        path = it.get("path")
        if not path or not os.path.exists(path):
            return
        try:
            icon = QtGui.QIcon(self._make_thumb(path))
        except Exception:
            icon = QtGui.QIcon()
        item = QtWidgets.QListWidgetItem(icon, "")
        item.setData(QtCore.Qt.UserRole, path)
        if it.get("title"):
            item.setData(TITLE_ROLE, it["title"])
        item.setTextAlignment(QtCore.Qt.AlignHCenter)
        self.list.insertItem(min(int(it.get("row", self.list.count())), self.list.count()), item)

    def _hist_remove_path(self, path):
        for i in range(self.list.count()):
            if self.list.item(i).data(QtCore.Qt.UserRole) == path:
                self.list.takeItem(i)
                return

    def _edit_targets(self):
        """Edit kispar lage: apply-all on ho to SAB pages, warna current."""
        if getattr(self, "pv_apply_all", None) and self.pv_apply_all.isChecked():
            paths = self._ordered_paths()
            return paths, True
        item = self._current_item_or_warn()
        if not item:
            return [], False
        return [item.data(QtCore.Qt.UserRole)], False

    def _refresh_all_thumbs(self):
        for i in range(self.list.count()):
            try:
                self._refresh_item(self.list.item(i))
            except Exception:
                pass
        self._pv_build_filmstrip()

    def _edit_current_bg(self, transform, busy_msg):
        """Image-transform BACKGROUND me — UI nahi rukti. Apply-all ho to sab
        pages par; undo ke liye pehle backup. transform: PIL.Image(RGB)->Image."""
        paths, allmode = self._edit_targets()
        if not paths:
            return
        self._pv_backup(paths)                       # legacy single-level undo
        _hist_before = self._hist_snapshot(paths)    # unified multi-level history: 'before'

        def job():
            for p in paths:
                try:
                    with Image.open(p) as im:
                        transform(im.convert("RGB")).save(p, "PNG")
                except Exception:
                    pass
            return True

        def on_done(res):
            if isinstance(res, Exception):
                self._warn(self.L("Edit fail: %s", "Edit failed: %s") % res)
                return
            if allmode:
                self._refresh_all_thumbs()
            else:
                try:
                    self._refresh_item(self.list.currentItem())
                except Exception:
                    pass
                self._pv_build_filmstrip()
            self._update_preview_panel()
            self._dirty = True
            # record this edit (before + after) for unified undo/redo
            try:
                self._hist_record({"type": "edit", "before": _hist_before,
                                   "after": self._hist_snapshot(paths)})
            except Exception:
                pass
        self._run_bg(job, on_done, busy_msg)

    def deskew_current(self):
        self._edit_current_bg(lambda im: deskew(im),
                              self.L("Seedha kar rahe hain…", "Straightening…"))

    def dewarp_current(self):
        """Kitab/register ke mude page ki tedhi lines seedhi (book flatten)."""
        self._edit_current_bg(lambda im: dewarp_page(im),
                              self.L("Book page seedha kar rahe hain…", "Flattening book page…"))

    def enhance_current_page(self):
        self._edit_current_bg(lambda im: auto_enhance(im),
                              self.L("Saaf kar rahe hain…", "Enhancing…"))

    def whiten_current_page(self):
        self._edit_current_bg(lambda im: whiten_dark_background(im),
                              self.L("Backing safed kar rahe hain…", "Whitening…"))

    def rotate_any(self):
        """Kisi bhi angle (jaise 2°, -3°) par ghumakar seedha karo."""
        deg, ok = QtWidgets.QInputDialog.getDouble(
            self, self.L("Kitne degree?", "How many degrees?"),
            self.L("Ghumao (+ = daayein, − = baayein):", "Rotate (+ = right, − = left):"),
            0.0, -180.0, 180.0, 1)
        if not ok or abs(deg) < 0.01:
            return
        self._edit_current_bg(
            lambda im: im.rotate(-deg, expand=True, fillcolor=(255, 255, 255),
                                 resample=Image.BICUBIC),
            self.L("Ghuma rahe hain…", "Rotating…"))

    def _to_mode(self, mode):
        """Page ko B&W ('1') / Grayscale ('L') me badlo (RGB me wapas dikhega)."""
        def _t(im):
            if mode == "1":
                return im.convert("L").point(lambda x: 255 if x > 150 else 0, "1").convert("RGB")
            if mode == "L":
                return im.convert("L").convert("RGB")
            return im
        self._edit_current_bg(_t, self.L("Badal rahe hain…", "Converting…"))

    def duplicate_current_page(self):
        """Current page ki ek nakal uske theek baad jod do."""
        item = self._current_item_or_warn()
        if not item:
            return
        src = item.data(QtCore.Qt.UserRole)
        try:
            fd, dst = tempfile.mkstemp(suffix=os.path.splitext(src)[1] or ".png", dir=self._tmpdir)
            os.close(fd)
            shutil.copy2(src, dst)
        except Exception as exc:
            self._warn("Copy failed: %s" % exc); return
        row = self.list.row(item)
        self._add_item_for_path(dst)               # end me add hota hai
        # use theek current ke baad le aao
        last = self.list.count() - 1
        it2 = self.list.takeItem(last)
        self.list.insertItem(row + 1, it2)
        self.list.setCurrentItem(it2)
        self._renumber_pages()
        self._pv_build_filmstrip()
        self.status.showMessage(self.L("⧉ Page ki nakal ban gayi", "⧉ Page duplicated"), 3000)

    def _pv_translate(self):
        txt = self.pv_text.toPlainText().strip()
        if not txt:
            self._pv_read_text()
            QtCore.QTimer.singleShot(1200, self._pv_translate_now)
            return
        self._pv_translate_now()

    def _pv_translate_now(self):
        txt = self.pv_text.toPlainText().strip()
        if not txt:
            self.status.showMessage(self.L("Pehle 'Text padho' dabao", "Press 'Read text' first"), 3000)
            return

        def job():
            try:
                import urllib.request as U, urllib.parse as P, json as J, ssl
                ctx = ssl._create_unverified_context()
                q = P.urlencode({"client": "gtx", "sl": "auto", "tl": "en",
                                 "dt": "t", "q": txt[:1800]})
                url = "https://translate.googleapis.com/translate_a/single?" + q
                r = U.urlopen(U.Request(url, headers={"User-Agent": "Mozilla/5.0"}),
                              timeout=15, context=ctx)
                data = J.loads(r.read().decode("utf-8", "ignore"))
                return "".join(seg[0] for seg in data[0] if seg and seg[0])
            except Exception as e:
                return e

        def done(res):
            if isinstance(res, Exception) or not res:
                self.status.showMessage(self.L("Translate nahi ho paya", "Translate failed"), 3000)
                return
            self.pv_tabs.setCurrentIndex(1)
            self.pv_text.setPlainText(res)
        self._run_bg(job, done, self.L("Translate ho raha hai…", "Translating…"))

    def _pv_strip_click(self, item):
        r = item.data(QtCore.Qt.UserRole)
        # (v303) previewed PDF ka page — us page tak preview scroll karo
        if isinstance(r, tuple) and len(r) == 2 and r[0] == "pdfpage":
            try:
                frac = float(r[1])
                bar = self.pv_scroll.verticalScrollBar()
                bar.setValue(int(frac * self.pv_img.height()))
            except Exception:
                pass
            return
        if isinstance(r, int) and 0 <= r < self.list.count():
            self.list.setCurrentRow(r)

    # ---- (v304/v305) filmstrip ko maus se chhota/bada karo ----
    # Do alag YAAD size: file-preview me BADI (auto), scanned working-set me chhoti.
    def _file_strip_h(self):
        return int(self._opts.get("pv_strip_h_file", 120) or 120)

    def _ws_strip_h(self):
        return int(self._opts.get("pv_strip_h", 60) or 60)

    def _set_strip_geom(self, h):
        """Sirf height + icon/grid size lagao (koi rebuild/save nahi)."""
        try:
            h = max(46, min(320, int(h)))
        except Exception:
            h = 60
        self._pv_strip_h = h
        try:
            self.pv_strip.setFixedHeight(h)
            ih = max(30, h - 16)                 # icon height
            iw = max(24, int(ih * 0.75))         # portrait pages
            self.pv_strip.setIconSize(QtCore.QSize(iw, ih))
            self.pv_strip.setGridSize(QtCore.QSize(iw + 16, h - 2))
        except Exception:
            pass
        return h

    def _apply_pv_strip_size(self, h, rebuild=True, save=True):
        """Filmstrip resize (drag/ctrl-scroll/double-click se). save=True par
        current mode ke hisaab se yaad: file-preview -> pv_strip_h_file, warna
        scanned working-set -> pv_strip_h."""
        h = self._set_strip_geom(h)
        in_file = bool(getattr(self, "_pv_showing_file", None))
        if save:
            self._opts["pv_strip_h_file" if in_file else "pv_strip_h"] = h
            try:
                self._save_opts()
            except Exception:
                pass
        if rebuild:
            try:
                if in_file and getattr(self, "_pv_page_offsets", None):
                    self._pv_fill_pdf_strip(self._pv_page_offsets)
                else:
                    self._pv_build_filmstrip()
            except Exception:
                pass

    def _pv_strip_handle_press(self, e):
        if e.button() == QtCore.Qt.LeftButton:
            self._pv_strip_drag = (e.globalY(), self._pv_strip_h)
            e.accept()

    def _pv_strip_handle_move(self, e):
        d = getattr(self, "_pv_strip_drag", None)
        if d and (e.buttons() & QtCore.Qt.LeftButton):
            start_y, start_h = d
            delta = start_y - e.globalY()        # oopar kheencho = badi
            self._apply_pv_strip_size(start_h + delta, rebuild=False, save=False)
            e.accept()

    def _pv_strip_handle_release(self, e):
        if getattr(self, "_pv_strip_drag", None) is not None:
            self._pv_strip_drag = None
            self._apply_pv_strip_size(self._pv_strip_h, rebuild=True, save=True)
            e.accept()

    def _pv_fill_pdf_strip(self, offsets):
        """(v303) Previewed PDF ke SAARE pages ko filmstrip me 1,2,3… dikhao —
        har thumb lambi preview-image se cut karke banti hai (PDF dobara nahi
        kholni padti). Kisi par click = us page tak scroll."""
        if not hasattr(self, "pv_strip"):
            return
        # (v305) file preview me AUTO-BADI patti (uski apni yaad size)
        self._set_strip_geom(self._file_strip_h())
        try:
            self.pv_strip.blockSignals(True)
            self.pv_strip.clear()
            pm = getattr(self, "_pv_pm", None)
            if pm is None or pm.isNull() or not offsets:
                self.pv_strip.blockSignals(False)
                return
            H = pm.height(); W = pm.width()
            n = len(offsets)
            for i, frac in enumerate(offsets):
                y0 = int(frac * H)
                y1 = int(offsets[i + 1] * H) if i + 1 < n else H
                if y1 - y0 < 4:
                    y1 = min(H, y0 + 4)
                crop = pm.copy(0, y0, W, y1 - y0)
                _isz = self.pv_strip.iconSize()
                _iw = max(24, _isz.width()); _ih = max(30, _isz.height())
                icon = crop.scaled(_iw, _ih, QtCore.Qt.KeepAspectRatio,
                                   QtCore.Qt.SmoothTransformation)
                it = QtWidgets.QListWidgetItem(QtGui.QIcon(icon), str(i + 1))
                it.setData(QtCore.Qt.UserRole, ("pdfpage", frac))
                it.setTextAlignment(QtCore.Qt.AlignHCenter | QtCore.Qt.AlignBottom)
                it.setToolTip(self.L("Page %d — click karke yahan jao" % (i + 1),
                                     "Page %d — click to jump here" % (i + 1)))
                self.pv_strip.addItem(it)
            if self.pv_strip.count():
                self.pv_strip.setCurrentRow(0)
            self.pv_strip.blockSignals(False)
        except Exception:
            try:
                self.pv_strip.blockSignals(False)
            except Exception:
                pass

    def _pv_build_filmstrip(self):
        if not hasattr(self, "pv_strip"):
            return
        # (v303) agar abhi koi SAVED file preview ho rahi hai to uski apni
        # filmstrip (PDF ke pages) ko working-set se overwrite mat karo
        if getattr(self, "_pv_showing_file", None):
            return
        # (v305) scanned working-set me apni (chhoti) yaad size
        self._set_strip_geom(self._ws_strip_h())
        try:
            self.pv_strip.blockSignals(True)
            self.pv_strip.clear()
            for i in range(self.list.count()):
                src = self.list.item(i)
                it = QtWidgets.QListWidgetItem(src.icon(), str(i + 1))
                it.setData(QtCore.Qt.UserRole, i)
                it.setTextAlignment(QtCore.Qt.AlignHCenter | QtCore.Qt.AlignBottom)
                self.pv_strip.addItem(it)
            cur = self.list.currentRow()
            if 0 <= cur < self.pv_strip.count():
                self.pv_strip.setCurrentRow(cur)
            self.pv_strip.blockSignals(False)
        except Exception:
            pass

